  GeneralRecipe(id: "Se-3", title: "Karnabahar fırın", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar", "3 yemek kaşığı yoğurt", "1 yumurta", "3 yemek kaşığı rendelenmiş kaşar", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C ısıtın; karnabaharı çiçeklerine ayırın.", "Karnabaharı buharda 8 dakika ön pişirin.", "Yoğurt ve yumurtayı çırpıp karnabaharlarla harmanlayın.", "Üzerine kaşar serpip 20 dakika, üzeri kızarana kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "Se-4", title: "Ispanak yemeği", category: "Sebze yemekleri", ingredients: ["500 g ıspanak", "1 soğan", "2 yemek kaşığı zeytinyağı", "2 yemek kaşığı pirinç", "Yarım su bardağı su"], steps: ["Ispanağı birkaç kez yıkayıp iri doğrayın.", "Soğanı yağda yumuşatın.", "Ispanak, yıkanmış pirinç ve suyu ekleyin.", "Pirinç yumuşayana ve ıspanak tamamen pişene kadar 20 dakika pişirin."], minutes: 30),
  GeneralRecipe(id: "Se-5", title: "Bamya yemeği", category: "Sebze yemekleri", ingredients: ["400 g bamya", "2 domates", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu", "Yarım su bardağı su"], steps: ["Bamyaları yıkayıp saplarını koni biçiminde ayıklayın.", "Soğanı yağda yumuşatıp rendelenmiş domatesleri ekleyin.", "Bamyaları, limon suyunu ve suyu ilave edin.", "Kapağı kapalı şekilde bamyalar yumuşayana kadar 25-30 dakika pişirin."], minutes: 45),
  GeneralRecipe(id: "Se-6", title: "Pırasa yemeği", category: "Sebze yemekleri", ingredients: ["4 pırasa", "2 havuç", "3 yemek kaşığı zeytinyağı", "2 yemek kaşığı pirinç", "1 su bardağı su", "Yarım limon"], steps: ["Pırasaları iyice yıkayıp halka halka doğrayın; havuçları dilimleyin.", "Havuçları zeytinyağında 3 dakika soteleyin.", "Pırasa, yıkanmış pirinç ve suyu ekleyin.", "Kısık ateşte 25-30 dakika pişirip limonla servis edin."], minutes: 40),
  GeneralRecipe(id: "Se-7", title: "Zeytinyağlı enginar ve bezelye", category: "Sebze yemekleri", ingredients: ["4 enginar çanağı", "1 su bardağı bezelye", "1 havuç", "1 küçük soğan", "3 yemek kaşığı zeytinyağı", "1 limonun suyu", "1 su bardağı su"], steps: ["Soğanı yemeklik, havucu küp doğrayın.", "Zeytinyağında soğan ve havucu 4 dakika soteleyin.", "Enginarları ve bezelyeyi ekleyip limonlu suyu dökün.", "Kapağı kapalı şekilde enginarlar yumuşayana kadar 25-30 dakika pişirin."], minutes: 45),
  GeneralRecipe(id: "Se-8", title: "Zeytinyağlı bezelye ve havuç", category: "Sebze yemekleri", ingredients: ["2 su bardağı bezelye", "2 havuç", "1 patates", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su"], steps: ["Soğanı ince doğrayın, havuç ve patatesi küp kesin.", "Soğanı yağda 3 dakika soteleyin.", "Havuç, patates ve bezelyeyi ekleyip karıştırın.", "Sıcak suyu ekleyerek kapağı kapalı 25-30 dakika sebzeler yumuşayana kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "Se-9", title: "Fırında kök sebzeler", category: "Sebze yemekleri", ingredients: ["2 havuç", "2 patates", "1 tatlı patates", "1 pancar", "3 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 200°C’ye ısıtın.", "Sebzeleri soyup eşit kalınlıkta dilimleyin.", "Yağ ve kekikle harmanlayıp tepsiye tek kat dizin.", "30-40 dakika, arada çevirerek yumuşayıp kızarana kadar pişirin."], minutes: 50),
  GeneralRecipe(id: "Ba-0", title: "Kuru fasulye", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı kuru fasulye", "1 soğan", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "4 su bardağı sıcak su"], steps: ["Fasulyeleri bir gece önceden ıslatıp suyunu süzün.", "Fasulyeleri taze suda 20 dakika ön haşlayıp süzün.", "Soğanı yağda kavurun; salçayı ekleyip 1 dakika çevirin.", "Fasulyeleri ve sıcak suyu ekleyin; fasulyeler tamamen yumuşayana kadar 45-60 dakika pişirin."], minutes: 90),
  GeneralRecipe(id: "Ba-1", title: "Nohut yemeği", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı kuru nohut", "1 soğan", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "4 su bardağı sıcak su"], steps: ["Nohutları bir gece ıslatın ve suyunu süzün.", "Nohutları taze suda ön haşlayın.", "Soğanı yağda kavurup salçayı ekleyin.", "Nohutları ve sıcak suyu ekleyerek tamamen yumuşayana kadar 50-70 dakika pişirin."], minutes: 100),
  GeneralRecipe(id: "Ba-2", title: "Yeşil mercimek yemeği", category: "Bakliyat yemekleri", ingredients: ["1,5 su bardağı yeşil mercimek", "1 soğan", "1 havuç", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Mercimeği yıkayıp 10 dakika ön haşlayın ve süzün.", "Soğan ve havucu doğrayıp yağda soteleyin.", "Salçayı ekleyip kısa süre kavurun.", "Mercimeği ve suyu ekleyerek 25-30 dakika yumuşayana kadar pişirin."], minutes: 50),
  GeneralRecipe(id: "Ba-3", title: "Barbunya pilaki", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış barbunya", "1 havuç", "1 patates", "1 soğan", "3 yemek kaşığı zeytinyağı", "1 domates", "1 su bardağı su"], steps: ["Soğanı doğrayıp yağda yumuşatın.", "Havuç ve patatesi küp doğrayıp 5 dakika soteleyin.", "Rendelenmiş domates, barbunya ve suyu ekleyin.", "Kısık ateşte sebzeler yumuşayana kadar 25 dakika pişirin; ılıtarak servis edin."], minutes: 40),
  GeneralRecipe(id: "Ba-4", title: "Kırmızı mercimek köftesi", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı kırmızı mercimek", "1 su bardağı ince bulgur", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı biber salçası", "3 dal taze soğan", "Yarım limon"], steps: ["Mercimeği 2,5 su bardağı suda iyice yumuşayana kadar pişirin.", "Ocaktan alıp bulguru ekleyin ve kapağı kapalı 20 dakika dinlendirin.", "Soğanı yağda kavurup salçayla birlikte mercimek karışımına katın.", "İnce doğranmış taze soğan ve limonu ekleyip yoğurun, şekil verin."], minutes: 55),
  GeneralRecipe(id: "Ba-5", title: "Börülce salatası", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış börülce", "1 kırmızı biber", "3 dal taze soğan", "Yarım demet maydanoz", "2 yemek kaşığı zeytinyağı", "1 limonun suyu"], steps: ["Haşlanmış börülceyi süzüp soğutun.", "Biberi, taze soğanı ve maydanozu ince doğrayın.", "Bütün malzemeleri geniş kapta birleştirin.", "Zeytinyağı ve limonla harmanlayıp servis edin."], minutes: 20),
  GeneralRecipe(id: "Ba-6", title: "Nohutlu ıspanak", category: "Bakliyat yemekleri", ingredients: ["400 g ıspanak", "1,5 su bardağı haşlanmış nohut", "1 soğan", "1 domates", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı su"], steps: ["Ispanağı bol suyla yıkayıp doğrayın.", "Soğanı yağda kavurun, doğranmış domatesi ekleyin.", "Nohut ve ıspanağı ekleyip karıştırın.", "Suyu ilave ederek 15-20 dakika ıspanak yumuşayana kadar pişirin."], minutes: 35),
  GeneralRecipe(id: "Ba-7", title: "Fasulye piyazı", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış kuru fasulye", "1 kırmızı soğan", "1 domates", "Yarım demet maydanoz", "3 yemek kaşığı zeytinyağı", "1 limonun suyu"], steps: ["Haşlanmış fasulyeyi süzüp soğutun.", "Soğanı ince piyazlık, domatesi küp doğrayın.", "Fasulye, soğan, domates ve maydanozu birleştirin.", "Limon ve zeytinyağıyla harmanlayın."], minutes: 15),
  GeneralRecipe(id: "Ba-8", title: "Mercimekli bulgur pilavı", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı pilavlık bulgur", "Yarım su bardağı yeşil mercimek", "1 soğan", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Mercimeği 15-20 dakika hafif diri kalacak şekilde haşlayıp süzün.", "Soğanı yağda kavurun.", "Bulgur ve mercimeği ekleyip 2 dakika karıştırın.", "Sıcak suyu ekleyip kısık ateşte suyunu çekene kadar pişirin, 10 dakika dinlendirin."], minutes: 45),
  GeneralRecipe(id: "Ba-9", title: "Nohutlu kabak yemeği", category: "Bakliyat yemekleri", ingredients: ["3 kabak", "1 su bardağı haşlanmış nohut", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı su"], steps: ["Soğanı yağda soteleyin.", "Kabakları yarım ay doğrayın, domatesleri rendeleyin.", "Kabak, domates ve nohudu tencereye ekleyin.", "Suyu katıp kabaklar yumuşayana kadar 20-25 dakika pişirin."], minutes: 35),
  GeneralRecipe(id: "Ma-0", title: "Domatesli makarna", category: "Makarnalar", ingredients: ["250 g makarna", "3 domates", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru fesleğen"], steps: ["Makarnayı bol kaynar suda paket süresine göre haşlayın.", "Sarımsağı yağda kısa süre çevirip rendelenmiş domatesi ekleyin.", "Sosu 10 dakika koyulaşana kadar pişirip fesleğen katın.", "Süzülen makarnayı sosla karıştırıp sıcak servis edin."], minutes: 25),
  GeneralRecipe(id: "Ma-1", title: "Fesleğenli makarna", category: "Makarnalar", ingredients: ["250 g makarna", "1 demet fesleğen", "2 yemek kaşığı zeytinyağı", "2 yemek kaşığı ceviz", "1 diş sarımsak", "2 yemek kaşığı rendelenmiş peynir"], steps: ["Makarnayı paket süresine göre haşlayın.", "Fesleğen, ceviz, sarımsak ve yağı mutfak robotunda çekin.", "Sosa birkaç kaşık makarna suyu ekleyip açın.", "Makarnayı sos ve peynirle harmanlayın."], minutes: 25),
  GeneralRecipe(id: "Ma-2", title: "Mantarlı makarna", category: "Makarnalar", ingredients: ["250 g makarna", "250 g mantar", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "1 diş sarımsak", "Yarım çay bardağı makarna suyu"], steps: ["Makarnayı kaynar suda haşlayın.", "Mantarları dilimleyip soğanla birlikte yağda suyunu çekene kadar soteleyin.", "Sarımsağı ekleyip 1 dakika karıştırın.", "Makarna suyu ve haşlanmış makarnayı ekleyip harmanlayın."], minutes: 30),
  GeneralRecipe(id: "Ma-3", title: "Sebzeli erişte", category: "Makarnalar", ingredients: ["250 g erişte", "1 kabak", "1 havuç", "1 kırmızı biber", "2 yemek kaşığı zeytinyağı"], steps: ["Erişteyi kaynar suda yumuşayana kadar haşlayıp süzün.", "Havuç, kabak ve biberi ince şeritler hâlinde doğrayın.", "Sebzeleri yağda 8-10 dakika yumuşayana kadar soteleyin.", "Erişteyi sebzelerle birleştirip 2 dakika karıştırın."], minutes: 30),
  GeneralRecipe(id: "Ma-4", title: "Bulgur pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "1 soğan", "1 domates", "1 yemek kaşığı tereyağı", "1 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Soğanı yağlarla birlikte yumuşayana kadar kavurun.", "Rendelenmiş domatesi ekleyip suyunu çektirin.", "Yıkanmış bulguru ekleyip 1 dakika karıştırın.", "Sıcak suyu döküp kapağı kapalı kısık ateşte 15 dakika pişirin; dinlendirin."], minutes: 30),
  GeneralRecipe(id: "Ma-5", title: "Pirinç pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pirinç", "1,5 su bardağı sıcak su", "1 yemek kaşığı tereyağı", "1 yemek kaşığı zeytinyağı", "Yarım çay kaşığı tuz"], steps: ["Pirinci nişastası gidene kadar yıkayıp süzün.", "Yağları tencerede ısıtıp pirinci 3 dakika kavurun.", "Sıcak su ve tuzu ekleyip kapağı kapatın.", "Kısık ateşte suyunu çekene kadar pişirin; 10 dakika dinlendirin."], minutes: 30),
  GeneralRecipe(id: "Ma-6", title: "Kinoalı sebze pilavı", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı kinoa", "1 havuç", "1 kabak", "1 kırmızı biber", "2 yemek kaşığı zeytinyağı", "2 su bardağı su"], steps: ["Kinoayı ince süzgeçte bol suyla yıkayın.", "Doğranmış sebzeleri yağda 5 dakika soteleyin.", "Kinoayı ve suyu ekleyip kaynatın.", "Kapağı kapalı kısık ateşte 15 dakika pişirip 5 dakika dinlendirin."], minutes: 35),
  GeneralRecipe(id: "Ma-7", title: "Karabuğday pilavı", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı karabuğday", "1 küçük soğan", "1 havuç", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Karabuğdayı yıkayıp süzün.", "Doğranmış soğan ve havucu yağda soteleyin.", "Karabuğdayı ve sıcak suyu ekleyin.", "Kısık ateşte taneler yumuşayıp suyu çekene kadar 15-20 dakika pişirin."], minutes: 35),
  GeneralRecipe(id: "Ma-8", title: "Fırın makarna", category: "Makarnalar", ingredients: ["250 g fırın makarna", "2 su bardağı süt", "2 yemek kaşığı un", "2 yemek kaşığı tereyağı", "1 su bardağı rendelenmiş kaşar"], steps: ["Makarnayı hafif diri kalacak şekilde haşlayın.", "Tereyağında unu 1 dakika kavurun, sütü azar azar ekleyerek koyulaştırın.", "Makarnayı sosla harmanlayıp fırın kabına alın.", "Kaşar serpip 190°C fırında 20-25 dakika kızarana kadar pişirin."], minutes: 50),
  GeneralRecipe(id: "Ma-9", title: "Nohutlu kuskus", category: "Dünya mutfağı", ingredients: ["1 su bardağı kuskus", "1 su bardağı haşlanmış nohut", "1 kırmızı biber", "1 yemek kaşığı zeytinyağı", "2 su bardağı su", "Yarım limon"], steps: ["Kuskusu kaynar suda paket süresine göre haşlayıp süzün.", "Biberi küçük doğrayıp yağda 5 dakika soteleyin.", "Nohudu ekleyip ısıtın.", "Kuskusla karıştırıp limon suyu ekleyerek servis edin."], minutes: 25),
  GeneralRecipe(id: "Ta-0", title: "Fırında tavuk, patates", category: "Tavuk yemekleri", ingredients: ["600 g tavuk baget", "3 patates", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik", "1 çay kaşığı kırmızı toz biber"], steps: ["Fırını 200°C’ye ısıtın; patatesleri iri dilimleyin.", "Tavuk bagetleri ve patatesleri yağ, kekik ve biberle harmanlayıp tepsiye tek kat dizin.", "Yaklaşık 45–55 dakika pişirin; tavukların en kalın yerinde iç sıcaklığın 74°C’ye ulaştığını kontrol edin."], minutes: 65),
  GeneralRecipe(id: "Ta-1", title: "Sebzeli tavuk sote", category: "Tavuk yemekleri", ingredients: ["400 g tavuk göğsü", "1 kabak", "1 kırmızı biber", "1 soğan", "2 yemek kaşığı zeytinyağı"], steps: ["Tavuğu ince şeritlere; soğan, kabak ve biberi eş boyda doğrayın.", "Tavada yağı ısıtıp tavuğu yüksek ateşte renk alana kadar çevirin.", "Soğan ve biberi ekleyip 5 dakika, ardından kabağı ekleyip 6–8 dakika daha soteleyin.", "Tavuğun iç sıcaklığı 74°C’ye ulaştığında servis edin."], minutes: 30),
  GeneralRecipe(id: "Ta-2", title: "Limonlu tavuk", category: "Tavuk yemekleri", ingredients: ["500 g tavuk göğsü", "1 limonun suyu", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik"], steps: ["Limon suyu, ezilmiş sarımsak, zeytinyağı ve kekiği karıştırın.", "Tavuğu sosa bulayıp buzdolabında 20 dakika bekletin.", "Tavada orta ateşte iki yüzünü kızartın; kalınlığına göre 12–18 dakika pişirin.", "İç sıcaklık 74°C olduğunda ocaktan alın; 3 dakika dinlendirin."], minutes: 45),
  GeneralRecipe(id: "Ta-3", title: "Tavuklu pilav", category: "Tavuk yemekleri", ingredients: ["300 g tavuk göğsü", "1 su bardağı pirinç", "1,5 su bardağı tavuk suyu", "1 yemek kaşığı tereyağı", "1 yemek kaşığı zeytinyağı"], steps: ["Tavuğu suda tamamen pişene kadar haşlayıp didikleyin; suyunu ayırın.", "Pirinci yıkayıp süzün, yağlarla 3 dakika kavurun.", "Ölçülü tavuk suyunu ekleyip kısık ateşte suyunu çekene kadar pişirin.", "Didiklenmiş tavuğu ekleyip kapağı kapalı 10 dakika dinlendirin."], minutes: 50),
  GeneralRecipe(id: "Ta-4", title: "Tavuklu makarna", category: "Tavuk yemekleri", ingredients: ["300 g tavuk göğsü", "250 g makarna", "2 domates", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı"], steps: ["Makarnayı paketteki süreye göre haşlayın.", "Küp doğranmış tavuğu yağda pişirin; iç sıcaklığının 74°C’ye ulaştığını kontrol edin.", "Sarımsak ve rendelenmiş domatesi ekleyip 8 dakika kaynatın.", "Makarnayı süzüp tavuklu sosla karıştırın."], minutes: 35),
  GeneralRecipe(id: "Ta-5", title: "Tavuk şiş", category: "Tavuk yemekleri", ingredients: ["500 g tavuk göğsü", "1 kırmızı biber", "1 yeşil biber", "2 yemek kaşığı yoğurt", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik"], steps: ["Tavuğu ve biberleri şişe uygun küpler halinde doğrayın.", "Yoğurt, yağ ve kekikle tavuğu karıştırıp buzdolabında 30 dakika bekletin.", "Tavuk ve biberleri şişlere dizip 200°C fırında yaklaşık 20–25 dakika pişirin.", "Tavuğun iç sıcaklığı 74°C’ye ulaştığında servis edin."], minutes: 65),
  GeneralRecipe(id: "Ta-6", title: "Yoğurtlu tavuk", category: "Tavuk yemekleri", ingredients: ["400 g tavuk göğsü", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 çay kaşığı kırmızı biber"], steps: ["Tavuğu küçük küpler halinde doğrayıp yağda tamamen pişirin.", "Yoğurtla ezilmiş sarımsağı ayrı kapta karıştırın.", "Pişmiş tavuğu 3 dakika dinlendirip yoğurtlu sosla buluşturun.", "Üzerine hafifçe kızdırılmış kırmızı biberli yağ gezdirin."], minutes: 30),
  GeneralRecipe(id: "Ta-7", title: "Tavuklu sebze güveç", category: "Tavuk yemekleri", ingredients: ["500 g tavuk but kuşbaşı", "2 patates", "1 patlıcan", "2 domates", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su"], steps: ["Fırını 190°C’ye ısıtın; sebzeleri eş boyda doğrayın.", "Tavuk ve sebzeleri güveç kabına alın; yağ ve suyu ekleyip karıştırın.", "Kapağı kapalı 40 dakika, ardından kapağı açık 15 dakika pişirin.", "Tavukların iç sıcaklığı 74°C’ye ulaştığında servis edin."], minutes: 70),
  GeneralRecipe(id: "Ta-8", title: "Tavuk köftesi", category: "Tavuk yemekleri", ingredients: ["500 g tavuk kıyması", "1 küçük soğan", "1 yumurta", "3 yemek kaşığı galeta unu", "1 yemek kaşığı zeytinyağı", "Yarım demet maydanoz"], steps: ["Soğanı rendeleyip suyunu sıkın; maydanozu kıyın.", "Tavuk kıyması, yumurta, galeta unu ve sebzeleri yoğurun.", "Karışımdan küçük köfteler yapıp yağlı kâğıt serili tepsiye dizin.", "200°C fırında yaklaşık 20–25 dakika, iç sıcaklık 74°C’ye ulaşana kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "Ta-9", title: "Tavuklu dürüm", category: "Tavuk yemekleri", ingredients: ["350 g tavuk göğsü", "4 lavaş", "1 kırmızı biber", "1 küçük soğan", "2 yemek kaşığı yoğurt", "1 yemek kaşığı zeytinyağı"], steps: ["Tavuğu ve sebzeleri ince şeritler halinde doğrayın.", "Yağda önce tavuğu, ardından soğan ve biberi soteleyin.", "Tavuk 74°C iç sıcaklığa ulaşınca ocaktan alın.", "Lavaşları ısıtıp yoğurt ve tavuklu karışımla doldurarak sarın."], minutes: 30),
  GeneralRecipe(id: "Et-0", title: "Izgara köfte", category: "Et yemekleri", ingredients: ["500 g orta yağlı dana kıyma", "1 küçük soğan", "2 yemek kaşığı galeta unu", "1 yumurta", "1 çay kaşığı kimyon"], steps: ["Soğanı rendeleyip fazla suyunu sıkın.", "Kıyma, soğan, yumurta, galeta unu ve kimyonu yoğurun.", "Karışımı 20 dakika buzdolabında dinlendirip köfte şekli verin.", "Isıtılmış ızgarada her iki yüzünü pişirin; kıymanın iç sıcaklığını en az 71°C’ye çıkarın."], minutes: 45),
  GeneralRecipe(id: "Et-1", title: "Fırında köfte", category: "Et yemekleri", ingredients: ["500 g dana kıyma", "1 soğan", "1 yumurta", "3 yemek kaşığı galeta unu", "2 patates", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 200°C’ye ısıtın; patatesleri elma dilim kesin.", "Kıyma, rendelenmiş soğan, yumurta ve galeta ununu yoğurup köfte yapın.", "Köfteleri ve yağla harmanlanmış patatesleri tepsiye yerleştirin.", "Yaklaşık 30–35 dakika pişirin; köftelerin iç sıcaklığı en az 71°C olmalı."], minutes: 50),
  GeneralRecipe(id: "Et-2", title: "Etli türlü", category: "Et yemekleri", ingredients: ["400 g dana kuşbaşı", "1 patlıcan", "1 kabak", "2 patates", "2 domates", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su"], steps: ["Eti tencerede az yağla renk alana kadar mühürleyin.", "Soğanı ekleyip yumuşatın; sıcak suyu ilave edip eti 35–45 dakika pişirin.", "Doğranmış patates, patlıcan, kabak ve domatesi ekleyin.", "Sebzeler ve et tamamen yumuşayana kadar yaklaşık 25 dakika daha pişirin."], minutes: 80),
  GeneralRecipe(id: "Et-3", title: "Et sote", category: "Et yemekleri", ingredients: ["500 g dana kuşbaşı", "1 soğan", "2 sivri biber", "2 domates", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı sıcak su"], steps: ["Eti kızgın tencerede yağla 5 dakika çevirin.", "Soğan ve biberleri ekleyip 5 dakika daha soteleyin.", "Rendelenmiş domates ve sıcak suyu ekleyin.", "Kapağı kapalı kısık ateşte et yumuşayana kadar 35–50 dakika pişirin."], minutes: 65),
  GeneralRecipe(id: "Et-4", title: "Etli nohut", category: "Et yemekleri", ingredients: ["300 g dana kuşbaşı", "2 su bardağı haşlanmış nohut", "1 soğan", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Eti yağda renk alana kadar çevirin; soğanı ekleyip kavurun.", "Salçayı ekleyip 1 dakika karıştırın; sıcak suyu ilave edin.", "Eti yumuşayana kadar 35–45 dakika pişirin.", "Haşlanmış nohudu ekleyip 15 dakika daha kaynatın."], minutes: 70),
  GeneralRecipe(id: "Et-5", title: "Kıymalı kabak", category: "Et yemekleri", ingredients: ["300 g dana kıyma", "3 kabak", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı sıcak su"], steps: ["Soğanı yağda kavurup kıymayı ekleyin; rengi tamamen dönene kadar pişirin.", "Kabakları yarım ay şeklinde kesip tencereye ekleyin.", "Rendelenmiş domates ve sıcak suyu ekleyin.", "Kapağı kapalı 20–25 dakika, kabaklar yumuşayana kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "Et-6", title: "Kıymalı ıspanak", category: "Et yemekleri", ingredients: ["300 g dana kıyma", "500 g ıspanak", "1 soğan", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı su"], steps: ["Ispanağı bol suyla yıkayıp iri doğrayın.", "Soğanı yağda kavurun; kıymayı ekleyip tamamen pişirin.", "Salçayı ve ıspanağı ekleyip hacmi azalıncaya kadar karıştırın.", "Suyu ilave edip kapağı kapalı 12–15 dakika pişirin."], minutes: 35),
  GeneralRecipe(id: "Et-7", title: "Kıymalı patates", category: "Et yemekleri", ingredients: ["400 g dana kuşbaşı", "300 g mantar", "1 soğan", "1 kırmızı biber", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı sıcak su"], steps: ["Eti yağda renk alana kadar mühürleyin.", "Sıcak suyu ekleyip et yumuşayana kadar kapağı kapalı pişirin.", "Soğan, biber ve dilimlenmiş mantarları ekleyin.", "Mantarların suyu çekilip et tamamen pişene kadar 12–15 dakika daha soteleyin."], minutes: 65),
  GeneralRecipe(id: "Et-8", title: "Etli bezelye", category: "Et yemekleri", ingredients: ["400 g dana kıyma", "2 patlıcan", "2 domates", "1 soğan", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı"], steps: ["Patlıcanları küp doğrayıp az yağla 200°C fırında 20 dakika yumuşatın.", "Soğanı kavurup kıymayı ekleyin; tamamen pişirin.", "Salça ve rendelenmiş domatesi ekleyip 10 dakika kaynatın.", "Patlıcanlarla birleştirip 10 dakika daha fırınlayın."], minutes: 55),
  GeneralRecipe(id: "Et-9", title: "Etli bulgur", category: "Et yemekleri", ingredients: ["500 g dana kuşbaşı", "2 patates", "2 havuç", "1 soğan", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Eti yağda mühürleyip doğranmış soğanı ekleyin.", "Sıcak suyu ilave edip et yumuşamaya başlayana kadar 35–45 dakika pişirin.", "Küp doğranmış patates ve havucu ekleyin.", "Sebzeler ve et tamamen yumuşayana kadar 20–25 dakika daha pişirin."], minutes: 80),
