  GeneralRecipe(id: "At-9", title: "Lorlu sandviç", category: "Pratik tarifler", ingredients: ["Lorlu sandviç", "zeytinyağı", "su (gerektikçe)"], steps: ["Malzemeleri temizleyip hazırlayın.", "Tarifin gerektirdiği haşlama, ezme veya fırınlama işlemini uygulayın.", "Küçük porsiyonlar hâlinde servis edin."], minutes: 55, detailed: false),
  GeneralRecipe(id: "master33-0", title: "Mercimek çorbası", category: "Çorbalar", ingredients: ["1 su bardağı kırmızı mercimek", "1 küçük soğan", "1 havuç", "1 yemek kaşığı zeytinyağı", "5 su bardağı su"], steps: ["Mercimeği yıkayın; soğan ve havucu doğrayın.", "Tencerede yağı ısıtıp soğan ve havucu 3 dakika çevirin.", "Mercimek ve suyu ekleyip 20 dakika yumuşayana dek pişirin.", "Blenderdan geçirip kıvamını sıcak suyla ayarlayın."], minutes: 25),
  GeneralRecipe(id: "master33-1", title: "Domates çorbası", category: "Çorbalar", ingredients: ["5 olgun domates", "1 yemek kaşığı un", "1 yemek kaşığı zeytinyağı", "3 su bardağı su"], steps: ["Domatesleri rendeleyin.", "Yağda unu 1 dakika kavurup domatesi ekleyin.", "Suyu azar azar ekleyerek karıştırın.", "15 dakika pişirip süzerek servis edin."], minutes: 25),
  GeneralRecipe(id: "master33-2", title: "Sebzeli bulgur pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "1 kabak", "1 kırmızı biber", "1 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Sebzeleri küçük küpler hâlinde doğrayın.", "Yağda sebzeleri 5 dakika soteleyin.", "Bulguru ekleyip karıştırın ve sıcak suyu ilave edin.", "Kapağı kapalı olarak kısık ateşte suyunu çekene dek pişirin."], minutes: 30),
  GeneralRecipe(id: "master33-5", title: "Fırında tavuk ve patates", category: "Tavuk yemekleri", ingredients: ["400 g kemiksiz tavuk", "3 patates", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 200 °C ısıtın.", "Patatesleri dilimleyip tavukla fırın kabına yerleştirin.", "Yağ ve kekiği ekleyip harmanlayın.", "Tavuk iç sıcaklığı en az 74 °C olana dek yaklaşık 35–45 dakika pişirin."], minutes: 55),
  GeneralRecipe(id: "master33-8", title: "Muzlu yulaf pankeki", category: "Kek ve kurabiyeler", ingredients: ["1 olgun muz", "1 yumurta", "4 yemek kaşığı ince yulaf", "1 tatlı kaşığı zeytinyağı"], steps: ["Muzu çatalla ezin.", "Yumurta ve yulafı ekleyip karıştırın.", "Az yağlanmış tavaya küçük porsiyonlar dökün.", "İki tarafını da içi tamamen pişene kadar çevirin."], minutes: 20),
  GeneralRecipe(id: "master33-10", title: "Yoğurtlu semizotu", category: "Salatalar", ingredients: ["1 demet semizotu", "1 su bardağı yoğurt", "1 küçük diş sarımsak", "1 tatlı kaşığı zeytinyağı"], steps: ["Semizotunu iyice yıkayıp kurutun.", "Yoğurtla ezilmiş sarımsağı karıştırın.", "Semizotunu ekleyip harmanlayın.", "Üzerine zeytinyağı gezdirerek servis edin."], minutes: 10),
  GeneralRecipe(id: "master33-11", title: "Kabak mücveri", category: "Sebze yemekleri", ingredients: ["2 kabak", "2 yumurta", "4 yemek kaşığı un", "Yarım demet dereotu", "1 yemek kaşığı zeytinyağı"], steps: ["Kabakları rendeleyip suyunu sıkın.", "Yumurta, un ve dereotuyla karıştırın.", "Karışımı yağlanmış tavaya küçük porsiyonlarla koyun.", "İki tarafını da içi tamamen pişene dek pişirin."], minutes: 30),
  GeneralRecipe(id: "master33-12", title: "Fırında karnabahar", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı toz kırmızı biber"], steps: ["Fırını 200 °C ısıtın.", "Karnabaharı çiçeklere ayırıp yıkayın ve kurulayın.", "Yağ ve baharatla harmanlayıp tepsiye yayın.", "25–30 dakika, çatalla kolay delininceye dek pişirin."], minutes: 35),
  GeneralRecipe(id: "master33-13", title: "Kıymalı kabak dolması", category: "Et yemekleri", ingredients: ["4 orta boy kabak", "200 g kıyma", "Yarım su bardağı pirinç", "1 soğan", "1 yemek kaşığı salça", "2 su bardağı su"], steps: ["Kabakları yıkayıp içlerini oyun.", "Kıyma, yıkanmış pirinç, doğranmış soğan ve salçayı karıştırın.", "Kabakları çok sıkıştırmadan doldurup tencereye dizin.", "Suyu ekleyip pirinç ve kıyma tamamen pişene kadar 40–45 dakika pişirin."], minutes: 60),
  GeneralRecipe(id: "master33-15", title: "Elmalı tarçınlı yulaf", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 elma", "4 yemek kaşığı yulaf", "1 su bardağı süt", "Yarım çay kaşığı tarçın"], steps: ["Elmayı yıkayıp rendeleyin.", "Süt ve yulafı küçük tencerede 5 dakika pişirin.", "Elmayı ekleyip 3 dakika daha karıştırın.", "Tarçın serperek ılık servis edin."], minutes: 15),
  GeneralRecipe(id: "master33-17", title: "Sebzeli makarna", category: "Makarnalar", ingredients: ["200 g makarna", "1 kabak", "1 havuç", "2 yemek kaşığı zeytinyağı", "1 küçük domates"], steps: ["Makarnayı paket talimatına göre haşlayın.", "Sebzeleri küçük doğrayıp yağda yumuşayana dek soteleyin.", "Doğranmış domatesi ekleyip 5 dakika pişirin.", "Süzülmüş makarnayı sosla karıştırın."], minutes: 25),
  GeneralRecipe(id: "master33-18", title: "Mercimek köftesi", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı kırmızı mercimek", "Yarım su bardağı ince bulgur", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı salça", "3 su bardağı su"], steps: ["Mercimeği suyla tamamen yumuşayana dek pişirin.", "Ocağı kapatıp bulguru ekleyin; kapağı kapalı 15 dakika bekletin.", "Soğanı yağ ve salçayla kavurup karışıma ekleyin.", "Soğuyunca yoğurup şekil verin; hijyenik koşullarda saklayın."], minutes: 45),
  GeneralRecipe(id: "master34-0", title: "Fırında sebzeli omlet", category: "Kahvaltılıklar", ingredients: ["3 yumurta", "1 küçük kabak", "1 kırmızı biber", "2 yemek kaşığı süt", "1 tatlı kaşığı zeytinyağı"], steps: ["Fırını 180 °C ısıtın.", "Kabak ve biberi ince doğrayın; yağlanmış küçük kaba yayın.", "Yumurta ve sütü çırpıp sebzelerin üzerine dökün.", "Ortasında çiğ yumurta kalmayana kadar yaklaşık 18–22 dakika pişirin."], minutes: 25),
  GeneralRecipe(id: "master34-1", title: "Kırmızı pancarlı yoğurt salatası", category: "Salatalar", ingredients: ["2 küçük pancar", "1 su bardağı yoğurt", "1 diş sarımsak", "1 tatlı kaşığı zeytinyağı"], steps: ["Pancarları yıkayıp yumuşayana kadar haşlayın.", "Soğuyan pancarları soyup rendeleyin.", "Yoğurt ve ezilmiş sarımsağı karıştırın.", "Pancarı ekleyip zeytinyağıyla servis edin."], minutes: 20),
  GeneralRecipe(id: "master34-2", title: "Zeytinyağlı pırasa", category: "Sebze yemekleri", ingredients: ["4 pırasa", "1 havuç", "2 yemek kaşığı pirinç", "3 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Pırasaları iyice yıkayıp dilimleyin; havucu doğrayın.", "Tencerede yağ ile havucu 3 dakika çevirin.", "Pırasa, yıkanmış pirinç ve suyu ekleyin.", "Kapağı kapalı kısık ateşte yaklaşık 30 dakika yumuşayana dek pişirin."], minutes: 45),
  GeneralRecipe(id: "master34-3", title: "Fırında baharatlı nohut", category: "Diyet ve sağlıklı tarifler", ingredients: ["2 su bardağı haşlanmış nohut", "1 yemek kaşığı zeytinyağı", "1 çay kaşığı tatlı toz biber", "Yarım çay kaşığı kimyon"], steps: ["Fırını 200 °C ısıtın.", "Haşlanmış nohudu süzüp iyice kurulayın.", "Yağ ve baharatla harmanlayıp tepsiye tek sıra yayın.", "Yaklaşık 20–25 dakika ara sıra çevirerek fırınlayın."], minutes: 35),
  GeneralRecipe(id: "master34-4", title: "Limonlu fırın levrek", category: "Balık ve deniz ürünleri", ingredients: ["2 temizlenmiş levrek fileto", "1 limon", "1 yemek kaşığı zeytinyağı", "2 dal maydanoz"], steps: ["Fırını 190 °C ısıtın.", "Filetoları fırın kabına yerleştirip yağ ve limon suyu ekleyin.", "Balık tamamen pişene ve eti kolay ayrılana dek yaklaşık 18–22 dakika pişirin.", "Kılçık kontrolü yapıp maydanozla servis edin."], minutes: 35),
  GeneralRecipe(id: "master34-5", title: "Tavuklu sebze sote", category: "Tavuk yemekleri", ingredients: ["350 g tavuk göğsü", "1 kabak", "1 kırmızı biber", "1 küçük soğan", "2 yemek kaşığı zeytinyağı"], steps: ["Tavuğu ve sebzeleri ayrı tahtalarda küçük doğrayın.", "Tavukları yağda yüksek ateşte renk alana kadar soteleyin.", "Soğan ve sebzeleri ekleyip yumuşayana dek pişirin.", "Tavuğun iç sıcaklığının en az 74 °C olduğundan emin olun."], minutes: 30),
  GeneralRecipe(id: "master34-6", title: "Mantarlı arpa şehriye pilavı", category: "Pilavlar", ingredients: ["1 su bardağı arpa şehriye", "200 g mantar", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Mantarları temizleyip dilimleyin.", "Soğan ve mantarı yağda suyunu çekene dek soteleyin.", "Arpa şehriyeyi ekleyip 2 dakika karıştırın.", "Sıcak suyu ekleyip kapağı kapalı kısık ateşte suyunu çekene dek pişirin."], minutes: 30),
  GeneralRecipe(id: "master34-7", title: "Yeşil mercimekli bulgur salatası", category: "Salatalar", ingredients: ["1 su bardağı haşlanmış yeşil mercimek", "Yarım su bardağı ince bulgur", "1 salatalık", "Yarım demet maydanoz", "1 limon", "1 yemek kaşığı zeytinyağı"], steps: ["Bulguru sıcak suyla ıslatıp kapağı kapalı 10 dakika şişirin.", "Salatalığı ve maydanozu yıkayıp doğrayın.", "Haşlanmış mercimek ile bulguru karıştırın.", "Sebzeleri, limon suyunu ve yağı ekleyip servis edin."], minutes: 30),
  GeneralRecipe(id: "master34-8", title: "Fırında kabak graten", category: "Sebze yemekleri", ingredients: ["3 kabak", "1 su bardağı süt", "1 yemek kaşığı un", "1 yemek kaşığı tereyağı", "Yarım su bardağı rendelenmiş kaşar"], steps: ["Fırını 190 °C ısıtın; kabakları ince dilimleyin.", "Kabakları fırın kabına dizin.", "Tereyağı ve unu kavurup sütü azar azar ekleyerek koyu sos hazırlayın.", "Sosu ve peyniri kabaklara ekleyip kabaklar yumuşayana dek 30 dakika pişirin."], minutes: 45),
  GeneralRecipe(id: "master34-9", title: "Kuru fasulye piyazı", category: "Salatalar", ingredients: ["2 su bardağı haşlanmış kuru fasulye", "1 kırmızı soğan", "1 domates", "Yarım demet maydanoz", "1 limon", "2 yemek kaşığı zeytinyağı"], steps: ["Fasulyeleri tamamen pişmiş ve soğumuş olarak hazırlayın.", "Soğanı ince dilimleyin; domates ve maydanozu doğrayın.", "Tüm malzemeleri karıştırın.", "Limon ve zeytinyağı ekleyip taze servis edin."], minutes: 15),
  GeneralRecipe(id: "master34-10", title: "Fırında elmalı crumble", category: "Dünya mutfağı", ingredients: ["3 elma", "Yarım su bardağı yulaf", "3 yemek kaşığı un", "2 yemek kaşığı tereyağı", "1 çay kaşığı tarçın"], steps: ["Fırını 180 °C ısıtın.", "Elmaları doğrayıp tarçınla karıştırarak kaba alın.", "Yulaf, un ve soğuk tereyağını ufalanan kıvama gelene dek karıştırın.", "Üstüne serpip elmalar yumuşayana dek 25–30 dakika pişirin."], minutes: 40),
  GeneralRecipe(id: "master34-11", title: "Yoğurtlu köz patlıcan", category: "Mezeler", ingredients: ["2 patlıcan", "1 su bardağı yoğurt", "1 diş sarımsak", "1 tatlı kaşığı zeytinyağı"], steps: ["Patlıcanları fırında 220 °C’de kabukları kararıncaya dek közleyin.", "Soğutup kabuklarını soyun ve içini ince kıyın.", "Yoğurt ve ezilmiş sarımsağı karıştırın.", "Patlıcanı ekleyip zeytinyağıyla servis edin."], minutes: 35),
  GeneralRecipe(id: "master34-12", title: "Sebzeli mercimek güveci", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı yeşil mercimek", "1 havuç", "1 patates", "1 soğan", "1 yemek kaşığı salça", "3 su bardağı su"], steps: ["Mercimeği yıkayıp 15 dakika ön haşlayın ve süzün.", "Soğan, havuç ve patatesi doğrayın.", "Tencerede salça, sebzeler, mercimek ve suyu birleştirin.", "Mercimek ve sebzeler tamamen yumuşayana dek 25–30 dakika pişirin."], minutes: 50),
  GeneralRecipe(id: "master34-13", title: "Fırında kıymalı patates", category: "Et yemekleri", ingredients: ["300 g kıyma", "3 patates", "1 soğan", "2 domates", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 200 °C ısıtın; patatesleri ince dilimleyin.", "Soğan ve kıymayı tavada tamamen renk değiştirene dek kavurun.", "Fırın kabına patates, kıyma ve domatesleri katmanlayın.", "Patatesler yumuşayana ve kıyma tamamen pişene dek 35–40 dakika fırınlayın."], minutes: 55),
  GeneralRecipe(id: "master34-14", title: "Tarçınlı armut kompostosu", category: "İçecekler", ingredients: ["3 armut", "4 su bardağı su", "1 çubuk tarçın", "1 tatlı kaşığı limon suyu"], steps: ["Armutları yıkayıp çekirdeklerini çıkararak dilimleyin.", "Su ve tarçını tencereye alın; kaynatın.", "Armutları ekleyip yumuşayana dek 12–15 dakika pişirin.", "Limon suyunu ekleyip soğutarak servis edin."], minutes: 25),
  GeneralRecipe(id: "paket39-g-002", title: "Karnıyarık", category: "Et yemekleri", ingredients: ["4 patlıcan", "250 g kıyma", "1 soğan", "2 domates", "2 yeşil biber", "2 yemek kaşığı zeytinyağı"], steps: ["Patlıcanları uzunlamasına çizip 200 °C fırında yumuşatın.", "Soğanı, biberi ve kıymayı kavurun; domatesi ekleyip iç harcı pişirin.", "Patlıcanları açıp harçla doldurun.", "Az su ekleyerek 190 °C fırında yaklaşık 20 dakika pişirin."], minutes: 65),
  GeneralRecipe(id: "paket39-g-003", title: "İmam bayıldı", category: "Sebze yemekleri", ingredients: ["4 patlıcan", "2 soğan", "3 domates", "3 diş sarımsak", "4 yemek kaşığı zeytinyağı"], steps: ["Patlıcanları fırında yumuşayana kadar pişirin.", "Soğan ve sarımsağı zeytinyağında yumuşatıp domatesi ekleyin.", "Patlıcanları yarıp iç harçla doldurun.", "180 °C fırında yaklaşık 25 dakika pişirip ılıtarak sunun."], minutes: 60),
  GeneralRecipe(id: "paket39-g-005", title: "Nohutlu bulgur pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "1 su bardağı haşlanmış nohut", "1 soğan", "1 yemek kaşığı salça", "2 su bardağı sıcak su"], steps: ["Soğanı az yağda yumuşatıp salçayı ekleyin.", "Bulguru yıkayıp tencereye alın.", "Nohut ve sıcak suyu ekleyin.", "Kısık ateşte suyu çekene dek 15–20 dakika pişirip dinlendirin."], minutes: 30),
  GeneralRecipe(id: "paket39-g-006", title: "Fırında sebzeli somon", category: "Balık ve deniz ürünleri", ingredients: ["2 somon fileto", "1 kabak", "1 havuç", "1 limon", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190 °C ısıtın.", "Sebzeleri ince doğrayıp tepsiye yayın.", "Somonu üzerine koyup yağ ve limon ekleyin.", "Balık tamamen pişip kolay ayrılana kadar yaklaşık 18–22 dakika fırınlayın."], minutes: 30),
  GeneralRecipe(id: "paket39-g-007", title: "Tavuklu mantar sote", category: "Tavuk yemekleri", ingredients: ["350 g kemiksiz tavuk", "250 g mantar", "1 soğan", "1 kırmızı biber", "2 yemek kaşığı zeytinyağı"], steps: ["Tavuğu küçük parçalara kesin.", "Soğan ve biberi tavada soteleyin; tavuğu ekleyin.", "Tavuk tamamen pişince dilimlenmiş mantarı ekleyin.", "Mantarın suyu çekilene kadar pişirip servis edin."], minutes: 30),
  GeneralRecipe(id: "paket39-g-008", title: "Fırında patatesli köfte", category: "Et yemekleri", ingredients: ["300 g kıyma", "3 patates", "1 soğan", "1 yumurta", "2 yemek kaşığı galeta unu", "1 yemek kaşığı salça"], steps: ["Kıyma, rendelenmiş soğan, yumurta ve galeta ununu yoğurun.", "Köfteleri şekillendirip patatesleri dilimleyin.", "Fırın kabına dizip salçalı su ekleyin.", "200 °C fırında köfteler tamamen pişene kadar yaklaşık 35 dakika pişirin."], minutes: 50),
  GeneralRecipe(id: "paket39-g-009", title: "Yoğurtlu semizotu salatası", category: "Salatalar", ingredients: ["1 demet semizotu", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı"], steps: ["Semizotunu iyice yıkayıp süzün.", "Yoğurtla ezilmiş sarımsağı karıştırın.", "Semizotunu yoğurda ekleyin.", "Zeytinyağı gezdirip soğuk servis edin."], minutes: 15),
  GeneralRecipe(id: "paket39-g-011", title: "Şakşuka", category: "Mezeler", ingredients: ["2 patlıcan", "2 kabak", "2 patates", "3 domates", "2 diş sarımsak", "3 yemek kaşığı zeytinyağı"], steps: ["Sebzeleri küp doğrayıp ayrı ayrı fırında yumuşatın.", "Domates ve sarımsağı tavada sos kıvamına gelene dek pişirin.", "Sebzeleri karıştırıp servis tabağına alın.", "Üzerine domates sosunu dökün."], minutes: 40),
  GeneralRecipe(id: "paket39-g-012", title: "Peynirli gözleme", category: "Kahvaltılıklar", ingredients: ["2 su bardağı un", "Yarım su bardağı su", "150 g beyaz peynir", "Yarım demet maydanoz", "1 yemek kaşığı zeytinyağı"], steps: ["Un ve suyla yumuşak bir hamur yoğurup 10 dakika dinlendirin.", "Peyniri ufalayıp maydanozla karıştırın.", "Hamuru ince açıp harcı koyarak kapatın.", "Az yağlı tavada iki yüzünü de pişirin."], minutes: 35),
  GeneralRecipe(id: "paket39-g-013", title: "Domatesli şehriye çorbası", category: "Çorbalar", ingredients: ["3 domates", "Yarım su bardağı tel şehriye", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Domatesleri rendeleyip yağda birkaç dakika pişirin.", "Suyu ekleyip kaynatın.", "Şehriyeyi ilave edip yumuşayana dek 10–12 dakika pişirin.", "Sıcak servis edin."], minutes: 25),
  GeneralRecipe(id: "paket39-g-017", title: "Kabak dolması", category: "Sebze yemekleri", ingredients: ["4 kabak", "150 g kıyma", "Yarım su bardağı pirinç", "1 soğan", "1 domates", "1 yemek kaşığı salça"], steps: ["Kabakların içini oyun.", "Pirinç, kıyma, ince kıyılmış soğan, domates ve salçayı karıştırın.", "İç harcı kabaklara gevşekçe doldurun.", "Tencereye dizip yarısına gelecek kadar su ekleyin; 35–40 dakika pişirin."], minutes: 55),
  GeneralRecipe(id: "paket39-g-018", title: "Fırında tavuk baget", category: "Tavuk yemekleri", ingredients: ["6 tavuk baget", "2 patates", "2 havuç", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 200 °C’ye ısıtın.", "Patates ve havucu iri doğrayıp bagetlerle harmanlayın.", "Yağ ve kekiği ekleyip fırın kabına yayın.", "Tavuk iç sıcaklığı en az 74 °C olana kadar yaklaşık 40–45 dakika pişirin."], minutes: 55),
  GeneralRecipe(id: "paket39-g-022", title: "Şehriyeli pirinç pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pirinç", "2 yemek kaşığı arpa şehriye", "1 yemek kaşığı tereyağı", "1,5 su bardağı sıcak su"], steps: ["Pirinci yıkayıp süzün.", "Şehriyeyi tereyağında hafifçe kavurun.", "Pirinci ekleyip 2 dakika çevirin ve sıcak suyu dökün.", "Kısık ateşte suyunu çekince ocaktan alıp 10 dakika dinlendirin."], minutes: 35),
  GeneralRecipe(id: "paket39-g-023", title: "Fırında mücver", category: "Sebze yemekleri", ingredients: ["2 kabak", "2 yumurta", "4 yemek kaşığı un", "Yarım demet dereotu", "100 g beyaz peynir"], steps: ["Kabakları rendeleyip suyunu iyice sıkın.", "Yumurta, un, dereotu ve ufalanmış peynirle karıştırın.", "Yağlı kâğıt serili tepsiye ince yayın.", "190 °C fırında 25–30 dakika, içi tamamen pişene kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "paket39-g-024", title: "Kıymalı patates oturtma", category: "Et yemekleri", ingredients: ["4 patates", "250 g kıyma", "1 soğan", "2 domates", "1 yemek kaşığı salça", "1 su bardağı su"], steps: ["Patatesleri ince dilimleyip fırın kabına dizin.", "Soğan ve kıymayı tavada iyice pişirin.", "Domates ve salçayı ekleyip 5 dakika kaynatın.", "Kıymalı sosu patateslerin üzerine dökün, su ekleyip 190 °C’de 35 dakika pişirin."], minutes: 55),
  GeneralRecipe(id: "paket39-g-025", title: "Etli sebze güveç", category: "Et yemekleri", ingredients: ["400 g kuşbaşı dana eti", "1 patlıcan", "2 patates", "2 domates", "1 biber", "2 yemek kaşığı zeytinyağı"], steps: ["Eti tavada mühürleyin.", "Sebzeleri eşit büyüklükte doğrayın.", "Et ve sebzeleri güveç kabına alıp yağ ve yarım su bardağı su ekleyin.", "Kapaklı olarak 180 °C fırında et yumuşayana dek 65–75 dakika pişirin."], minutes: 90),
  GeneralRecipe(id: "paket39-g-027", title: "Fırında beşamel soslu karnabahar", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar", "2 su bardağı süt", "2 yemek kaşığı un", "2 yemek kaşığı tereyağı", "Yarım su bardağı rendelenmiş kaşar"], steps: ["Karnabaharı çiçeklerine ayırıp 8 dakika haşlayın.", "Tereyağında unu kavurup sütü azar azar ekleyerek koyulaştırın.", "Karnabaharı fırın kabına alıp sosu üzerine dökün.", "Kaşarı serpip 190 °C’de 20 dakika kızartın."], minutes: 50),
  GeneralRecipe(id: "paket39-g-028", title: "Kırmızı mercimek çorbası", category: "Çorbalar", ingredients: ["1 su bardağı kırmızı mercimek", "1 havuç", "1 soğan", "1 patates", "5 su bardağı su"], steps: ["Mercimeği yıkayın; sebzeleri doğrayın.", "Tüm malzemeleri tencerede suyla birleştirin.", "Mercimek ve sebzeler yumuşayana kadar yaklaşık 25 dakika pişirin.", "Blenderdan geçirip kıvamını sıcak suyla ayarlayın."], minutes: 35),
  GeneralRecipe(id: "paket39-g-029", title: "Yayla çorbası", category: "Çorbalar", ingredients: ["Yarım su bardağı pirinç", "1 su bardağı yoğurt", "1 yumurta sarısı", "1 yemek kaşığı un", "5 su bardağı su", "1 tatlı kaşığı kuru nane"], steps: ["Pirinci suda tamamen yumuşayana kadar haşlayın.", "Yoğurt, yumurta sarısı ve unu ayrı kapta çırpın.", "Sıcak çorba suyundan azar azar ekleyip terbiyeyi ılıtın.", "Terbiyeyi tencereye döküp karıştırarak kaynatın; nane ekleyin."], minutes: 35),
  GeneralRecipe(id: "paket39-g-031", title: "Fırında levrek", category: "Balık ve deniz ürünleri", ingredients: ["2 temizlenmiş levrek", "1 limon", "1 soğan", "2 yemek kaşığı zeytinyağı", "2 dal maydanoz"], steps: ["Fırını 190 °C’ye ısıtın.", "Balıkları temizleyip kılçık kontrolü yapın.", "Soğan ve limon dilimleriyle birlikte tepsiye yerleştirin.", "Yağ gezdirip balık eti opaklaşana ve kolay ayrılana dek 25–30 dakika pişirin."], minutes: 40),
  GeneralRecipe(id: "paket39-g-032", title: "Ton balıklı makarna salatası", category: "Salatalar", ingredients: ["200 g makarna", "1 kutu ton balığı", "1 salatalık", "1 kırmızı biber", "2 yemek kaşığı zeytinyağı", "1 limon"], steps: ["Makarnayı haşlayıp soğutun.", "Salatalık ve biberi küçük doğrayın.", "Süzülmüş ton balığıyla tüm malzemeleri birleştirin.", "Limon suyu ve zeytinyağı ekleyip soğuk servis edin."], minutes: 25),
  GeneralRecipe(id: "paket39-g-033", title: "Patates salatası", category: "Salatalar", ingredients: ["4 patates", "3 taze soğan", "Yarım demet maydanoz", "1 limon", "2 yemek kaşığı zeytinyağı"], steps: ["Patatesleri kabuklu haşlayıp soğutun.", "Soyup küp doğrayın.", "Taze soğan ve maydanozu ince kıyın.", "Limon ve yağla harmanlayıp servis edin."], minutes: 30),
  GeneralRecipe(id: "paket39-g-034", title: "Kısır", category: "Salatalar", ingredients: ["1 su bardağı ince bulgur", "1 su bardağı sıcak su", "1 yemek kaşığı biber salçası", "3 taze soğan", "Yarım demet maydanoz", "1 limon"], steps: ["Bulguru sıcak suyla ıslatıp kapağını kapatın.", "Şişen bulgura salçayı ekleyip karıştırın.", "İnce doğranmış yeşillikleri ilave edin.", "Limon suyu ekleyip servis edin."], minutes: 30),
  GeneralRecipe(id: "paket39-g-035", title: "Peynirli börek", category: "Hamur işleri", ingredients: ["3 yufka", "200 g beyaz peynir", "Yarım demet maydanoz", "1 yumurta", "Yarım su bardağı süt", "3 yemek kaşığı sıvı yağ"], steps: ["Peyniri maydanozla karıştırın.", "Yumurta, süt ve yağı çırpın.", "Yufkaları soslayarak tepsiye kat kat serin, aralara peynir koyun.", "180 °C fırında üzeri kızarıp içi pişene dek 30–35 dakika pişirin."], minutes: 50),
  GeneralRecipe(id: "paket39-g-037", title: "Sebzeli omlet", category: "Kahvaltılıklar", ingredients: ["2 yumurta", "Yarım kırmızı biber", "1 küçük domates", "1 yemek kaşığı zeytinyağı"], steps: ["Biberi küçük doğrayıp yağda yumuşatın.", "Doğranmış domatesi ekleyip suyunu çektirin.", "Çırpılmış yumurtaları tavaya dökün.", "Yumurtalar tamamen pişene kadar pişirin."], minutes: 15),
  GeneralRecipe(id: "paket39-g-038", title: "İrmik helvası", category: "Tatlılar", ingredients: ["1 su bardağı irmik", "2 yemek kaşığı tereyağı", "1 su bardağı süt", "Yarım su bardağı şeker", "Yarım su bardağı su"], steps: ["Süt, su ve şekeri ayrı tencerede ılıtıp eritin.", "İrmiği tereyağında altın rengi olana dek kavurun.", "Sıcak sıvıyı dikkatle azar azar ekleyin.", "Kısık ateşte suyunu çektirip 10 dakika dinlendirin."], minutes: 30),
  GeneralRecipe(id: "paket39-g-040", title: "Zeytinyağlı enginar", category: "Sebze yemekleri", ingredients: ["4 enginar çanağı", "1 havuç", "1 patates", "1 su bardağı bezelye", "1 limon", "3 yemek kaşığı zeytinyağı"], steps: ["Enginarları limonlu suda bekletin.", "Havuç ve patatesi küp doğrayın.", "Sebzeleri enginarların içine yerleştirip zeytinyağı ve az su ekleyin.", "Kapak kapalı şekilde enginarlar yumuşayana kadar pişirin."], minutes: 45),
  GeneralRecipe(id: "paket39-g-041", title: "Kabak sandal", category: "Sebze yemekleri", ingredients: ["3 kabak", "200 g kıyma", "1 soğan", "1 domates", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı rendelenmiş kaşar"], steps: ["Kabakları boyuna ikiye kesip içlerini oyun.", "Soğan ve kıymayı kavurup doğranmış domatesi ekleyin.", "Harcı kabaklara paylaştırıp tepsiye dizin.", "Az suyla 190 °C fırında yumuşatın, kaşar ekleyip kızartın."], minutes: 45),
  GeneralRecipe(id: "paket39-g-042", title: "Köz patlıcan salatası", category: "Salatalar", ingredients: ["3 patlıcan", "2 kırmızı biber", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 limon"], steps: ["Patlıcan ve biberleri közleyip kabuklarını soyun.", "Sebzeleri ince doğrayıp bir kapta karıştırın.", "Ezilmiş sarımsak, limon suyu ve zeytinyağı ekleyin.", "Soğuk veya ılık servis edin."], minutes: 30),
  GeneralRecipe(id: "paket39-g-043", title: "Yeşil mercimek salatası", category: "Salatalar", ingredients: ["1 su bardağı yeşil mercimek", "3 dal taze soğan", "Yarım demet maydanoz", "1 kırmızı biber", "1 limon", "2 yemek kaşığı zeytinyağı"], steps: ["Mercimeği dağılmadan yumuşayana kadar haşlayıp süzün.", "Soğuyan mercimeğe ince doğranmış yeşillikleri ve biberi ekleyin.", "Limon suyu ve zeytinyağıyla harmanlayın.", "Servis öncesi kısa süre dinlendirin."], minutes: 35),
  GeneralRecipe(id: "paket39-g-044", title: "Mayalı açma", category: "Hamur işleri", ingredients: ["4 su bardağı un", "1 su bardağı ılık süt", "Yarım su bardağı sıvı yağ", "1 yemek kaşığı kuru maya", "1 yemek kaşığı şeker", "1 yumurta"], steps: ["Ilık süt, maya ve şekeri karıştırıp 10 dakika bekletin.", "Un ve yağı ekleyip yumuşak hamur yoğurun, 45 dakika mayalandırın.", "Hamuru şeritler hâlinde şekillendirip tepsiye alın.", "Yumurta sürerek 190 °C fırında kızarana kadar pişirin."], minutes: 100),
  GeneralRecipe(id: "paket39-g-045", title: "Domatesli arpa şehriye pilavı", category: "Pilavlar", ingredients: ["1 su bardağı arpa şehriye", "2 domates", "1 yemek kaşığı tereyağı", "1,5 su bardağı sıcak su"], steps: ["Şehriyeyi tereyağında hafifçe kavurun.", "Rendelenmiş domatesleri ekleyip birkaç dakika pişirin.", "Sıcak suyu ekleyip kapağını kapatın.", "Kısık ateşte suyunu çekince dinlendirip servis edin."], minutes: 30),
  GeneralRecipe(id: "paket39-g-046", title: "Mantarlı bulgur pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "200 g mantar", "1 soğan", "1 yemek kaşığı tereyağı", "2 su bardağı sıcak su"], steps: ["Mantarları temizleyip dilimleyin.", "Soğanı yağda kavurup mantarları ekleyin.", "Bulguru katıp karıştırın, sıcak suyu ekleyin.", "Kapağı kapalı kısık ateşte suyunu çekene kadar pişirin."], minutes: 35),
  GeneralRecipe(id: "paket39-g-047", title: "Tavuklu erişte", category: "Makarnalar", ingredients: ["250 g erişte", "200 g tavuk göğsü", "1 kırmızı biber", "2 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su"], steps: ["Tavuğu küçük doğrayıp yağda tamamen pişirin.", "Doğranmış biberi ekleyip yumuşatın.", "Erişteyi katıp kısa süre kavurun.", "Sıcak su ekleyerek erişte yumuşayana kadar pişirin."], minutes: 35),
  GeneralRecipe(id: "paket39-g-048", title: "Fesleğenli domates makarna", category: "Makarnalar", ingredients: ["250 g makarna", "3 domates", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "6 yaprak fesleğen"], steps: ["Makarnayı paket süresine göre haşlayın.", "Sarımsağı zeytinyağında kısa süre çevirip rendelenmiş domatesi ekleyin.", "Sosu koyulaşana kadar pişirin.", "Makarnayı sos ve doğranmış fesleğenle karıştırın."], minutes: 25),
  GeneralRecipe(id: "paket39-g-049", title: "Karides güveç", category: "Balık ve deniz ürünleri", ingredients: ["300 g temizlenmiş karides", "2 domates", "2 yeşil biber", "2 diş sarımsak", "1 yemek kaşığı tereyağı", "Yarım su bardağı kaşar"], steps: ["Sarımsak ve biberi tereyağında yumuşatın.", "Domatesleri ekleyip sos kıvamına gelene kadar pişirin.", "Karidesleri katıp tamamen pişene kadar kısa süre çevirin.", "Güveç kabına alıp kaşar ekleyerek fırında kızartın."], minutes: 30),
  GeneralRecipe(id: "paket39-g-050", title: "Fırında köri soslu tavuk", category: "Dünya mutfağı", ingredients: ["400 g tavuk göğsü", "1 su bardağı yoğurt", "1 tatlı kaşığı köri", "2 yemek kaşığı zeytinyağı", "1 kırmızı biber"], steps: ["Yoğurt, köri ve yağı karıştırın.", "Tavukları sosla kaplayıp 20 dakika buzdolabında bekletin.", "Biberlerle birlikte fırın kabına alın.", "190 °C fırında tavuk tamamen pişene kadar pişirin."], minutes: 45),
  GeneralRecipe(id: "paket39-g-051", title: "Tavuklu sebze çorbası", category: "Çorbalar", ingredients: ["200 g tavuk göğsü", "1 havuç", "1 patates", "1 küçük kabak", "5 su bardağı su"], steps: ["Tavuğu suda tamamen pişirip küçük parçalara ayırın.", "Doğranmış sebzeleri tavuk suyuna ekleyin.", "Sebzeler yumuşayınca tavuk parçalarını geri koyun.", "Birkaç dakika birlikte kaynatıp servis edin."], minutes: 40),
  GeneralRecipe(id: "paket39-g-052", title: "Kremasız mantar çorbası", category: "Çorbalar", ingredients: ["300 g mantar", "1 soğan", "2 yemek kaşığı un", "2 yemek kaşığı zeytinyağı", "4 su bardağı su", "1 su bardağı süt"], steps: ["Soğanı yağda yumuşatıp dilimlenmiş mantarları ekleyin.", "Unu katıp kısa süre kavurun.", "Suyu azar azar karıştırarak dökün.", "Mantarlar pişince süt ekleyip birkaç dakika daha kaynatın."], minutes: 30),
  GeneralRecipe(id: "paket39-g-053", title: "Balkabağı çorbası", category: "Çorbalar", ingredients: ["400 g balkabağı", "1 patates", "1 havuç", "1 soğan", "4 su bardağı su", "2 yemek kaşığı zeytinyağı"], steps: ["Soğanı yağda yumuşatın.", "Küp doğranmış balkabağı, patates ve havucu ekleyin.", "Suyla sebzeler tamamen yumuşayana kadar kaynatın.", "Blenderdan geçirip sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "paket39-g-054", title: "Tahinli kabak tatlısı", category: "Tatlılar", ingredients: ["600 g balkabağı", "1 su bardağı şeker", "Yarım su bardağı su", "3 yemek kaşığı tahin", "3 yemek kaşığı dövülmüş ceviz"], steps: ["Kabağı iri küpler hâlinde doğrayıp şekerle tencereye dizin.", "Suyu ekleyip kısık ateşte yumuşayana kadar pişirin.", "Soğuyan kabakları servis tabağına alın.", "Üzerine tahin ve ceviz gezdirin."], minutes: 60),
  GeneralRecipe(id: "paket39-g-055", title: "Portakallı kek", category: "Kek ve kurabiyeler", ingredients: ["3 yumurta", "1 su bardağı şeker", "1 su bardağı süt", "Yarım su bardağı sıvı yağ", "2 su bardağı un", "1 paket kabartma tozu", "1 portakal kabuğu rendesi"], steps: ["Yumurta ve şekeri köpürene kadar çırpın.", "Süt, yağ ve portakal kabuğunu ekleyin.", "Un ve kabartma tozunu karıştırıp kalıba dökün.", "175 °C fırında ortası pişene kadar yaklaşık 35 dakika pişirin."], minutes: 55),
  GeneralRecipe(id: "paket39-g-056", title: "Fırında sütlü irmik tatlısı", category: "Tatlılar", ingredients: ["1 litre süt", "8 yemek kaşığı irmik", "6 yemek kaşığı şeker", "1 paket vanilin", "1 yemek kaşığı tereyağı"], steps: ["Süt, irmik ve şekeri tencerede sürekli karıştırarak koyulaştırın.", "Vanilin ve tereyağını ekleyin.", "Karışımı fırın kabına dökün.", "200 °C fırında üzeri hafif renk alana kadar pişirin."], minutes: 45),
  GeneralRecipe(id: "paket39-g-057", title: "Kahvaltılık patatesli yumurta", category: "Kahvaltılıklar", ingredients: ["2 patates", "3 yumurta", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kırmızı toz biber"], steps: ["Patatesleri küçük küpler hâlinde doğrayın.", "Yağda kapak kapalı yumuşayana kadar pişirin.", "Çırpılmış yumurtaları ve baharatı ekleyin.", "Yumurtalar tamamen pişene kadar karıştırın."], minutes: 25),
  GeneralRecipe(id: "paket39-g-058", title: "Sebzeli kinoa kasesi", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı kinoa", "1 salatalık", "1 kırmızı biber", "1 avokado", "1 limon", "2 yemek kaşığı zeytinyağı"], steps: ["Kinoayı bol suda yıkayıp iki ölçü suda yumuşayana kadar pişirin.", "Salatalık, biber ve avokadoyu doğrayın.", "Soğuyan kinoayla sebzeleri birleştirin.", "Limon suyu ve zeytinyağı ekleyerek karıştırın."], minutes: 35),
  GeneralRecipe(id: "paket39-g-059", title: "Fırında baharatlı patates", category: "Sebze yemekleri", ingredients: ["4 patates", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik", "1 çay kaşığı tatlı toz biber"], steps: ["Patatesleri kabuklu veya soyulmuş şekilde elma dilim doğrayın.", "Yağ ve baharatlarla harmanlayın.", "Yağlı kâğıt serili tepsiye tek kat dizin.", "200 °C fırında dışı kızarıp içi yumuşayana kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a4_001", title: "Sebzeli arpa şehriye pilavı", category: "Pilavlar", ingredients: ["1 su bardağı arpa şehriye", "1 küçük havuç", "1 yeşil biber", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Havucu ve biberi küçük doğrayın.", "Şehriyeyi yağda hafif renk alana kadar kavurun.", "Sebzeleri ekleyip iki dakika çevirin.", "Sıcak suyu ekleyip kısık ateşte suyunu çekene kadar pişirin."], minutes: 25),
  GeneralRecipe(id: "p39a4_003", title: "Yoğurtlu pancar salatası", category: "Salatalar", ingredients: ["2 orta boy pancar", "4 yemek kaşığı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı"], steps: ["Pancarları yıkayıp yumuşayana kadar haşlayın.", "Soğutup kabuklarını soyun ve rendeleyin.", "Yoğurt ve ezilmiş sarımsakla karıştırın.", "Zeytinyağı gezdirerek servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a4_004", title: "Limonlu tavuk baget", category: "Tavuk yemekleri", ingredients: ["6 tavuk baget", "1 limonun suyu", "2 yemek kaşığı zeytinyağı", "2 diş sarımsak", "1 çay kaşığı kekik"], steps: ["Fırını 190 dereceye ısıtın.", "Limon suyu, yağ, ezilmiş sarımsak ve kekiği karıştırın.", "Bagetleri sosla kaplayıp fırın kabına yerleştirin.", "Tavuğun içi tamamen pişene kadar yaklaşık 40-45 dakika pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a4_006", title: "Fırında kabak dilimleri", category: "Sebze yemekleri", ingredients: ["2 kabak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru nane", "1 çay kaşığı kırmızı biber"], steps: ["Fırını 200 dereceye ısıtın.", "Kabakları eşit kalınlıkta dilimleyin.", "Yağ ve baharatlarla karıştırıp tek kat dizin.", "Kenarları kızarıp içleri yumuşayana kadar fırınlayın."], minutes: 30),
  GeneralRecipe(id: "p39a4_009", title: "Domatesli peynirli makarna", category: "Makarnalar", ingredients: ["250 g makarna", "2 domates", "100 g beyaz peynir", "1 yemek kaşığı zeytinyağı", "1 çay kaşığı fesleğen"], steps: ["Makarnayı paket talimatına göre haşlayıp süzün.", "Domatesleri rendeleyip yağda suyunu biraz çekene kadar pişirin.", "Makarnayı sosa ekleyip karıştırın.", "Ufalanmış peynir ve fesleğenle servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a4_010", title: "Köz biberli yoğurt mezesi", category: "Mezeler", ingredients: ["3 kırmızı kapya biber", "5 yemek kaşığı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı"], steps: ["Biberleri fırında veya tavada közleyin.", "Kapalı kapta dinlendirip kabuklarını soyun.", "Küçük doğrayıp yoğurt ve sarımsakla karıştırın.", "Üzerine zeytinyağı gezdirin."], minutes: 20),
  GeneralRecipe(id: "p39a4_011", title: "Patatesli pırasa", category: "Sebze yemekleri", ingredients: ["3 pırasa", "2 patates", "1 havuç", "2 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su"], steps: ["Pırasaları iyice yıkayıp halka doğrayın.", "Patates ve havucu küp doğrayın.", "Sebzeleri yağda birkaç dakika çevirin.", "Suyu ekleyip kapağı kapalı olarak sebzeler yumuşayana kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a4_012", title: "Portakallı havuç salatası", category: "Salatalar", ingredients: ["3 havuç", "1 portakal", "1 yemek kaşığı zeytinyağı", "2 yemek kaşığı limon suyu"], steps: ["Havuçları soyup rendeleyin.", "Portakalı soyup beyaz kısımlarını ayırarak dilimleyin.", "Zeytinyağı ve limon suyunu karıştırın.", "Havuç ve portakalı sosla harmanlayın."], minutes: 15),
  GeneralRecipe(id: "p39a4_013", title: "Fırında peynirli mantar", category: "Sebze yemekleri", ingredients: ["12 büyük mantar", "100 g rendelenmiş kaşar", "1 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 190 dereceye ısıtın.", "Mantarları temizleyip saplarını çıkarın.", "Tepsiye dizip içlerine az yağ ve peynir koyun.", "Mantarlar yumuşayıp peynir eriyene kadar pişirin."], minutes: 30),
  GeneralRecipe(id: "p39a4_014", title: "Sebzeli kuskus", category: "Dünya mutfağı", ingredients: ["1 su bardağı kuskus", "1 küçük kabak", "1 havuç", "2 yemek kaşığı zeytinyağı", "2 su bardağı su"], steps: ["Kuskusu paket talimatına göre haşlayın.", "Kabak ve havucu küçük küpler hâlinde doğrayın.", "Sebzeleri zeytinyağında yumuşayana kadar soteleyin.", "Süzülen kuskusla birleştirip sıcak servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a4_015", title: "Limonlu mercimek salatası", category: "Salatalar", ingredients: ["1 su bardağı yeşil mercimek", "2 dal taze soğan", "Yarım demet maydanoz", "2 yemek kaşığı limon suyu", "2 yemek kaşığı zeytinyağı"], steps: ["Mercimeği yıkayıp dağılmayacak şekilde haşlayın ve süzün.", "Taze soğan ve maydanozu ince doğrayın.", "Mercimeği yeşilliklerle karıştırın.", "Limon suyu ve zeytinyağıyla soslayın."], minutes: 30),
  GeneralRecipe(id: "p39a4_016", title: "Fırında armut tatlısı", category: "Tatlılar", ingredients: ["3 olgun armut", "1 çay kaşığı tarçın", "2 yemek kaşığı iri çekilmiş ceviz", "2 yemek kaşığı su"], steps: ["Fırını 180 dereceye ısıtın.", "Armutları ikiye bölüp çekirdeklerini çıkarın.", "Fırın kabına dizip tarçın ve su ekleyin.", "Yumuşayana kadar pişirip cevizle servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a4_017", title: "Sebzeli yumurta muffin", category: "Kek ve kurabiyeler", ingredients: ["3 yumurta", "Yarım kırmızı biber", "1 küçük kabak", "50 g beyaz peynir", "1 tatlı kaşığı zeytinyağı"], steps: ["Fırını 180 dereceye ısıtın ve muffin kalıplarını yağlayın.", "Sebzeleri küçük doğrayıp kabağı hafifçe sıkın.", "Yumurta, sebze ve ufalanmış peyniri karıştırın.", "Kalıplara paylaştırıp yumurta tamamen pişene kadar fırınlayın."], minutes: 30),
  GeneralRecipe(id: "p39a4_018", title: "Zeytinyağlı kereviz", category: "Sebze yemekleri", ingredients: ["2 kereviz", "1 havuç", "1 patates", "1 portakalın suyu", "3 yemek kaşığı zeytinyağı"], steps: ["Kereviz, havuç ve patatesi soyup eşit büyüklükte doğrayın.", "Tencereye sebzeleri yerleştirip zeytinyağını ekleyin.", "Portakal suyu ve sebzeleri örtecek kadar su ilave edin.", "Kısık ateşte yumuşayana kadar pişirip ılıtarak servis edin."], minutes: 45),
  GeneralRecipe(id: "p39a5_001", title: "Fırında sebzeli köfte", category: "Et yemekleri", ingredients: ["350 g kıyma", "1 küçük soğan", "1 yumurta", "3 yemek kaşığı galeta unu", "2 patates", "1 havuç", "2 yemek kaşığı zeytinyağı"], steps: ["Soğanı rendeleyip kıyma, yumurta ve galeta unuyla yoğurun.", "Harçtan küçük köfteler hazırlayın.", "Patates ve havucu dilimleyip yağla harmanlayın.", "Köfte ve sebzeleri tepsiye yerleştirip 190°C fırında köftelerin içi tamamen pişene kadar yaklaşık 30 dakika pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a5_003", title: "Fırında karnabahar graten", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar", "1 su bardağı süt", "1 yemek kaşığı un", "1 yemek kaşığı tereyağı", "Yarım su bardağı rendelenmiş kaşar"], steps: ["Karnabaharı çiçeklerine ayırıp hafif yumuşayana kadar haşlayın.", "Tereyağında unu kavurup sütü azar azar ekleyerek koyulaştırın.", "Karnabaharı fırın kabına alıp sosu üzerine dökün.", "Peynir serpip 190°C fırında üzeri kızarana kadar pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a5_006", title: "Tavuklu sebzeli noodle", category: "Dünya mutfağı", ingredients: ["250 g tavuk göğsü", "200 g noodle", "1 havuç", "1 kırmızı biber", "2 yemek kaşığı soya sosu", "1 yemek kaşığı sıvı yağ"], steps: ["Noodleı paket talimatına göre haşlayın.", "Tavuğu ince şeritler hâlinde kesip tavada tamamen pişirin.", "İnce doğranmış sebzeleri ekleyip diri kalacak şekilde soteleyin.", "Noodle ve soya sosunu ekleyip karıştırarak sıcak servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a5_007", title: "Fırında baharatlı patates dilimleri", category: "Pratik tarifler", ingredients: ["4 patates", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı tatlı toz biber", "1 çay kaşığı kekik"], steps: ["Patatesleri iyice yıkayıp elma dilimi şeklinde kesin.", "Yağ ve baharatlarla karıştırın.", "Tek sıra hâlinde fırın tepsisine yayın.", "200°C fırında ara sıra çevirerek yumuşayıp kızarana kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a5_008", title: "Ispanaklı peynirli börek", category: "Hamur işleri", ingredients: ["3 yufka", "300 g ıspanak", "150 g beyaz peynir", "1 yumurta", "Yarım su bardağı yoğurt", "3 yemek kaşığı sıvı yağ"], steps: ["Ispanağı yıkayıp doğrayın ve peynirle karıştırın.", "Yoğurt, yumurta ve yağı çırpın.", "Yufkaları soslayıp iç harçla rulo yaparak tepsiye dizin.", "190°C fırında üzeri kızarıp içi pişene kadar pişirin."], minutes: 50),
  GeneralRecipe(id: "p39a5_010", title: "Portakallı kereviz", category: "Sebze yemekleri", ingredients: ["2 kereviz", "1 havuç", "1 patates", "1 portakalın suyu", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı su"], steps: ["Kereviz, havuç ve patatesi soyup küp doğrayın.", "Sebzeleri zeytinyağında birkaç dakika çevirin.", "Portakal suyu ve suyu ekleyin.", "Kapağı kapalı olarak sebzeler yumuşayana kadar pişirin."], minutes: 50),
  GeneralRecipe(id: "p39a5_011", title: "Fırında yoğurtlu tavuk", category: "Tavuk yemekleri", ingredients: ["500 g tavuk but", "4 yemek kaşığı yoğurt", "1 yemek kaşığı zeytinyağı", "1 diş sarımsak", "1 çay kaşığı kekik"], steps: ["Yoğurt, yağ, sarımsak ve kekiği karıştırın.", "Tavuğu sosla kaplayıp en az 15 dakika dinlendirin.", "Tavukları fırın kabına yerleştirin.", "200°C fırında tavuk tamamen pişip iç sıcaklığı 74°C olana kadar pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a5_012", title: "Mantar sote", category: "Sebze yemekleri", ingredients: ["400 g kültür mantarı", "1 soğan", "1 yeşil biber", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Mantarları temizleyip dilimleyin.", "Soğan ve biberi yağda yumuşatın.", "Mantarları ekleyip yüksek ateşte suyunu salıp çekene kadar pişirin.", "Kekik ekleyip sıcak servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a5_013", title: "Elmalı tarçınlı kek", category: "Kek ve kurabiyeler", ingredients: ["2 elma", "3 yumurta", "1 su bardağı şeker", "1 su bardağı süt", "Yarım su bardağı sıvı yağ", "2 su bardağı un", "1 paket kabartma tozu", "1 çay kaşığı tarçın"], steps: ["Yumurta ve şekeri köpürene kadar çırpın.", "Süt ve yağı ekleyin; un, kabartma tozu ve tarçını karıştırın.", "Küp doğranmış elmaları hamura katıp kalıba dökün.", "175°C fırında ortasına batırılan kürdan temiz çıkana kadar pişirin."], minutes: 60),
  GeneralRecipe(id: "p39a5_014", title: "Nohutlu bulgur salatası", category: "Salatalar", ingredients: ["1 su bardağı ince bulgur", "1 su bardağı haşlanmış nohut", "1 salatalık", "2 domates", "Yarım demet maydanoz", "1 limon", "2 yemek kaşığı zeytinyağı"], steps: ["Bulguru sıcak suyla ıslatıp yumuşayana kadar bekletin.", "Domates, salatalık ve maydanozu küçük doğrayın.", "Haşlanmış nohudu bulgur ve sebzelerle karıştırın.", "Limon ve zeytinyağı ekleyip servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a5_015", title: "Fesleğenli domatesli makarna", category: "Makarnalar", ingredients: ["250 g makarna", "3 domates", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "6 yaprak taze fesleğen"], steps: ["Makarnayı paket talimatına göre haşlayın.", "Sarımsağı yağda kısa süre çevirip doğranmış domatesleri ekleyin.", "Sosu domatesler yumuşayana kadar pişirin.", "Makarnayı sos ve kıyılmış fesleğenle harmanlayın."], minutes: 30),
  GeneralRecipe(id: "p39a5_016", title: "Sebzeli fırın mücver", category: "Sebze yemekleri", ingredients: ["2 kabak", "1 havuç", "2 yumurta", "4 yemek kaşığı un", "Yarım demet dereotu", "2 yemek kaşığı zeytinyağı"], steps: ["Kabak ve havucu rendeleyip fazla suyunu sıkın.", "Yumurta, un, dereotu ve yağla karıştırın.", "Karışımı yağlı kâğıt serili küçük bir kaba yayın.", "190°C fırında içi tamamen pişip üzeri kızarana kadar pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a5_018", title: "Tahinli cevizli kurabiye", category: "Kek ve kurabiyeler", ingredients: ["1 su bardağı tahin", "Yarım su bardağı pudra şekeri", "1,5 su bardağı un", "Yarım su bardağı çekilmiş ceviz", "1 çay kaşığı kabartma tozu"], steps: ["Tahin ve şekeri karıştırın.", "Un, ceviz ve kabartma tozunu ekleyip yumuşak hamur elde edin.", "Hamurdan küçük parçalar alıp tepsiye dizin.", "175°C fırında kenarları hafif renk alana kadar pişirip soğutun."], minutes: 35),
  GeneralRecipe(id: "p39a5_019", title: "Peynirli köz biber salatası", category: "Salatalar", ingredients: ["3 kırmızı biber", "100 g beyaz peynir", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu", "Bir tutam maydanoz"], steps: ["Biberleri közleyip kabuklarını soyun.", "Biberleri şeritler hâlinde kesin.", "Peyniri ufalayıp biberlerle karıştırın.", "Limon, yağ ve maydanoz ekleyerek servis edin."], minutes: 20),
  GeneralRecipe(id: "p39a5_020", title: "Fırında sebzeli levrek", category: "Balık ve deniz ürünleri", ingredients: ["2 temizlenmiş levrek fileto", "1 kabak", "1 havuç", "1 limon", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Sebzeleri ince dilimleyip yağla harmanlayın.", "Sebzeleri fırın kabına yayıp üzerine balıkları yerleştirin.", "Limon dilimleri ve kekik ekleyin.", "190°C fırında balık opaklaşıp kolayca ayrılana ve sebzeler pişene kadar pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a6_001", title: "Terbiyeli tavuk çorbası", category: "Çorbalar", ingredients: ["250 g tavuk göğsü", "1 havuç", "3 yemek kaşığı yoğurt", "1 yumurta sarısı", "1 yemek kaşığı un", "5 su bardağı su"], steps: ["Tavuğu havuçla suda tamamen pişirip didikleyin.", "Yoğurt, yumurta sarısı ve unu çırpın.", "Sıcak çorba suyundan azar azar ekleyerek terbiyeyi ılıştırın.", "Terbiyeyi tencereye karıştırarak dökün, birkaç dakika kaynatın."], minutes: 35),
  GeneralRecipe(id: "p39a6_002", title: "Köz patlıcan çorbası", category: "Çorbalar", ingredients: ["2 patlıcan", "1 soğan", "1 yemek kaşığı tereyağı", "1 yemek kaşığı un", "3 su bardağı su", "1 su bardağı süt"], steps: ["Patlıcanları közleyip kabuklarını soyun.", "Soğanı tereyağında yumuşatın, unu ekleyip kısa süre kavurun.", "Doğranmış patlıcan ve suyu ekleyip 10 dakika kaynatın.", "Sütü ekleyip blenderdan geçirin ve yeniden ısıtın."], minutes: 40),
  GeneralRecipe(id: "p39a6_003", title: "Kıymalı kabak yemeği", category: "Et yemekleri", ingredients: ["3 kabak", "200 g kıyma", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı", "1 çay bardağı su"], steps: ["Soğanı yağda kavurup kıymayı ekleyin ve tamamen renk değiştirene kadar pişirin.", "Domatesleri doğrayıp tencereye alın.", "Kabakları yarım ay doğrayarak ekleyin.", "Suyu ilave edip kabaklar yumuşayana kadar kapağı kapalı pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a6_004", title: "Fırında kaşarlı tavuk", category: "Tavuk yemekleri", ingredients: ["500 g tavuk göğsü", "2 domates", "1 yeşil biber", "100 g kaşar peyniri", "2 yemek kaşığı zeytinyağı"], steps: ["Tavuğu kuşbaşı doğrayıp yağda dış yüzeyini mühürleyin.", "Doğranmış domates ve biberle fırın kabına alın.", "190°C fırında tavuk tamamen pişene kadar pişirin.", "Kaşarı serpip eriyene kadar yeniden fırınlayın."], minutes: 45),
  GeneralRecipe(id: "p39a6_006", title: "Fırında somon ve kuşkonmaz", category: "Balık ve deniz ürünleri", ingredients: ["2 somon fileto", "200 g kuşkonmaz", "1 limon", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 190°C ısıtın.", "Kuşkonmazları ayıklayıp yağ ve kekikle harmanlayın.", "Somonları sebzelerle tepsiye koyup limon sıkın.", "Somonun içi tamamen pişene kadar yaklaşık 15-20 dakika fırınlayın."], minutes: 30),
  GeneralRecipe(id: "p39a6_008", title: "Peynirli kabak mücveri", category: "Sebze yemekleri", ingredients: ["2 kabak", "2 yumurta", "100 g beyaz peynir", "4 yemek kaşığı un", "Yarım demet dereotu", "2 yemek kaşığı zeytinyağı"], steps: ["Kabakları rendeleyip suyunu sıkın.", "Yumurta, ufalanmış peynir, un ve dereotuyla karıştırın.", "Az yağlanmış tavaya kaşıkla porsiyonlar koyun.", "İki yüzünü de içi pişene kadar orta ateşte kızartın."], minutes: 35),
  GeneralRecipe(id: "p39a6_009", title: "Fırında brokoli köftesi", category: "Sebze yemekleri", ingredients: ["1 küçük brokoli", "1 yumurta", "4 yemek kaşığı galeta unu", "80 g kaşar peyniri", "1 yemek kaşığı zeytinyağı"], steps: ["Brokoliyi buharda yumuşatıp ince kıyın.", "Yumurta, galeta unu ve peynirle karıştırın.", "Karışımdan küçük köfteler şekillendirin.", "190°C fırında üzerleri kızarana kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a6_010", title: "Nohutlu pazı yemeği", category: "Sebze yemekleri", ingredients: ["1 bağ pazı", "1 su bardağı haşlanmış nohut", "1 soğan", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Pazıyı iyice yıkayıp doğrayın.", "Soğanı yağda kavurup salçayı ekleyin.", "Pazı ve haşlanmış nohudu tencereye alın.", "Suyu ekleyip pazı yumuşayana kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a6_012", title: "Sebzeli karabuğday pilavı", category: "Pilavlar", ingredients: ["1 su bardağı karabuğday", "1 havuç", "1 kabak", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "2 su bardağı su"], steps: ["Karabuğdayı yıkayıp süzün.", "Soğan, havuç ve kabağı küçük doğrayıp yağda soteleyin.", "Karabuğdayı ekleyip karıştırın.", "Suyu ekleyerek taneler yumuşayana kadar kapağı kapalı pişirin."], minutes: 35),
  GeneralRecipe(id: "p39a6_013", title: "Kremasız mantarlı makarna", category: "Makarnalar", ingredients: ["250 g makarna", "250 g mantar", "2 diş sarımsak", "3 yemek kaşığı zeytinyağı", "3 yemek kaşığı yoğurt"], steps: ["Makarnayı paket süresine göre haşlayın ve bir kepçe suyunu ayırın.", "Mantarları yağda suyunu çekene kadar soteleyin.", "Sarımsağı ekleyip kısa süre çevirin.", "Ocağı kısıp makarna, az haşlama suyu ve yoğurdu karıştırarak servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a6_014", title: "Ispanaklı lazanya", category: "Dünya mutfağı", ingredients: ["8 lazanya yaprağı", "400 g ıspanak", "200 g lor peyniri", "2 su bardağı süt", "2 yemek kaşığı un", "1 yemek kaşığı tereyağı", "100 g kaşar"], steps: ["Ispanağı yıkayıp doğrayın ve tavada suyunu çektirin.", "Tereyağı, un ve sütle beşamel sos hazırlayın.", "Fırın kabında lazanya, ıspanak, lor ve sosu kat kat dizin.", "Üzerine kaşar serpip 180°C fırında yapraklar yumuşayana kadar pişirin."], minutes: 65),
  GeneralRecipe(id: "p39a6_015", title: "Tavuklu Sezar salata", category: "Salatalar", ingredients: ["250 g tavuk göğsü", "1 küçük marul", "2 dilim tam buğday ekmeği", "3 yemek kaşığı yoğurt", "1 tatlı kaşığı hardal", "1 yemek kaşığı limon suyu"], steps: ["Tavuğu tavada tamamen pişirip dilimleyin.", "Ekmeği küp kesip fırında kızartın.", "Marulu yıkayıp doğrayın.", "Yoğurt, hardal ve limonla sos hazırlayıp tüm malzemeleri harmanlayın."], minutes: 30),
  GeneralRecipe(id: "p39a6_016", title: "Pancarlı cevizli salata", category: "Salatalar", ingredients: ["2 orta boy pancar", "1 avuç ceviz", "50 g beyaz peynir", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Pancarları yumuşayana kadar haşlayıp soğutun.", "Kabuklarını soyup küp doğrayın.", "Peyniri ufalayıp cevizi iri parçalayın.", "Zeytinyağı ve limonla karıştırarak servis edin."], minutes: 50),
  GeneralRecipe(id: "p39a6_017", title: "Kuru domatesli roka salatası", category: "Salatalar", ingredients: ["1 bağ roka", "6 kuru domates", "50 g tulum peyniri", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Rokayı yıkayıp kurulayın.", "Kuru domatesleri gerekiyorsa ılık suda yumuşatıp dilimleyin.", "Peyniri küçük parçalara ayırın.", "Tüm malzemeleri limon ve yağla harmanlayın."], minutes: 15),
  GeneralRecipe(id: "p39a6_018", title: "Fırında sütlaç", category: "Tatlılar", ingredients: ["1 çay bardağı pirinç", "1 litre süt", "1 su bardağı şeker", "2 yemek kaşığı nişasta", "2 su bardağı su"], steps: ["Pirinci suda yumuşayana kadar haşlayın.", "Süt ve şekeri ekleyip karıştırarak kaynatın.", "Nişastayı az soğuk suyla açıp karışıma ekleyin.", "Kaselere paylaştırıp üstleri kızarana kadar fırının üst ızgarasında kontrollü pişirin."], minutes: 65),
  GeneralRecipe(id: "p39a6_021", title: "Peynirli dereotlu poğaça", category: "Hamur işleri", ingredients: ["2 su bardağı un", "1 yumurta", "Yarım su bardağı yoğurt", "Yarım çay bardağı sıvı yağ", "1 paket kabartma tozu", "100 g beyaz peynir", "Yarım demet dereotu"], steps: ["Un ve kabartma tozunu karıştırın.", "Yumurta, yoğurt ve yağı ekleyip yumuşak hamur yoğurun.", "Peynir ve dereotunu ekleyerek küçük poğaçalar hazırlayın.", "180°C fırında içleri pişip üzerleri kızarana kadar pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a6_022", title: "Patatesli gözleme", category: "Hamur işleri", ingredients: ["2 su bardağı un", "Yarım su bardağı su", "2 haşlanmış patates", "1 küçük soğan", "1 yemek kaşığı zeytinyağı"], steps: ["Un ve suyla ele yapışmayan hamur yoğurup dinlendirin.", "Soğanı yağda yumuşatıp ezilmiş patatesle karıştırın.", "Hamuru bezelere ayırıp ince açın, iç koyup kapatın.", "Gözlemeleri tavada iki tarafı da kızarana kadar pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a6_024", title: "Haydari", category: "Mezeler", ingredients: ["1 su bardağı süzme yoğurt", "50 g beyaz peynir", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kuru nane"], steps: ["Beyaz peyniri çatalla ezin.", "Yoğurt ve ezilmiş sarımsakla karıştırın.", "Naneyi ve zeytinyağını ekleyin.", "Soğuk olarak servis edin."], minutes: 15),
  GeneralRecipe(id: "p39a6_025", title: "Acılı ezme", category: "Mezeler", ingredients: ["3 domates", "2 yeşil biber", "1 küçük soğan", "Yarım demet maydanoz", "1 yemek kaşığı nar ekşisi", "1 yemek kaşığı zeytinyağı"], steps: ["Domates, biber ve soğanı çok ince doğrayın.", "Maydanozu yıkayıp kıyın.", "Sebzelerin fazla suyunu süzün.", "Nar ekşisi ve zeytinyağıyla harmanlayıp servis edin."], minutes: 20),
  GeneralRecipe(id: "p39a7_001", title: "Terbiyeli kereviz çorbası", category: "Çorbalar", ingredients: ["1 kereviz", "1 havuç", "1 patates", "1 yumurta sarısı", "3 yemek kaşığı yoğurt", "1 yemek kaşığı limon suyu"], steps: ["Kereviz, havuç ve patatesi soyup küçük küpler halinde doğrayın.", "Sebzeleri üzerini örtecek kadar suda yumuşayana kadar haşlayın.", "Yoğurt, yumurta sarısı ve limonu çırpıp sıcak çorbadan birkaç kaşıkla ılıştırın.", "Terbiyeyi yavaşça tencereye katın; kaynatmadan ısıtıp servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a7_002", title: "Köz biberli domates çorbası", category: "Çorbalar", ingredients: ["4 domates", "2 közlenmiş kırmızı biber", "1 soğan", "1 yemek kaşığı un", "2 yemek kaşığı zeytinyağı", "3 su bardağı su"], steps: ["Soğanı doğrayıp yağda yumuşatın.", "Unu ekleyip kısa süre kavurun; rendelenmiş domates ve köz biberi ilave edin.", "Suyu ekleyip 15 dakika pişirin.", "Blenderdan geçirip kıvamını ayarlayarak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a7_003", title: "Arpa şehriyeli yoğurt çorbası", category: "Çorbalar", ingredients: ["Yarım su bardağı arpa şehriye", "1 su bardağı yoğurt", "1 yumurta sarısı", "1 yemek kaşığı un", "4 su bardağı su", "1 tatlı kaşığı kuru nane"], steps: ["Şehriyeyi suda yumuşayana kadar haşlayın.", "Yoğurt, yumurta sarısı ve unu pürüzsüz çırpın.", "Sıcak sudan azar azar ekleyerek terbiyeyi ılıştırın.", "Karışımı tencereye döküp karıştırarak ısıtın; nane serpin."], minutes: 30),
  GeneralRecipe(id: "p39a7_004", title: "Tavuklu nohutlu çorba", category: "Çorbalar", ingredients: ["200 g tavuk göğsü", "1 su bardağı haşlanmış nohut", "1 havuç", "1 küçük soğan", "4 su bardağı su", "1 yemek kaşığı zeytinyağı"], steps: ["Tavuğu suda tamamen pişirip didikleyin; suyunu saklayın.", "Soğan ve havucu yağda kısa süre soteleyin.", "Tavuk suyu, didiklenmiş tavuk ve nohudu ekleyin.", "Havuç yumuşayana kadar kaynatıp sıcak servis edin."], minutes: 45),
  GeneralRecipe(id: "p39a7_005", title: "Fırında patlıcan musakka", category: "Sebze yemekleri", ingredients: ["3 patlıcan", "300 g kıyma", "1 soğan", "2 domates", "1 yemek kaşığı salça", "2 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Patlıcanları dilimleyip hafif yağlayın ve 200°C fırında yumuşatın.", "Soğanı ve kıymayı tavada kavurun; salça ve domatesi ekleyin.", "Fırın kabına patlıcan ve kıymalı harcı kat kat yerleştirin.", "Suyu ekleyip 190°C fırında 25 dakika pişirin."], minutes: 65),
  GeneralRecipe(id: "p39a7_006", title: "Etli kuru bamya", category: "Et yemekleri", ingredients: ["200 g kuru bamya", "250 g kuşbaşı dana eti", "1 soğan", "2 domates", "1 limon", "2 yemek kaşığı zeytinyağı"], steps: ["Kuru bamyayı limonlu suda kısa süre haşlayıp süzün.", "Eti tencerede kavurup soğanı ekleyin.", "Rendelenmiş domatesi ve üzerini örtecek kadar suyu ilave edin.", "Et yumuşayınca bamyayı ekleyip dağılmadan pişirin."], minutes: 70),
  GeneralRecipe(id: "p39a7_008", title: "Fırında sebzeli hindi köfte", category: "Tavuk yemekleri", ingredients: ["400 g hindi kıyma", "1 küçük kabak", "1 havuç", "1 yumurta", "3 yemek kaşığı galeta unu", "1 yemek kaşığı zeytinyağı"], steps: ["Kabak ve havucu rendeleyip suyunu sıkın.", "Hindi kıyma, yumurta ve galeta unuyla yoğurun.", "Küçük köfteler yapıp yağlı kağıt serili tepsiye dizin.", "190°C fırında içleri tamamen pişene kadar yaklaşık 25 dakika pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a7_010", title: "Fırında karnabahar ve nohut", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar", "1 su bardağı haşlanmış nohut", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kimyon", "1 çay kaşığı toz kırmızı biber"], steps: ["Karnabaharı küçük çiçeklere ayırıp yıkayın.", "Haşlanmış nohutla birlikte yağ ve baharatlarla harmanlayın.", "Tek kat halinde tepsiye yayın.", "200°C fırında karnabahar yumuşayıp kenarları kızarana kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a7_011", title: "Yoğurtlu semizotu yemeği", category: "Sebze yemekleri", ingredients: ["1 bağ semizotu", "1 küçük soğan", "1 yemek kaşığı pirinç", "2 yemek kaşığı zeytinyağı", "1 su bardağı yoğurt", "1 diş sarımsak"], steps: ["Semizotunu iyice yıkayıp doğrayın.", "Soğanı yağda yumuşatıp semizotu ve pirinci ekleyin.", "Az su ilave edip pirinç pişene kadar kapağı kapalı tutun.", "Ilıdıktan sonra sarımsaklı yoğurtla servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a7_012", title: "Bulgurlu kabak dolması", category: "Sebze yemekleri", ingredients: ["4 kabak", "1 su bardağı ince bulgur", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı domates salçası"], steps: ["Kabakları ikiye bölüp içlerini oyun.", "Soğan, bulgur, rendelenmiş domates ve salçayı karıştırarak iç harcı hazırlayın.", "Kabakları fazla sıkıştırmadan doldurup tencereye dizin.", "Yarılarına kadar sıcak su ekleyip kabak ve bulgur yumuşayana kadar pişirin."], minutes: 60),
  GeneralRecipe(id: "p39a7_013", title: "Limonlu fırın çipura", category: "Balık ve deniz ürünleri", ingredients: ["2 temizlenmiş çipura", "1 limon", "1 soğan", "2 yemek kaşığı zeytinyağı", "3 dal maydanoz"], steps: ["Balıkları temizleyip kağıt havluyla kurulayın.", "Soğan ve limonu dilimleyip fırın kabına yerleştirin.", "Balıkları yağlayıp içlerine maydanoz koyun.", "190°C fırında balık eti kolay ayrılana kadar yaklaşık 25-30 dakika pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a7_014", title: "Sebzeli karides güveç", category: "Balık ve deniz ürünleri", ingredients: ["400 g ayıklanmış karides", "2 domates", "1 yeşil biber", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "80 g kaşar"], steps: ["Biber ve sarımsağı yağda soteleyin.", "Doğranmış domatesi ekleyip suyunu hafif çektirin.", "Karidesleri ekleyip opaklaşana kadar pişirin.", "Güveç kaplarına paylaştırıp kaşar serpin; 190°C fırında üstünü kızartın."], minutes: 35),
  GeneralRecipe(id: "p39a7_016", title: "Dereotlu limonlu pirinç pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pirinç", "1,5 su bardağı sıcak su", "1 yemek kaşığı tereyağı", "Yarım demet dereotu", "1 tatlı kaşığı limon suyu"], steps: ["Pirinci yıkayıp süzün.", "Tereyağında pirinci birkaç dakika kavurun.", "Sıcak suyu ekleyip kısık ateşte suyunu çektirin.", "Demlendikten sonra kıyılmış dereotu ve limon suyunu karıştırın."], minutes: 30),
  GeneralRecipe(id: "p39a7_018", title: "Fırında peynirli erişte", category: "Makarnalar", ingredients: ["250 g erişte", "1 su bardağı süt", "1 yumurta", "100 g beyaz peynir", "80 g kaşar peyniri", "1 yemek kaşığı tereyağı"], steps: ["Erişteyi hafif diri kalacak şekilde haşlayıp süzün.", "Süt, yumurta ve ufalanmış beyaz peyniri karıştırın.", "Erişteyi yağlanmış fırın kabına alıp sosla harmanlayın.", "Kaşar serpip 180°C fırında üstü kızarana kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a7_020", title: "Yeşil mercimekli pancar salatası", category: "Salatalar", ingredients: ["1 su bardağı haşlanmış yeşil mercimek", "2 haşlanmış pancar", "3 dal taze soğan", "Yarım demet maydanoz", "2 yemek kaşığı zeytinyağı", "1 limon"], steps: ["Mercimeği dağılmadan haşlayıp soğutun.", "Pancarı küp, taze soğanı ince doğrayın.", "Maydanozu kıyıp diğer malzemelerle birleştirin.", "Zeytinyağı ve limon suyuyla karıştırın."], minutes: 40),
  GeneralRecipe(id: "p39a7_021", title: "Fırında ayva tatlısı", category: "Tatlılar", ingredients: ["2 ayva", "4 yemek kaşığı şeker", "1 çubuk tarçın", "3 karanfil", "1 su bardağı su"], steps: ["Ayvaları ikiye bölüp çekirdek yuvalarını çıkarın.", "Fırın kabına dizip üzerlerine şeker paylaştırın.", "Su, tarçın ve karanfili ekleyip üzerini kapatın.", "180°C fırında yumuşayana kadar pişirip ılık servis edin."], minutes: 70),
  GeneralRecipe(id: "p39a7_022", title: "Elmalı tarçınlı crumble", category: "Dünya mutfağı", ingredients: ["3 elma", "1 çay kaşığı tarçın", "Yarım su bardağı un", "3 yemek kaşığı tereyağı", "3 yemek kaşığı esmer şeker", "3 yemek kaşığı yulaf"], steps: ["Elmaları küp doğrayıp tarçınla karıştırarak fırın kabına yayın.", "Un, tereyağı, şeker ve yulafı parmak uçlarıyla kırıntı kıvamına getirin.", "Kırıntıları elmaların üzerine dağıtın.", "180°C fırında elmalar yumuşayıp üstü kızarana kadar pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a7_023", title: "Ispanaklı lorlu krep", category: "Kahvaltılıklar", ingredients: ["2 yumurta", "1 su bardağı süt", "1 su bardağı un", "150 g ıspanak", "100 g lor", "1 yemek kaşığı zeytinyağı"], steps: ["Yumurta, süt ve unu çırpıp akışkan krep hamuru hazırlayın.", "İnce krepleri yapışmaz tavada iki yüzlü pişirin.", "Ispanağı az yağda söndürüp lorla karıştırın.", "İç harcı kreplere paylaştırıp katlayarak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a7_024", title: "Fırında yulaflı muzlu pankek", category: "Kek ve kurabiyeler", ingredients: ["2 olgun muz", "2 yumurta", "1 su bardağı yulaf unu", "Yarım su bardağı süt", "1 çay kaşığı kabartma tozu"], steps: ["Muzları ezip yumurta ve sütle karıştırın.", "Yulaf unu ve kabartma tozunu ekleyin.", "Karışımı küçük pankekler halinde yağlı kağıda dökün.", "180°C fırında içleri pişip üzerleri hafif kızarana kadar pişirin."], minutes: 30),
  GeneralRecipe(id: "p39a7_025", title: "Zeytinli kekikli mini ekmek", category: "Kek ve kurabiyeler", ingredients: ["2 su bardağı un", "1 paket instant maya", "Yarım su bardağı ılık su", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı çekirdeksiz zeytin", "1 tatlı kaşığı kekik"], steps: ["Un, maya ve suyu karıştırıp zeytinyağıyla yumuşak hamur yoğurun.", "Doğranmış zeytin ve kekiği ekleyip hamuru kabarana kadar dinlendirin.", "Küçük ekmekler şekillendirip tepsiye dizin.", "190°C fırında içleri pişip kabukları kızarana kadar pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a8_001", title: "Cevizli sarımsaklı semizotu cacığı", category: "Salatalar", ingredients: ["1 demet semizotu", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "2 yemek kaşığı ceviz"], steps: ["Semizotunu bol suyla yıkayıp kurutun", "Yoğurdu ezilmiş sarımsakla çırpın", "Semizotunu yoğurtla harmanlayın", "Üzerine zeytinyağı ve ceviz ekleyip soğuk servis edin."], minutes: 15),
  GeneralRecipe(id: "p39a8_002", title: "Fırında kabak mücver", category: "Sebze yemekleri", ingredients: ["3 kabak", "2 yumurta", "4 yemek kaşığı un", "100 g beyaz peynir", "Yarım demet dereotu", "2 yemek kaşığı zeytinyağı"], steps: ["Kabakları rendeleyip suyunu iyice sıkın", "Yumurta, un, ufalanmış peynir ve dereotunu ekleyin", "Karışımı yağlanmış fırın kabına yayın", "180°C fırında içi pişip üstü kızarana kadar yaklaşık 30 dakika pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a8_003", title: "Közlenmiş patlıcanlı bulgur salatası", category: "Salatalar", ingredients: ["2 patlıcan", "1 su bardağı ince bulgur", "1,5 su bardağı sıcak su", "2 domates", "Yarım demet maydanoz", "2 yemek kaşığı zeytinyağı", "1 limon"], steps: ["Bulguru sıcak suyla ıslatıp üzerini kapatarak şişirin", "Patlıcanları közleyip kabuklarını soyun ve doğrayın", "Domates ve maydanozu ince kıyın", "Tüm malzemeleri zeytinyağı ve limonla harmanlayın."], minutes: 40),
  GeneralRecipe(id: "p39a8_004", title: "Terbiyeli sulu köfte", category: "Et yemekleri", ingredients: ["300 g kıyma", "3 yemek kaşığı pirinç", "1 soğan", "1 havuç", "1 yumurta sarısı", "1 limon", "2 yemek kaşığı yoğurt", "5 su bardağı su"], steps: ["Kıyma, yıkanmış pirinç ve rendelenmiş soğanı yoğurup küçük köfteler yapın", "Havuçla suyu kaynatıp köfteleri ekleyin ve tamamen pişirin", "Yoğurt, yumurta sarısı ve limonu çırpıp sıcak sudan azar azar ekleyerek ılıştırın", "Terbiyeyi tencereye karıştırarak ekleyip birkaç dakika daha ısıtın."], minutes: 55),
  GeneralRecipe(id: "p39a8_005", title: "Fırında mantarlı köfte", category: "Et yemekleri", ingredients: ["400 g kıyma", "250 g mantar", "1 soğan", "1 yumurta", "3 yemek kaşığı galeta unu", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Kıyma, rendelenmiş soğan, yumurta ve galeta ununu yoğurun", "Köfteleri şekillendirip fırın kabına dizin", "Dilimlenmiş mantarları yağ ve kekikle karıştırıp aralarına yayın", "190°C fırında köftelerin içi tamamen pişene kadar pişirin."], minutes: 50),
  GeneralRecipe(id: "p39a8_006", title: "Domates soslu nohutlu pazı", category: "Sebze yemekleri", ingredients: ["1 demet pazı", "1 su bardağı haşlanmış nohut", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Pazıyı iyice yıkayıp saplarıyla birlikte doğrayın", "Soğanı yağda yumuşatıp rendelenmiş domatesi ekleyin", "Pazı, nohut ve suyu tencereye alın", "Kısık ateşte pazı yumuşayana kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a8_007", title: "Fırında limonlu hindi", category: "Et yemekleri", ingredients: ["500 g hindi göğüs", "1 limon", "2 yemek kaşığı zeytinyağı", "2 diş sarımsak", "1 çay kaşığı kekik", "2 havuç"], steps: ["Hindi etini eşit kalınlıkta dilimleyin", "Limon suyu, yağ, sarımsak ve kekikle harmanlayın", "Havuç dilimleriyle birlikte fırın kabına yerleştirin", "190°C fırında hindi tamamen pişene kadar pişirip dinlendirin."], minutes: 55),
  GeneralRecipe(id: "p39a8_008", title: "Kırmızı mercimekli sebze köftesi", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı kırmızı mercimek", "1 havuç", "1 küçük kabak", "3 yemek kaşığı yulaf unu", "1 yumurta", "1 yemek kaşığı zeytinyağı"], steps: ["Mercimeği yumuşayana kadar haşlayıp suyunu süzün", "Havuç ve kabağı rendeleyip fazla suyunu sıkın", "Mercimek, sebzeler, yumurta ve yulaf ununu karıştırıp şekil verin", "Yağlı kağıt üzerinde 190°C fırında iki yüzü kızarana kadar pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a8_009", title: "Fırında domatesli barbunya", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış barbunya", "3 domates", "1 soğan", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay bardağı su"], steps: ["Soğan ve sarımsağı yağda yumuşatın", "Rendelenmiş domatesleri ekleyip 10 dakika pişirin", "Haşlanmış barbunyayı sos ve suyla fırın kabında karıştırın", "180°C fırında sos koyulaşana kadar yaklaşık 25 dakika pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a8_010", title: "Peynirli brokoli çorbası", category: "Çorbalar", ingredients: ["1 küçük brokoli", "1 patates", "1 soğan", "4 su bardağı su", "Yarım su bardağı süt", "60 g rendelenmiş kaşar"], steps: ["Soğan ve doğranmış patatesi suyla kaynatın", "Brokoli çiçeklerini ekleyip tüm sebzeleri yumuşatın", "Çorbayı blenderdan geçirip sütü ekleyin", "Kısık ateşte ısıtıp kaşarı karıştırarak eritin."], minutes: 35),
  GeneralRecipe(id: "p39a8_011", title: "Şehriyeli domatesli tavuk çorbası", category: "Çorbalar", ingredients: ["200 g tavuk göğüs", "2 domates", "Yarım su bardağı arpa şehriye", "5 su bardağı su", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Tavuğu suda tamamen pişirip didikleyin", "Domatesleri rendeleyip yağda birkaç dakika pişirin", "Tavuk suyu, şehriye ve didiklenmiş tavuğu ekleyin", "Şehriye yumuşayınca limon suyuyla servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a8_012", title: "Kabaklı yoğurtlu erişte", category: "Makarnalar", ingredients: ["250 g erişte", "2 kabak", "1 su bardağı yoğurt", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kuru nane"], steps: ["Erişteyi paket süresine göre haşlayıp süzün", "Kabakları rendeleyip yağda suyunu çekene kadar pişirin", "Yoğurdu ezilmiş sarımsakla karıştırın", "Erişteyi kabak ve yoğurtla birleştirip nane serpin."], minutes: 30),
  GeneralRecipe(id: "p39a8_013", title: "Fırında sebzeli kuskus", category: "Dünya mutfağı", ingredients: ["1 su bardağı kuskus", "1 kabak", "1 kırmızı biber", "1 havuç", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Sebzeleri küçük küpler halinde doğrayın", "Sebzeleri yağla karıştırıp 190°C fırında yumuşatın", "Kuskusu sıcak suda paket talimatına göre pişirin", "Pişmiş kuskusu fırın sebzeleriyle harmanlayın."], minutes: 40),
  GeneralRecipe(id: "p39a8_014", title: "Karamelize soğanlı mercimek pilavı", category: "Pilavlar", ingredients: ["1 su bardağı yeşil mercimek", "1 su bardağı bulgur", "2 soğan", "3 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Mercimeği diri kalacak şekilde haşlayıp süzün", "Soğanları ince doğrayıp yağda düşük ateşte kahverengileştirin", "Bulgur, mercimek ve sıcak suyu ekleyin", "Suyunu çekene kadar pişirip soğanlarla birlikte dinlendirin."], minutes: 45),
  GeneralRecipe(id: "p39a8_015", title: "Fırında elmalı yulaf", category: "Kahvaltılıklar", ingredients: ["2 elma", "1 su bardağı yulaf ezmesi", "1 su bardağı süt", "1 yumurta", "1 çay kaşığı tarçın", "2 yemek kaşığı ceviz"], steps: ["Elmaları küçük küpler halinde doğrayın", "Yulaf, süt, yumurta ve tarçını karıştırın", "Elmaları ve cevizleri ekleyip küçük fırın kabına dökün", "180°C fırında ortası katılaşana kadar yaklaşık 25 dakika pişirin."], minutes: 35),
  GeneralRecipe(id: "p39a8_016", title: "Lor peynirli biber dolması", category: "Kahvaltılıklar", ingredients: ["4 küçük kapya biber", "150 g lor peyniri", "1 yumurta", "Yarım demet maydanoz", "1 yemek kaşığı zeytinyağı"], steps: ["Biberleri ikiye bölüp çekirdeklerini çıkarın", "Lor, yumurta ve kıyılmış maydanozu karıştırın", "Karışımı biberlerin içine doldurup yağ gezdirin", "190°C fırında yumurta tamamen pişene kadar pişirin."], minutes: 25),
  GeneralRecipe(id: "p39a8_017", title: "Portakallı irmik tatlısı", category: "Tatlılar", ingredients: ["1 su bardağı irmik", "3 su bardağı süt", "Yarım su bardağı şeker", "1 portakalın kabuğu", "1 yemek kaşığı tereyağı"], steps: ["Süt, irmik ve şekeri tencerede karıştırın", "Orta ateşte sürekli karıştırarak koyulaştırın", "Portakal kabuğu rendesi ve tereyağını ekleyin", "Kaselere paylaştırıp soğuyunca servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a8_018", title: "Kıyır tahinli ceviz kurabiyesi", category: "Kek ve kurabiyeler", ingredients: ["1 su bardağı tahin", "Yarım su bardağı pudra şekeri", "2 su bardağı un", "Yarım su bardağı ceviz", "1 çay kaşığı kabartma tozu"], steps: ["Tahin ve pudra şekerini karıştırın", "Un, kabartma tozu ve ince kıyılmış cevizi ekleyip hamur yapın", "Küçük toplar şekillendirip tepsiye dizin", "170°C fırında hafif renk alana kadar pişirip soğutun."], minutes: 35),
  GeneralRecipe(id: "p39a8_019", title: "Fırında peynirli karnabahar topları", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 küçük karnabahar", "1 yumurta", "100 g rendelenmiş kaşar", "4 yemek kaşığı galeta unu", "1 yemek kaşığı zeytinyağı"], steps: ["Karnabaharı buharda yumuşatıp iyice süzün", "Çatalla ezip yumurta, peynir ve galeta unuyla karıştırın", "Küçük toplar hazırlayıp yağlı kağıda dizin", "190°C fırında her tarafı kızarana kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a8_020", title: "Köz biberli humus", category: "Mezeler", ingredients: ["2 su bardağı haşlanmış nohut", "2 közlenmiş kırmızı biber", "2 yemek kaşığı tahin", "1 limon", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı"], steps: ["Nohutları iyice haşlayıp süzün", "Közlenmiş biberlerin kabuklarını soyun", "Nohut, biber, tahin, limon ve sarımsağı pürüzsüz olana kadar çekin", "Kıvamı suyla ayarlayıp zeytinyağıyla servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a9_001", title: "Fırında sebzeli tavuk şiş", category: "Et yemekleri", ingredients: ["500 g tavuk göğsü", "1 kabak", "1 kırmızı biber", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Tavuk ve sebzeleri eşit büyüklükte doğrayın.", "Zeytinyağı ve kekikle harmanlayın.", "Malzemeleri sırayla şişlere dizip tepsiye yerleştirin.", "200°C fırında tavuk tamamen pişene kadar yaklaşık 25 dakika pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a9_002", title: "Cevizli yoğurtlu pancar salatası", category: "Salatalar", ingredients: ["2 orta boy pancar", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "2 yemek kaşığı ceviz"], steps: ["Pancarları yıkayıp yumuşayana kadar haşlayın.", "Soğuyunca kabuklarını soyup rendeleyin.", "Yoğurt ve ezilmiş sarımsakla karıştırın.", "Üzerine zeytinyağı ve ceviz ekleyin."], minutes: 35),
  GeneralRecipe(id: "p39a9_004", title: "Fırında ıspanaklı patates", category: "Sebze yemekleri", ingredients: ["3 patates", "250 g ıspanak", "1 soğan", "2 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Patatesleri ince dilimleyip 8 dakika haşlayın.", "Ispanağı soğanla tavada suyunu çekene kadar pişirin.", "Patates ve ıspanağı fırın kabına kat kat yerleştirin.", "Çırpılmış yumurta ve sütü döküp 190°C fırında tamamen pişirin."], minutes: 50),
  GeneralRecipe(id: "p39a9_005", title: "Nohutlu karnabahar yemeği", category: "Bakliyat yemekleri", ingredients: ["1 küçük karnabahar", "1 su bardağı haşlanmış nohut", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Karnabaharı küçük çiçeklere ayırıp yıkayın.", "Soğanı yağda kavurup rendelenmiş domatesi ekleyin.", "Karnabahar, nohut ve suyu ekleyin.", "Kapağı kapalı şekilde karnabahar yumuşayana kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a9_006", title: "Limonlu dereotlu somon", category: "Balık ve deniz ürünleri", ingredients: ["2 somon fileto", "1 limon", "2 yemek kaşığı zeytinyağı", "Yarım demet dereotu", "1 diş sarımsak"], steps: ["Somon filetoları fırın kabına yerleştirin.", "Limon suyu, yağ ve ezilmiş sarımsağı karıştırıp üzerine sürün.", "180°C fırında balık tamamen pişene kadar pişirin.", "Kıyılmış dereotuyla servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a9_007", title: "Tavuklu arpa şehriye pilavı", category: "Pilavlar", ingredients: ["1 su bardağı arpa şehriye", "200 g tavuk göğsü", "1 havuç", "2 su bardağı sıcak su", "2 yemek kaşığı zeytinyağı"], steps: ["Tavuğu küçük doğrayıp tavada tamamen pişirin.", "Rendelenmiş havuç ve şehriyeyi ekleyip kavurun.", "Sıcak suyu ekleyip kapağı kapalı şekilde kısık ateşte pişirin.", "Suyunu çekince 10 dakika dinlendirin."], minutes: 40),
  GeneralRecipe(id: "p39a9_008", title: "Fırında yoğurtlu kabak", category: "Sebze yemekleri", ingredients: ["3 kabak", "1 su bardağı yoğurt", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kuru nane"], steps: ["Kabakları halka halka dilimleyin.", "Yağla harmanlayıp 200°C fırında yumuşayana kadar pişirin.", "Yoğurdu sarımsakla karıştırın.", "Ilıyan kabakların üzerine yoğurt ve nane ekleyin."], minutes: 35),
  GeneralRecipe(id: "p39a9_009", title: "Peynirli pırasalı börek", category: "Hamur işleri", ingredients: ["3 yufka", "2 pırasa", "150 g beyaz peynir", "1 yumurta", "Yarım çay bardağı süt", "3 yemek kaşığı zeytinyağı"], steps: ["Pırasaları ince doğrayıp yağda yumuşatın.", "Soğuyunca ufalanmış peynirle karıştırın.", "Yufkaların arasına harcı paylaştırıp rulo yapın.", "Üzerine sütle çırpılmış yumurta sürüp 190°C fırında kızartın."], minutes: 50),
  GeneralRecipe(id: "p39a9_010", title: "Bulgurlu yeşil mercimek salatası", category: "Salatalar", ingredients: ["1 su bardağı haşlanmış yeşil mercimek", "Yarım su bardağı ince bulgur", "1 salatalık", "1 kırmızı biber", "Yarım demet maydanoz", "1 limon", "2 yemek kaşığı zeytinyağı"], steps: ["Bulguru sıcak suyla ıslatıp şişmesini bekleyin.", "Salatalık, biber ve maydanozu doğrayın.", "Mercimek ve bulguru sebzelerle karıştırın.", "Limon ve zeytinyağı ekleyerek servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a9_011", title: "Fırında ballı tarçınlı armut", category: "Tatlılar", ingredients: ["3 armut", "2 yemek kaşığı bal", "1 çay kaşığı tarçın", "3 yemek kaşığı ceviz"], steps: ["Armutları ikiye kesip çekirdeklerini çıkarın.", "Kesik yüzleri yukarı bakacak şekilde fırın kabına dizin.", "Tarçın serpip 180°C fırında yumuşayana kadar pişirin.", "Ilıdıktan sonra bal ve ceviz ekleyin."], minutes: 30),
  GeneralRecipe(id: "p39a9_012", title: "Domatesli fesleğenli bulgur", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "2 domates", "1 soğan", "2 su bardağı sıcak su", "2 yemek kaşığı zeytinyağı", "5 yaprak fesleğen"], steps: ["Soğanı yağda yumuşatıp rendelenmiş domatesleri ekleyin.", "Bulguru ekleyip kısa süre karıştırın.", "Sıcak suyu katıp suyunu çekene kadar pişirin.", "Dinlendirip kıyılmış fesleğenle servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a9_013", title: "Fırında nohut köftesi", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış nohut", "1 küçük soğan", "1 yumurta", "3 yemek kaşığı galeta unu", "1 çay kaşığı kimyon", "2 yemek kaşığı zeytinyağı"], steps: ["Nohudu çatalla ezin veya kısa süre rondodan geçirin.", "Rendelenmiş soğan, yumurta, galeta unu ve kimyonu ekleyin.", "Küçük köfteler hazırlayıp yağlı kağıda dizin.", "190°C fırında iki yüzünü çevirerek kızartın."], minutes: 45),
  GeneralRecipe(id: "p39a9_014", title: "Sütlü kabak çorbası", category: "Çorbalar", ingredients: ["2 kabak", "1 patates", "1 soğan", "3 su bardağı su", "1 su bardağı süt", "1 yemek kaşığı zeytinyağı"], steps: ["Soğanı yağda yumuşatın.", "Doğranmış kabak ve patatesi ekleyip suyla haşlayın.", "Sebzeler yumuşayınca blenderdan geçirin.", "Sütü ekleyip taşırmadan ısıtın."], minutes: 30),
  GeneralRecipe(id: "p39a9_015", title: "Fırında patatesli alabalık", category: "Balık ve deniz ürünleri", ingredients: ["2 temizlenmiş alabalık", "2 patates", "1 limon", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Patatesleri ince dilimleyip fırın kabına yayın.", "Üzerine temizlenmiş alabalıkları yerleştirin.", "Limon suyu, yağ ve kekik ekleyin.", "190°C fırında balık tamamen pişene ve patatesler yumuşayana kadar pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a9_016", title: "Yoğurtlu havuçlu makarna", category: "Makarnalar", ingredients: ["250 g makarna", "2 havuç", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı"], steps: ["Makarnayı paket talimatına göre haşlayıp süzün.", "Havucu rendeleyip yağda yumuşatın.", "Yoğurtla ezilmiş sarımsağı karıştırın.", "Ilık makarnayı havuç ve yoğurtla harmanlayın."], minutes: 25),
  GeneralRecipe(id: "p39a9_017", title: "Fırında peynirli domates", category: "Kahvaltılıklar", ingredients: ["4 domates", "120 g lor peyniri", "1 yumurta", "Yarım demet maydanoz", "1 yemek kaşığı zeytinyağı"], steps: ["Domatesleri ikiye bölüp çekirdekli iç kısmını biraz çıkarın.", "Lor, yumurta ve maydanozu karıştırın.", "Harcı domateslere doldurup yağ gezdirin.", "190°C fırında yumurta tamamen pişene kadar pişirin."], minutes: 25),
  GeneralRecipe(id: "p39a9_018", title: "Portakallı havuçlu kek", category: "Kek ve kurabiyeler", ingredients: ["2 havuç", "2 yumurta", "1 su bardağı un", "Yarım su bardağı şeker", "Yarım su bardağı sıvı yağ", "1 portakalın kabuğu", "1 paket kabartma tozu"], steps: ["Yumurta ve şekeri çırpıp yağı ekleyin.", "Rendelenmiş havuç ve portakal kabuğunu karıştırın.", "Un ve kabartma tozunu ekleyip kalıba dökün.", "175°C fırında kürdan temiz çıkana kadar pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a9_019", title: "Köz patlıcanlı yoğurt mezesi", category: "Mezeler", ingredients: ["2 patlıcan", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı limon suyu"], steps: ["Patlıcanları ocakta veya fırında tamamen yumuşayana kadar közleyin.", "Kabuklarını soyup içini ince doğrayın.", "Yoğurt, sarımsak ve limonla karıştırın.", "Zeytinyağı gezdirerek soğuk servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a9_020", title: "Sebzeli yumurtalı pirinç", category: "Pilavlar", ingredients: ["1 su bardağı pirinç", "2 yumurta", "1 havuç", "Yarım su bardağı bezelye", "2 yemek kaşığı zeytinyağı", "1,5 su bardağı sıcak su"], steps: ["Pirinci yıkayıp sıcak suyla suyunu çekene kadar pişirin.", "Havuç ve bezelyeyi ayrı tavada yumuşatın.", "Yumurtaları ekleyip tamamen pişene kadar karıştırın.", "Pişmiş pirinci ekleyip tüm malzemeleri birkaç dakika harmanlayın."], minutes: 35),
  GeneralRecipe(id: "p39a10_001", title: "Fırında sebzeli tavuk güveç", category: "Tavuk yemekleri", ingredients: ["400 g kuşbaşı tavuk", "1 kabak", "1 patlıcan", "2 domates", "1 kapya biber", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C ısıtın; sebzeleri küp doğrayın.", "Tavuğu ve sebzeleri fırın kabına alın.", "Zeytinyağı ve yarım çay bardağı su ekleyip karıştırın.", "Üzerini kapatarak tavuk tamamen pişene kadar yaklaşık 40 dakika fırınlayın."], minutes: 55),
  GeneralRecipe(id: "p39a10_002", title: "Cevizli yoğurtlu semizotu kasesi", category: "Salatalar", ingredients: ["1 demet semizotu", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı"], steps: ["Semizotunu bol suda yıkayıp süzün.", "Yoğurdu ezilmiş sarımsakla karıştırın.", "Semizotunu yoğurda ekleyin.", "Zeytinyağı gezdirip soğuk servis edin."], minutes: 15),
  GeneralRecipe(id: "p39a10_005", title: "Kırmızı mercimekli kabak çorbası", category: "Çorbalar", ingredients: ["Yarım su bardağı kırmızı mercimek", "2 kabak", "1 soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Soğanı doğrayıp yağda yumuşatın.", "Kabak ve yıkanmış mercimeği ekleyin.", "Suyu koyup 25 dakika kaynatın.", "Blenderdan geçirip sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a10_006", title: "Domatesli barbunya pilaki", category: "Sebze yemekleri", ingredients: ["2 su bardağı haşlanmış barbunya", "2 domates", "1 havuç", "1 soğan", "3 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Soğan ve havucu doğrayıp zeytinyağında yumuşatın.", "Rendelenmiş domatesleri ekleyip 5 dakika pişirin.", "Haşlanmış barbunya ve suyu ekleyin.", "Kısık ateşte 20 dakika pişirip ılıtarak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a10_007", title: "Fırında peynirli kabak ruloları", category: "Sebze yemekleri", ingredients: ["2 kabak", "100 g lor peyniri", "2 yemek kaşığı yoğurt", "1 yemek kaşığı zeytinyağı", "1 tutam dereotu"], steps: ["Kabakları uzunlamasına ince dilimleyin.", "Dilimleri yağlayıp 190°C fırında 10 dakika yumuşatın.", "Lor, yoğurt ve dereotunu karıştırın.", "Kabaklara harç koyup sarın ve 10 dakika daha fırınlayın."], minutes: 35),
  GeneralRecipe(id: "p39a10_008", title: "Bulgurlu yeşil mercimek çorbası", category: "Çorbalar", ingredients: ["Yarım su bardağı yeşil mercimek", "3 yemek kaşığı bulgur", "1 soğan", "1 yemek kaşığı domates salçası", "5 su bardağı su"], steps: ["Mercimeği yıkayıp 15 dakika ön haşlayın.", "Soğanı kavurup salçayı ekleyin.", "Mercimek, bulgur ve suyu tencereye alın.", "Bakliyatlar tamamen yumuşayana kadar 25 dakika pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a10_009", title: "Tahinli havuç salatası", category: "Salatalar", ingredients: ["3 havuç", "2 yemek kaşığı tahin", "2 yemek kaşığı yoğurt", "1 yemek kaşığı limon suyu", "1 yemek kaşığı zeytinyağı"], steps: ["Havuçları rendeleyin.", "Zeytinyağında 5 dakika soteleyip soğutun.", "Tahin, yoğurt ve limon suyunu çırpın.", "Havuçlarla harmanlayıp servis edin."], minutes: 20),
  GeneralRecipe(id: "p39a10_010", title: "Fırında domatesli köfte", category: "Et yemekleri", ingredients: ["400 g kıyma", "1 küçük soğan", "2 yemek kaşığı galeta unu", "3 domates", "1 yemek kaşığı zeytinyağı"], steps: ["Kıymayı rendelenmiş soğan ve galeta unuyla yoğurun.", "Küçük köfteler şekillendirin.", "Domatesleri dilimleyip köftelerle fırın kabına dizin.", "190°C fırında köftelerin içi tamamen pişene kadar yaklaşık 30 dakika pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a10_011", title: "Portakallı kereviz salatası", category: "Salatalar", ingredients: ["1 küçük kereviz", "1 portakal", "1 havuç", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Kereviz ve havucu soyup rendeleyin.", "Portakalı soyup küçük parçalara ayırın.", "Limon suyunu kerevize ekleyerek kararmasını önleyin.", "Tüm malzemeleri zeytinyağıyla karıştırın."], minutes: 20),
  GeneralRecipe(id: "p39a10_013", title: "Kabaklı bulgur pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "1 kabak", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Soğanı ve kabağı küçük doğrayın.", "Yağda soğanı yumuşatıp kabağı ekleyin.", "Bulguru katıp kısa süre karıştırın.", "Sıcak suyu ekleyip kısık ateşte suyunu çekene kadar pişirin."], minutes: 30),
  GeneralRecipe(id: "p39a10_014", title: "Elmalı tarçınlı fırın yulaf", category: "Kahvaltılıklar", ingredients: ["1 su bardağı yulaf", "1 elma", "1 yumurta", "Yarım su bardağı süt", "1 çay kaşığı tarçın"], steps: ["Fırını 180°C ısıtın.", "Elmayı rendeleyin ve diğer malzemelerle karıştırın.", "Küçük yağlanmış kaba dökün.", "Üzeri kızarıp ortası pişene kadar 25 dakika fırınlayın."], minutes: 35),
  GeneralRecipe(id: "p39a10_015", title: "Fırında nohutlu patlıcan", category: "Sebze yemekleri", ingredients: ["2 patlıcan", "1 su bardağı haşlanmış nohut", "2 domates", "1 soğan", "2 yemek kaşığı zeytinyağı"], steps: ["Patlıcanları küp doğrayıp 190°C fırında 15 dakika yumuşatın.", "Soğanı yağda soteleyip domatesi ekleyin.", "Nohudu ve patlıcanları sosla harmanlayın.", "Fırında 20 dakika daha pişirin."], minutes: 50),
  GeneralRecipe(id: "p39a10_016", title: "Limonlu ıspanak salatası", category: "Salatalar", ingredients: ["150 g bebek ıspanak", "1 salatalık", "1 avuç ceviz", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Ispanağı ve salatalığı yıkayıp kurulayın.", "Salatalığı ince doğrayın.", "Cevizi iri kırıp sebzelerle karıştırın.", "Limon ve zeytinyağı ekleyerek servis edin."], minutes: 15),
  GeneralRecipe(id: "p39a10_017", title: "Peynirli mısır unlu muffin", category: "Kek ve kurabiyeler", ingredients: ["1 su bardağı mısır unu", "Yarım su bardağı yoğurt", "2 yumurta", "80 g beyaz peynir", "1 paket kabartma tozu", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 180°C ısıtın.", "Yumurta, yoğurt ve yağı çırpın.", "Mısır unu, kabartma tozu ve ufalanmış peyniri ekleyin.", "Muffin kalıplarında içleri tamamen pişene kadar 20-25 dakika fırınlayın."], minutes: 35),
  GeneralRecipe(id: "p39a10_018", title: "Fırında armutlu crumble", category: "Dünya mutfağı", ingredients: ["3 armut", "Yarım su bardağı yulaf", "2 yemek kaşığı un", "2 yemek kaşığı tereyağı", "1 çay kaşığı tarçın"], steps: ["Fırını 180°C ısıtın.", "Armutları dilimleyip küçük fırın kabına yerleştirin.", "Yulaf, un, tereyağı ve tarçını ufalanan bir karışım yapın.", "Armutların üzerine serpip 25 dakika pişirin."], minutes: 35),
  GeneralRecipe(id: "p39a10_019", title: "Sarımsaklı fırın brokoli", category: "Sebze yemekleri", ingredients: ["1 küçük brokoli", "2 yemek kaşığı zeytinyağı", "2 diş sarımsak", "1 yemek kaşığı limon suyu"], steps: ["Fırını 200°C ısıtın.", "Brokoliyi küçük çiçeklere ayırıp yıkayın.", "Yağ ve ezilmiş sarımsakla harmanlayın.", "Tepside 20 dakika pişirip limonla servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a10_020", title: "Tavuklu sebzeli kuskus", category: "Dünya mutfağı", ingredients: ["1 su bardağı kuskus", "200 g tavuk göğsü", "1 havuç", "1 küçük kabak", "2 yemek kaşığı zeytinyağı"], steps: ["Kuskusu paket talimatına göre haşlayıp süzün.", "Tavuğu küçük doğrayıp tavada tamamen pişirin.", "Havuç ve kabağı ekleyip yumuşayana kadar soteleyin.", "Kuskusu ekleyip karıştırarak sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a11_001", title: "Zerdeçallı mercimek çorbası", category: "Çorbalar", ingredients: ["1 su bardağı kırmızı mercimek", "1 havuç", "1 küçük soğan", "1 çay kaşığı zerdeçal", "1 yemek kaşığı zeytinyağı", "5 su bardağı su"], steps: ["Mercimeği yıkayın, havuç ve soğanı doğrayın.", "Soğanı yağda soteleyip havuç ve mercimeği ekleyin.", "Suyu ve zerdeçalı katıp 25 dakika pişirin.", "Blenderdan geçirip sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a11_002", title: "Fırında yoğurtlu karnabahar", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar", "1 su bardağı yoğurt", "1 yumurta", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı tatlı toz biber"], steps: ["Fırını 190°C ısıtın; karnabaharı çiçeklere ayırın.", "Karnabaharı kaynar suda 5 dakika ön haşlayıp süzün.", "Yoğurt, yumurta, yağ ve baharatı çırpın.", "Karnabaharı sosla karıştırıp fırında 25 dakika kızartın."], minutes: 40),
  GeneralRecipe(id: "p39a11_003", title: "Tavuklu nohut yemeği", category: "Tavuk yemekleri", ingredients: ["300 g kuşbaşı tavuk", "1,5 su bardağı haşlanmış nohut", "1 soğan", "2 domates", "1 yemek kaşığı salça", "2 yemek kaşığı zeytinyağı"], steps: ["Soğanı doğrayıp yağda kavurun; tavuğu ekleyin.", "Tavukların dışı renk değiştirince salça ve domatesi ekleyin.", "Nohudu ve 1 su bardağı sıcak suyu katın.", "Tavuk tamamen pişene kadar yaklaşık 20 dakika kısık ateşte pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a11_004", title: "Köz patlıcanlı bulgur pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "2 patlıcan", "1 soğan", "1 domates", "2 su bardağı sıcak su", "2 yemek kaşığı zeytinyağı"], steps: ["Patlıcanları közleyip kabuklarını soyun ve doğrayın.", "Soğanı yağda kavurup rendelenmiş domatesi ekleyin.", "Bulguru ve sıcak suyu katıp kapağı kapalı pişirin.", "Suyunu çekince patlıcanı karıştırıp 10 dakika dinlendirin."], minutes: 45),
  GeneralRecipe(id: "p39a11_005", title: "Fırında hardallı somon", category: "Balık ve deniz ürünleri", ingredients: ["2 dilim somon fileto", "1 tatlı kaşığı hardal", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu", "1 diş sarımsak"], steps: ["Fırını 190°C ısıtın.", "Hardal, yağ, limon ve ezilmiş sarımsağı karıştırın.", "Sosu somonların üzerine sürüp fırın kabına yerleştirin.", "Balık opaklaşıp kolay ayrılana kadar yaklaşık 15-20 dakika pişirin."], minutes: 30),
  GeneralRecipe(id: "p39a11_006", title: "Beşamel soslu ıspanaklı patates", category: "Sebze yemekleri", ingredients: ["3 patates", "250 g ıspanak", "1 soğan", "1 su bardağı süt", "1 yemek kaşığı un", "1 yemek kaşığı zeytinyağı"], steps: ["Patatesleri ince dilimleyip 8 dakika haşlayın.", "Soğanı ve ıspanağı yağda suyunu çekene kadar soteleyin.", "Süt ve unu çırparak küçük tencerede koyulaştırın.", "Patates ve ıspanağı fırın kabına dizip sosu dökün; 190°C fırında 25 dakika pişirin."], minutes: 50),
  GeneralRecipe(id: "p39a11_007", title: "Kuru domatesli makarna", category: "Makarnalar", ingredients: ["250 g makarna", "8 adet kuru domates", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 avuç fesleğen"], steps: ["Makarnayı paket talimatına göre haşlayıp bir kepçe suyunu ayırın.", "Kuru domatesleri sıcak suda yumuşatıp doğrayın.", "Sarımsağı yağda hafifçe çevirip domatesleri ekleyin.", "Makarnayı, biraz haşlama suyunu ve fesleğeni ekleyerek karıştırın."], minutes: 25),
  GeneralRecipe(id: "p39a11_008", title: "Cevizli yoğurtlu semizotu salatası", category: "Salatalar", ingredients: ["1 bağ semizotu", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "2 yemek kaşığı ceviz"], steps: ["Semizotunu bol suyla yıkayıp iyice kurulayın.", "Yoğurdu ezilmiş sarımsakla karıştırın.", "Semizotunu yoğurtla harmanlayın.", "Üzerine zeytinyağı ve ceviz ekleyip servis edin."], minutes: 15),
  GeneralRecipe(id: "p39a11_009", title: "Soğanlı mantarlı arpa şehriye pilavı", category: "Pilavlar", ingredients: ["1 su bardağı arpa şehriye", "200 g mantar", "1 küçük soğan", "2 su bardağı sıcak su", "2 yemek kaşığı zeytinyağı"], steps: ["Mantarları dilimleyip soğanı doğrayın.", "Soğanı yağda kavurup mantarı ekleyin ve suyunu çektirin.", "Arpa şehriyeyi ekleyip 2 dakika kavurun.", "Sıcak suyu ilave edip suyunu çekene kadar kısık ateşte pişirin."], minutes: 30),
  GeneralRecipe(id: "p39a11_010", title: "Portakallı zeytinyağlı pırasa", category: "Sebze yemekleri", ingredients: ["4 pırasa", "1 havuç", "1 portakalın suyu", "2 yemek kaşığı pirinç", "3 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Pırasaları ve havucu yıkayıp verev doğrayın.", "Sebzeleri yağda 4 dakika çevirin.", "Yıkanmış pirinç, portakal suyu ve suyu ekleyin.", "Kapağı kapalı şekilde sebzeler yumuşayana kadar 25 dakika pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a11_011", title: "Kıymalı karnabahar yemeği", category: "Et yemekleri", ingredients: ["250 g az yağlı kıyma", "1 küçük karnabahar", "1 soğan", "2 domates", "1 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Soğanı yağda kavurup kıymayı ekleyerek rengi dönene kadar pişirin.", "Doğranmış domatesleri ilave edin.", "Karnabahar çiçeklerini ve suyu ekleyin.", "Karnabahar yumuşayana ve kıyma tamamen pişene kadar 25 dakika pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a11_012", title: "Fırında peynirli kabak dilimleri", category: "Diyet ve sağlıklı tarifler", ingredients: ["2 kabak", "60 g rendelenmiş kaşar", "1 yumurta", "3 yemek kaşığı galeta unu", "1 tatlı kaşığı zeytinyağı"], steps: ["Fırını 200°C ısıtın ve kabakları kalın halkalar halinde dilimleyin.", "Yumurtayı çırpıp kaşar ve galeta ununu ayrı kapta karıştırın.", "Kabakları önce yumurtaya sonra peynirli karışıma bulayın.", "Yağlı kâğıt serili tepside 20-25 dakika kızartın."], minutes: 35),
  GeneralRecipe(id: "p39a11_013", title: "Tarçınlı kabak tatlısı", category: "Tatlılar", ingredients: ["600 g bal kabağı", "3 yemek kaşığı toz şeker", "Yarım su bardağı su", "1 çay kaşığı tarçın", "2 yemek kaşığı ceviz"], steps: ["Kabağı soyup iri küpler halinde doğrayın.", "Tencereye kabak, şeker ve suyu alın.", "Kapağı kapalı olarak kabak yumuşayana kadar 25 dakika pişirin.", "Soğuyunca tarçın ve cevizle servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a11_014", title: "Sebzeli fırın mücver topları", category: "Diyet ve sağlıklı tarifler", ingredients: ["2 kabak", "1 havuç", "2 yumurta", "4 yemek kaşığı un", "Yarım demet dereotu", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C ısıtın.", "Kabak ve havucu rendeleyip fazla suyunu iyice sıkın.", "Yumurta, un, dereotu ve yağı karıştırın.", "Kaşıkla küçük porsiyonlar koyup 25 dakika, içleri pişene kadar fırınlayın."], minutes: 35),
  GeneralRecipe(id: "p39a11_015", title: "Limonlu tavuklu pirinç pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pirinç", "200 g tavuk göğsü", "1,5 su bardağı sıcak tavuk suyu", "1 yemek kaşığı tereyağı", "1 yemek kaşığı limon suyu"], steps: ["Pirinci yıkayıp 15 dakika ılık suda bekletin ve süzün.", "Tavuğu ayrı tavada tamamen pişirip küçük parçalara ayırın.", "Pirinci tereyağında kavurup sıcak suyu ekleyin ve kapağı kapalı pişirin.", "Suyunu çekince tavuk ve limonu ekleyip 10 dakika dinlendirin."], minutes: 40),
  GeneralRecipe(id: "p39a11_016", title: "Brokolili peynirli krep", category: "Kahvaltılıklar", ingredients: ["1 yumurta", "Yarım su bardağı süt", "Yarım su bardağı un", "1 su bardağı küçük brokoli çiçeği", "50 g beyaz peynir"], steps: ["Brokoliyi 5 dakika buharda pişirip ince kıyın.", "Yumurta, süt ve unu pürüzsüz olana kadar çırpın.", "Brokoli ve ufalanmış peyniri hamura karıştırın.", "Az yağlanmış tavada küçük kreplerin iki yüzünü de tamamen pişirin."], minutes: 25),
  GeneralRecipe(id: "p39a11_017", title: "Fırında limonlu levrek", category: "Balık ve deniz ürünleri", ingredients: ["2 temizlenmiş levrek fileto", "1 limon", "1 küçük kırmızı soğan", "2 yemek kaşığı zeytinyağı", "3 dal maydanoz"], steps: ["Fırını 190°C ısıtın.", "Soğan ve limonu ince dilimleyip fırın kabına yerleştirin.", "Levrekleri üzerine koyup yağ gezdirin.", "Balık tamamen pişene kadar 18-22 dakika fırınlayıp maydanozla servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a11_018", title: "Elmalı yoğurtlu kup", category: "Tatlılar", ingredients: ["1 elma", "1 su bardağı yoğurt", "3 yemek kaşığı yulaf", "1 çay kaşığı tarçın", "1 tatlı kaşığı bal"], steps: ["Elmayı küçük doğrayıp tavada 3-4 dakika yumuşatın ve soğutun.", "Yoğurdu balla karıştırın.", "Bardağa yoğurt, yulaf ve elmayı kat kat yerleştirin.", "Tarçın serpip bekletmeden servis edin."], minutes: 15),
  GeneralRecipe(id: "p39a11_019", title: "Domatesli yeşil mercimek güveci", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı yeşil mercimek", "2 domates", "1 soğan", "1 havuç", "2 yemek kaşığı zeytinyağı", "2 su bardağı su"], steps: ["Mercimeği yıkayıp 15 dakika ön haşlayın ve süzün.", "Soğan ve havucu yağda yumuşatın.", "Domates, mercimek ve suyu ekleyin.", "Mercimek tamamen yumuşayana kadar 20-25 dakika pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a11_020", title: "Yoğurtlu dereotlu peynir poğaçası", category: "Hamur işleri", ingredients: ["2 su bardağı un", "1 su bardağı yoğurt", "1 yumurta", "Yarım çay bardağı zeytinyağı", "1 paket kabartma tozu", "100 g beyaz peynir", "Yarım demet dereotu"], steps: ["Fırını 180°C ısıtın.", "Yoğurt, yumurta ve yağı karıştırıp un ve kabartma tozunu ekleyin.", "Peynir ve doğranmış dereotunu katıp yumuşak hamur hazırlayın.", "Şekil verip tepside 25-30 dakika içleri pişene kadar fırınlayın."], minutes: 45),
  GeneralRecipe(id: "p39a12_001", title: "Fırında yoğurt soslu patates", category: "Sebze yemekleri", ingredients: ["3 patates", "3 yemek kaşığı yoğurt", "1 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 200°C ısıtın ve patatesleri elma dilimleyin.", "Yoğurt, yağ ve kekiği çırpıp patateslere yedirin.", "Patatesleri tepsiye tek kat dizin.", "25-30 dakika, içleri yumuşayıp dışları kızarana kadar pişirin."], minutes: 35),
  GeneralRecipe(id: "p39a12_002", title: "Tahinli limonlu nohut salatası", category: "Salatalar", ingredients: ["2 su bardağı haşlanmış nohut", "1 salatalık", "1 kapya biber", "2 yemek kaşığı tahin", "2 yemek kaşığı limon suyu"], steps: ["Salatalık ve biberi küçük doğrayın.", "Tahin ve limonu 2 yemek kaşığı suyla açın.", "Nohutları sebzelerle birleştirin.", "Sosu ekleyip karıştırarak servis edin."], minutes: 20),
  GeneralRecipe(id: "p39a12_003", title: "Kıymalı yeşil mercimek yemeği", category: "Bakliyat yemekleri", ingredients: ["1 su bardağı yeşil mercimek", "200 g kıyma", "1 soğan", "1 yemek kaşığı salça", "2 yemek kaşığı zeytinyağı", "3 su bardağı su"], steps: ["Mercimeği yıkayıp 15 dakika ön haşlayın.", "Soğanı yağda soteleyip kıymayı tamamen pişene kadar kavurun.", "Salçayı, mercimeği ve suyu ekleyin.", "Mercimekler yumuşayana kadar 20-25 dakika kaynatın."], minutes: 50),
  GeneralRecipe(id: "p39a12_004", title: "Köz biberli lorlu omlet", category: "Kahvaltılıklar", ingredients: ["2 yumurta", "1 közlenmiş kapya biber", "3 yemek kaşığı lor", "1 tatlı kaşığı zeytinyağı"], steps: ["Köz biberi küçük doğrayın.", "Yumurtaları çırpıp lor ve biberi ekleyin.", "Karışımı hafif yağlı tavaya dökün.", "İki tarafını da yumurta tamamen pişene kadar pişirin."], minutes: 15),
  GeneralRecipe(id: "p39a12_005", title: "Fırında kekikli barbunya güveci", category: "Kek ve kurabiyeler", ingredients: ["2 su bardağı haşlanmış barbunya", "3 domates", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 çay bardağı sıcak su"], steps: ["Fırını 190°C ısıtın.", "Soğanı yağda soteleyip doğranmış domatesleri ekleyin.", "Haşlanmış barbunyayı ve suyu karıştırıp fırın kabına aktarın.", "25 dakika fırınlayıp sıcak servis edin."], minutes: 45),
  GeneralRecipe(id: "p39a12_006", title: "Limonlu taze naneli pirinç pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pirinç", "1,5 su bardağı sıcak su", "1 yemek kaşığı tereyağı", "Yarım demet dereotu", "1 yemek kaşığı limon suyu"], steps: ["Pirinci yıkayıp 15 dakika ılık suda bekletin ve süzün.", "Tereyağında pirinci 2 dakika kavurun.", "Sıcak suyu ekleyip kısık ateşte suyunu çektirin.", "Dereotu ve limonu ekleyip 10 dakika dinlendirin."], minutes: 35),
  GeneralRecipe(id: "p39a12_007", title: "Fırında kabaklı tavuk köftesi", category: "Tavuk yemekleri", ingredients: ["300 g tavuk kıyması", "1 küçük kabak", "1 yumurta", "3 yemek kaşığı galeta unu", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C ısıtın.", "Kabağı rendeleyip suyunu iyice sıkın.", "Tavuk kıyması, kabak, yumurta ve galeta ununu yoğurup köfteler şekillendirin.", "Yağlı kâğıt üzerinde 25-30 dakika, tavuk tamamen pişene kadar fırınlayın."], minutes: 40),
  GeneralRecipe(id: "p39a12_008", title: "Ispanaklı nohut sote", category: "Sebze yemekleri", ingredients: ["300 g ıspanak", "1,5 su bardağı haşlanmış nohut", "1 soğan", "1 yemek kaşığı zeytinyağı", "1 domates"], steps: ["Ispanağı iyice yıkayıp doğrayın.", "Soğanı yağda soteleyip doğranmış domatesi ekleyin.", "Nohut ve ıspanağı ilave edin.", "Ispanak tamamen yumuşayana kadar 10-12 dakika pişirin."], minutes: 30),
  GeneralRecipe(id: "p39a12_009", title: "Portakallı havuç çorbası", category: "Çorbalar", ingredients: ["4 havuç", "1 küçük patates", "1 soğan", "3 su bardağı su", "Yarım su bardağı portakal suyu", "1 yemek kaşığı zeytinyağı"], steps: ["Havuç, patates ve soğanı doğrayın.", "Soğanı yağda soteleyip diğer sebzeleri ve suyu ekleyin.", "Sebzeler yumuşayana kadar 20 dakika kaynatın.", "Blenderdan geçirip portakal suyunu ekleyerek kısa süre ısıtın."], minutes: 35),
  GeneralRecipe(id: "p39a12_010", title: "Yoğurtlu fırın patlıcan", category: "Mezeler", ingredients: ["2 patlıcan", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 210°C ısıtın.", "Patlıcanları birkaç yerinden delip 25-30 dakika yumuşayana kadar közleyin.", "Soğuyunca kabuklarını soyup içini doğrayın.", "Sarımsaklı yoğurtla karıştırıp üzerine yağ gezdirin."], minutes: 40),
  GeneralRecipe(id: "p39a12_011", title: "Tavuklu bezelyeli bulgur", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "200 g tavuk göğsü", "1 su bardağı bezelye", "1 küçük soğan", "2 su bardağı sıcak su", "1 yemek kaşığı zeytinyağı"], steps: ["Tavuğu küçük doğrayıp yağda tamamen pişirin.", "Soğanı ekleyip yumuşatın.", "Bulgur, bezelye ve sıcak suyu ekleyin.", "Kısık ateşte bulgur yumuşayana kadar pişirip 10 dakika dinlendirin."], minutes: 40),
  GeneralRecipe(id: "p39a12_012", title: "Fırında tahinli karnabahar", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar", "2 yemek kaşığı tahin", "1 yemek kaşığı limon suyu", "1 yemek kaşığı zeytinyağı", "2 yemek kaşığı su"], steps: ["Fırını 200°C ısıtın.", "Karnabaharı çiçeklerine ayırıp yıkayın.", "Tahin, limon, yağ ve suyu çırpıp karnabaharı soslayın.", "Tepside 25-30 dakika yumuşayana kadar pişirin."], minutes: 35),
  GeneralRecipe(id: "p39a12_013", title: "Peynirli ıspanaklı mini börek", category: "Hamur işleri", ingredients: ["3 yufka", "250 g ıspanak", "100 g beyaz peynir", "1 yumurta", "2 yemek kaşığı yoğurt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C ısıtın.", "Ispanağı yıkayıp ince kıyın ve peynirle karıştırın.", "Yufkaları parçalara ayırıp iç harçla küçük rulolar yapın.", "Yumurta, yoğurt ve yağ karışımını sürüp 25 dakika kızarana kadar pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a12_014", title: "Narlı yoğurtlu havuç mezesi", category: "Mezeler", ingredients: ["3 havuç", "1 su bardağı yoğurt", "1 yemek kaşığı zeytinyağı", "2 yemek kaşığı nar tanesi", "1 diş sarımsak"], steps: ["Havuçları rendeleyip yağda 5-6 dakika yumuşatın.", "Havuçları tamamen soğutun.", "Yoğurdu sarımsakla karıştırıp havuçları ekleyin.", "Nar taneleriyle süsleyerek servis edin."], minutes: 20),
  GeneralRecipe(id: "p39a12_015", title: "Fırında elmalı irmik kup", category: "Tatlılar", ingredients: ["2 elma", "4 yemek kaşığı irmik", "2 su bardağı süt", "2 yemek kaşığı şeker", "1 çay kaşığı tarçın"], steps: ["Fırını 180°C ısıtın.", "Süt, irmik ve şekeri tencerede karıştırarak koyulaştırın.", "Elmaları rendeleyip tarçınla karıştırın.", "Küçük kaplara irmik ve elmayı kat kat koyup 15 dakika fırınlayın."], minutes: 35),
  GeneralRecipe(id: "p39a12_016", title: "Limonlu sarımsaklı fırın alabalık", category: "Balık ve deniz ürünleri", ingredients: ["2 temizlenmiş alabalık", "1 limon", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "3 dal maydanoz"], steps: ["Fırını 190°C ısıtın.", "Balıkları temizleyip kurulayın.", "Limon, ezilmiş sarımsak ve yağı karıştırıp balıklara sürün.", "Balık tamamen pişene kadar 20-25 dakika fırınlayıp maydanozla servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a12_017", title: "Mantarlı yeşil mercimek makarnası", category: "Makarnalar", ingredients: ["200 g makarna", "1 su bardağı haşlanmış yeşil mercimek", "200 g mantar", "1 soğan", "2 yemek kaşığı zeytinyağı"], steps: ["Makarnayı paket talimatına göre haşlayıp süzün.", "Soğan ve mantarı yağda soteleyip suyunu çektirin.", "Haşlanmış mercimeği ekleyip 3 dakika ısıtın.", "Makarnayla karıştırarak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a12_018", title: "Domatesli peynirli fırın kabak", category: "Sebze yemekleri", ingredients: ["3 kabak", "2 domates", "100 g beyaz peynir", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 190°C ısıtın.", "Kabak ve domatesleri halka dilimleyin.", "Sebzeleri fırın kabına sıralayıp yağ ve kekik gezdirin.", "Üzerine ufalanmış peynir ekleyip 25-30 dakika pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a12_019", title: "Zencefilli balkabağı çorbası", category: "Çorbalar", ingredients: ["400 g balkabağı", "1 havuç", "1 soğan", "3 su bardağı su", "1 çay kaşığı rendelenmiş taze zencefil", "1 yemek kaşığı zeytinyağı"], steps: ["Soğanı yağda yumuşatın.", "Doğranmış kabak, havuç, zencefil ve suyu ekleyin.", "Sebzeler yumuşayana kadar 20 dakika pişirin.", "Blenderdan geçirip sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a12_020", title: "Cevizli muzlu yulaf kurabiyesi", category: "Kek ve kurabiyeler", ingredients: ["2 olgun muz", "1,5 su bardağı yulaf ezmesi", "3 yemek kaşığı ceviz", "1 çay kaşığı tarçın"], steps: ["Fırını 180°C ısıtın.", "Muzları ezip yulaf, ceviz ve tarçınla karıştırın.", "Karışımdan kaşıkla porsiyonlar alıp tepsiye dizin.", "18-20 dakika kurabiyeler toparlanana kadar pişirip soğutun."], minutes: 30),
  GeneralRecipe(id: "p39a13_001", title: "Fırında havuçlu kabaklı hindi köfte", category: "Tavuk yemekleri", ingredients: ["350 g hindi kıyması", "1 küçük kabak", "1 havuç", "1 yumurta", "3 yemek kaşığı galeta unu"], steps: ["Fırını 190°C ısıtın.", "Kabak ve havucu rendeleyip suyunu sıkın.", "Hindi kıyması, sebzeler, yumurta ve galeta ununu yoğurup küçük köfteler hazırlayın.", "Yağlı kâğıt serili tepside içleri tamamen pişene kadar yaklaşık 25 dakika fırınlayın."], minutes: 40),
  GeneralRecipe(id: "p39a13_002", title: "Közlenmiş domatesli bulgur çorbası", category: "Çorbalar", ingredients: ["3 domates", "Yarım çay bardağı ince bulgur", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Domatesleri fırında 200°C’de 15 dakika közleyin.", "Soğanı doğrayıp yağda yumuşatın.", "Kabukları alınmış domatesleri, bulguru ve suyu ekleyin.", "Bulgur yumuşayana kadar 15 dakika pişirip servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a13_003", title: "Fırında sarımsaklı brokoli patates", category: "Sebze yemekleri", ingredients: ["1 küçük brokoli", "2 patates", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kekik"], steps: ["Fırını 200°C ısıtın.", "Patatesleri ince dilimleyip brokoliyi çiçeklerine ayırın.", "Sebzeleri ezilmiş sarımsak, yağ ve kekikle harmanlayın.", "Patatesler yumuşayana kadar 30 dakika fırınlayın."], minutes: 40),
  GeneralRecipe(id: "p39a13_004", title: "Tavuklu kabaklı pirinç pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pirinç", "200 g tavuk göğsü", "1 küçük kabak", "1,5 su bardağı sıcak su", "1 yemek kaşığı tereyağı"], steps: ["Pirinci yıkayıp 15 dakika ılık suda bekletin.", "Küp doğranmış tavuğu tavada tamamen pişirin.", "Rendelenmiş kabağı ve pirinci ekleyip kısa süre kavurun.", "Sıcak suyu ekleyip kısık ateşte suyunu çektirin ve 10 dakika dinlendirin."], minutes: 45),
  GeneralRecipe(id: "p39a13_005", title: "Yoğurtlu kırmızı lahana mezesi", category: "Mezeler", ingredients: ["Yarım küçük kırmızı lahana", "1 su bardağı yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Lahanayı ince doğrayıp limonla ovun.", "Zeytinyağında 5 dakika yumuşatıp soğutun.", "Yoğurdu ezilmiş sarımsakla karıştırın.", "Soğuyan lahanayı yoğurtla birleştirip servis edin."], minutes: 20),
  GeneralRecipe(id: "p39a13_006", title: "Domatesli nohutlu pazı yemeği", category: "Sebze yemekleri", ingredients: ["1 demet pazı", "1,5 su bardağı haşlanmış nohut", "1 soğan", "1 domates", "2 yemek kaşığı zeytinyağı"], steps: ["Pazıyı bol suyla yıkayıp saplarıyla birlikte doğrayın.", "Soğanı yağda kavurup domatesi ekleyin.", "Pazı ve nohudu tencereye alın.", "Yarım çay bardağı su ekleyip pazı yumuşayana kadar 15 dakika pişirin."], minutes: 35),
  GeneralRecipe(id: "p39a13_007", title: "Fırında limonlu tavuk kanat", category: "Tavuk yemekleri", ingredients: ["600 g tavuk kanat", "1 limonun suyu", "2 yemek kaşığı zeytinyağı", "2 diş sarımsak", "1 çay kaşığı kekik"], steps: ["Fırını 200°C ısıtın.", "Limon, yağ, sarımsak ve kekiği karıştırın.", "Kanatları sosla iyice kaplayıp tepsiye dizin.", "Ara sıra çevirerek içleri tamamen pişene kadar 40-45 dakika fırınlayın."], minutes: 55),
  GeneralRecipe(id: "p39a13_008", title: "Fırında mantarlı peynirli polenta", category: "Dünya mutfağı", ingredients: ["1 su bardağı mısır irmiği", "4 su bardağı su", "250 g mantar", "100 g kaşar peyniri", "1 yemek kaşığı tereyağı"], steps: ["Mısır irmiğini kaynar suya yavaşça döküp sürekli karıştırarak koyulaştırın.", "Mantarları dilimleyip tereyağında suyunu çekene kadar soteleyin.", "Polentayı fırın kabına yayın, mantarları ve rendelenmiş peyniri ekleyin.", "190°C fırında peynir eriyip kızarana kadar 15 dakika pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a13_009", title: "Portakallı pancar salatası", category: "Salatalar", ingredients: ["2 haşlanmış pancar", "1 portakal", "1 avuç roka", "2 yemek kaşığı ceviz", "1 yemek kaşığı zeytinyağı"], steps: ["Pancarları soğutup ince dilimleyin.", "Portakalı soyup zarlarını ayırın.", "Rokayı yıkayıp kurulayın.", "Tüm malzemeleri ceviz ve zeytinyağıyla harmanlayın."], minutes: 20),
  GeneralRecipe(id: "p39a13_010", title: "Ispanaklı lorlu fırın makarna", category: "Makarnalar", ingredients: ["250 g makarna", "200 g ıspanak", "150 g lor peyniri", "1 su bardağı süt", "1 yumurta"], steps: ["Fırını 190°C ısıtın.", "Makarnayı paket süresinden 2 dakika kısa haşlayın.", "Ispanağı yıkayıp doğrayın ve tavada suyunu çektirin.", "Makarna, ıspanak ve loru karıştırıp fırın kabına alın.", "Süt ve yumurtayı çırpıp üzerine dökün; 20 dakika fırınlayın."], minutes: 45),
  GeneralRecipe(id: "p39a13_011", title: "Kabaklı mercimek mücveri", category: "Sebze yemekleri", ingredients: ["1 su bardağı haşlanmış yeşil mercimek", "2 kabak", "1 yumurta", "3 yemek kaşığı un", "Yarım demet dereotu"], steps: ["Kabakları rendeleyip fazla suyunu sıkın.", "Mercimeği çatalla hafifçe ezin.", "Yumurta, un ve doğranmış dereotuyla karıştırın.", "Yağlı kâğıt üzerine küçük parçalar yerleştirip 190°C fırında 25 dakika pişirin."], minutes: 35),
  GeneralRecipe(id: "p39a13_012", title: "Fırında elmalı tarçınlı kek", category: "Kek ve kurabiyeler", ingredients: ["2 elma", "2 yumurta", "1 su bardağı süt", "1,5 su bardağı un", "Yarım su bardağı şeker", "1 paket kabartma tozu", "1 çay kaşığı tarçın"], steps: ["Fırını 175°C ısıtın.", "Yumurta ve şekeri çırpıp sütü ekleyin.", "Un, kabartma tozu ve tarçını karışıma katın.", "Küp doğranmış elmaları ekleyip kalıba dökün.", "Kürdan temiz çıkana kadar yaklaşık 35-40 dakika pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a13_013", title: "Naneli yoğurtlu buğday salatası", category: "Salatalar", ingredients: ["1,5 su bardağı haşlanmış aşurelik buğday", "1 su bardağı yoğurt", "1 salatalık", "Yarım demet taze nane", "1 yemek kaşığı zeytinyağı"], steps: ["Haşlanmış buğdayı tamamen soğutun.", "Salatalığı küçük doğrayıp naneyi kıyın.", "Yoğurdu zeytinyağıyla karıştırın.", "Tüm malzemeleri birleştirip soğuk servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a13_014", title: "Domatesli fırın barbunya köftesi", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı haşlanmış barbunya", "1 küçük soğan", "1 yumurta", "4 yemek kaşığı galeta unu", "2 domates"], steps: ["Fırını 190°C ısıtın.", "Barbunyayı ezip rendelenmiş soğan, yumurta ve galeta unuyla yoğurun.", "Küçük köfteler hazırlayıp tepsiye dizin.", "Rendelenmiş domatesi üzerlerine gezdirip 25 dakika pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a13_015", title: "Limonlu dereotlu karnabahar salatası", category: "Salatalar", ingredients: ["1 küçük karnabahar", "Yarım demet dereotu", "1 limonun suyu", "2 yemek kaşığı zeytinyağı", "1 küçük kırmızı soğan"], steps: ["Karnabaharı çiçeklerine ayırıp buharda hafif diri kalacak şekilde pişirin.", "Tamamen soğumaya bırakın.", "Soğanı ince doğrayıp dereotunu kıyın.", "Limon ve yağla birlikte harmanlayıp servis edin."], minutes: 20),
  GeneralRecipe(id: "p39a13_016", title: "Fırında mantarlı hindi sote", category: "Tavuk yemekleri", ingredients: ["350 g hindi göğsü", "250 g mantar", "1 kapya biber", "1 soğan", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 200°C ısıtın.", "Hindi etini küçük parçalar halinde doğrayın.", "Mantar, biber ve soğanı dilimleyin.", "Tüm malzemeleri yağla harmanlayıp geniş fırın kabına yayın.", "Hindi tamamen pişene kadar 25-30 dakika fırınlayın."], minutes: 40),
  GeneralRecipe(id: "p39a13_017", title: "Fırında muzlu yulaf bar", category: "Diyet ve sağlıklı tarifler", ingredients: ["2 olgun muz", "2 su bardağı yulaf ezmesi", "3 yemek kaşığı fıstık ezmesi", "2 yemek kaşığı kuru üzüm", "1 çay kaşığı tarçın"], steps: ["Fırını 180°C ısıtın.", "Muzları ezip fıstık ezmesiyle karıştırın.", "Yulaf, kuru üzüm ve tarçını ekleyin.", "Karışımı küçük kalıba bastırarak yayın.", "20-25 dakika pişirip tamamen soğuduktan sonra dilimleyin."], minutes: 35),
  GeneralRecipe(id: "p39a13_018", title: "Köz biberli bulgur kısırı", category: "Salatalar", ingredients: ["1 su bardağı ince bulgur", "1 su bardağı sıcak su", "2 közlenmiş kapya biber", "2 dal taze soğan", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Bulguru sıcak suyla ıslatıp üzerini kapatarak 15 dakika bekletin.", "Köz biberleri ve taze soğanı küçük doğrayın.", "Bulguru çatalla havalandırıp sebzeleri ekleyin.", "Zeytinyağı ve limonla harmanlayıp servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a13_019", title: "Patatesli pırasalı omlet", category: "Kahvaltılıklar", ingredients: ["2 yumurta", "1 küçük pırasa", "1 küçük patates", "2 yemek kaşığı süt", "1 yemek kaşığı zeytinyağı"], steps: ["Patatesi küçük küpler halinde doğrayıp tavada yumuşayana kadar pişirin.", "İnce doğranmış pırasayı ekleyip 5 dakika soteleyin.", "Yumurta ve sütü çırpıp tavaya dökün.", "Kısık ateşte her iki yüzünü yumurta tamamen pişene kadar pişirin."], minutes: 30),
  GeneralRecipe(id: "p39a13_020", title: "Tarçınlı armutlu sütlü irmik", category: "Tatlılar", ingredients: ["2 su bardağı süt", "4 yemek kaşığı irmik", "1 armut", "2 yemek kaşığı şeker", "Yarım çay kaşığı tarçın"], steps: ["Süt, irmik ve şekeri tencerede çırparak ısıtın.", "Koyulaşana kadar karıştırarak pişirin.", "Armudu soyup küçük doğrayın ve tarçınla karıştırın.", "İrmik tatlısını kaselere paylaştırıp armutla süsleyin."], minutes: 25),
  GeneralRecipe(id: "p39a14_001", title: "Fırında yoğurtlu kabak dilimleri", category: "Sebze yemekleri", ingredients: ["3 kabak", "4 yemek kaşığı yoğurt", "1 yumurta", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru nane"], steps: ["Fırını 190°C ısıtın ve kabakları halka dilimleyin.", "Yoğurt, yumurta, yağ ve naneyi çırpın.", "Kabakları sosla harmanlayıp tepsiye tek sıra dizin.", "Üzeri kızarana ve kabaklar yumuşayana kadar 20-25 dakika pişirin."], minutes: 30),
  GeneralRecipe(id: "p39a14_002", title: "Kırmızı mercimekli domates çorbası", category: "Çorbalar", ingredients: ["Yarım su bardağı kırmızı mercimek", "3 domates", "1 soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Mercimeği yıkayın; soğanı doğrayıp yağda soteleyin.", "Rendelenmiş domatesleri ekleyip 5 dakika pişirin.", "Mercimek ve suyu katıp 20-25 dakika kaynatın.", "Blenderdan geçirip sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a14_003", title: "Kekikli fırın tavuk but", category: "Kek ve kurabiyeler", ingredients: ["4 tavuk but", "2 patates", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik", "1 diş sarımsak"], steps: ["Fırını 200°C ısıtın.", "Patatesleri iri dilimleyip butlarla tepsiye alın.", "Yağ, kekik ve ezilmiş sarımsakla harmanlayın.", "Tavuk tamamen pişip içi pembe kalmayana kadar 40-45 dakika pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a14_004", title: "Nohutlu pazı kavurması", category: "Sebze yemekleri", ingredients: ["1 demet pazı", "1 su bardağı haşlanmış nohut", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı domates salçası"], steps: ["Pazıyı bol suyla yıkayıp doğrayın.", "Soğanı yağda yumuşatıp salçayı kavurun.", "Nohut ve pazıyı ekleyip karıştırın.", "Kapağı kapalı şekilde pazı yumuşayana kadar 12-15 dakika pişirin."], minutes: 30),
  GeneralRecipe(id: "p39a14_005", title: "Limonlu havuçlu kuskus", category: "Dünya mutfağı", ingredients: ["1 su bardağı kuskus", "1 havuç", "1 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su", "1 yemek kaşığı limon suyu"], steps: ["Havucu rendeleyip yağda 3 dakika soteleyin.", "Kuskusu ekleyip 1 dakika karıştırın.", "Sıcak suyu ekleyip suyunu çekene kadar pişirin.", "Limon suyunu karıştırıp 5 dakika dinlendirin."], minutes: 25),
  GeneralRecipe(id: "p39a14_006", title: "Fırında lorlu patlıcan ruloları", category: "Sebze yemekleri", ingredients: ["2 patlıcan", "150 g lor peyniri", "1 domates", "2 yemek kaşığı zeytinyağı", "2 dal maydanoz"], steps: ["Patlıcanları uzun ince dilimleyip yağlayın.", "200°C fırında yumuşayana kadar 15 dakika pişirin.", "Loru kıyılmış maydanozla karıştırıp dilimlere sarın.", "Üzerlerine rendelenmiş domates koyup 15 dakika daha fırınlayın."], minutes: 45),
  GeneralRecipe(id: "p39a14_007", title: "Tahinli elmalı yulaf kasesi", category: "Kahvaltılıklar", ingredients: ["5 yemek kaşığı yulaf", "1 su bardağı süt", "1 elma", "1 tatlı kaşığı tahin", "Yarım çay kaşığı tarçın"], steps: ["Yulaf ve sütü küçük tencerede 5-6 dakika pişirin.", "Elmayı rendeleyip tarçınla karıştırın.", "Pişmiş yulafı kaseye alın.", "Elma ve tahini üzerine ekleyerek servis edin."], minutes: 15),
  GeneralRecipe(id: "p39a14_008", title: "Köz patlıcanlı tahinli yoğurt mezesi", category: "Mezeler", ingredients: ["2 patlıcan", "1 su bardağı süzme yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı limon suyu"], steps: ["Patlıcanları ocakta veya fırında közleyip soğutun.", "Kabuklarını soyup içlerini ince kıyın.", "Yoğurt, ezilmiş sarımsak ve limonla karıştırın.", "Zeytinyağı gezdirip servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a14_009", title: "Mantarlı ıspanaklı bulgur", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "150 g mantar", "2 avuç ıspanak", "1 soğan", "2 su bardağı sıcak su", "2 yemek kaşığı zeytinyağı"], steps: ["Soğan ve dilimlenmiş mantarı yağda soteleyin.", "Yıkanmış ıspanağı ekleyip söndürün.", "Bulgur ve sıcak suyu ilave edin.", "Kısık ateşte suyunu çekene kadar pişirip dinlendirin."], minutes: 35),
  GeneralRecipe(id: "p39a14_010", title: "Portakallı fırın havuç", category: "Sebze yemekleri", ingredients: ["5 havuç", "1 portakalın suyu", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kimyon", "1 yemek kaşığı susam"], steps: ["Fırını 200°C ısıtın.", "Havuçları uzunlamasına dilimleyip tepsiye yayın.", "Portakal suyu, yağ ve kimyonla harmanlayın.", "25 dakika pişirip susam serperek servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a14_011", title: "Domatesli mercimekli erişte", category: "Makarnalar", ingredients: ["1 su bardağı erişte", "Yarım su bardağı haşlanmış yeşil mercimek", "2 domates", "1 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Rendelenmiş domatesleri yağda 5 dakika pişirin.", "Erişte ve mercimeği ekleyip karıştırın.", "Sıcak suyu ilave edip erişte yumuşayana kadar pişirin.", "5 dakika dinlendirip servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a14_012", title: "Fırında limonlu çipura ve rezene", category: "Balık ve deniz ürünleri", ingredients: ["2 temizlenmiş çipura", "1 rezene kökü", "1 limon", "2 yemek kaşığı zeytinyağı", "2 dal dereotu"], steps: ["Fırını 190°C ısıtın.", "Rezeneyi ince dilimleyip tepsiye yayın.", "Balıkları üzerine yerleştirip limon ve yağ ekleyin.", "Balık eti tamamen pişip kolay ayrılana kadar 25-30 dakika fırınlayın."], minutes: 40),
  GeneralRecipe(id: "p39a14_013", title: "Cevizli pancarlı kinoa", category: "Diyet ve sağlıklı tarifler", ingredients: ["Yarım su bardağı kinoa", "1 haşlanmış pancar", "2 yemek kaşığı ceviz", "1 yemek kaşığı limon suyu", "1 yemek kaşığı zeytinyağı"], steps: ["Kinoayı yıkayıp bir su bardağı suda 15 dakika pişirin.", "Kinoayı soğutup pancarı küçük küpler halinde doğrayın.", "Cevizi iri kırın.", "Tüm malzemeleri limon ve yağla karıştırın."], minutes: 35),
  GeneralRecipe(id: "p39a14_014", title: "Peynirli kabaklı mini pankek", category: "Kek ve kurabiyeler", ingredients: ["1 küçük kabak", "1 yumurta", "3 yemek kaşığı un", "3 yemek kaşığı beyaz peynir", "1 tatlı kaşığı zeytinyağı"], steps: ["Kabağı rendeleyip suyunu sıkın.", "Yumurta, un ve ufalanmış peynirle karıştırın.", "Yapışmaz tavayı hafifçe yağlayın.", "Küçük porsiyonları iki yüzü de tamamen pişene kadar çevirin."], minutes: 25),
  GeneralRecipe(id: "p39a14_015", title: "Fırında tarçınlı elmalı irmik kup", category: "Tatlılar", ingredients: ["2 elma", "3 yemek kaşığı irmik", "2 su bardağı süt", "2 yemek kaşığı şeker", "Yarım çay kaşığı tarçın"], steps: ["Süt, irmik ve şekeri karıştırarak koyulaştırın.", "Elmaları rendeleyip tarçınla harmanlayın.", "Kaselere irmik ve elmayı kat kat yerleştirin.", "180°C fırında 10 dakika ısıtıp ılık servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a14_016", title: "Yoğurtlu naneli buğday çorbası", category: "Çorbalar", ingredients: ["Yarım su bardağı aşurelik buğday", "1 su bardağı yoğurt", "1 yumurta sarısı", "1 yemek kaşığı un", "4 su bardağı su", "1 tatlı kaşığı kuru nane"], steps: ["Önceden ıslatılmış buğdayı yumuşayana kadar haşlayın.", "Yoğurt, yumurta sarısı ve unu çırpın.", "Sıcak sudan ekleyerek terbiyeyi ılıştırıp tencereye karıştırarak katın.", "Kısık ateşte 5 dakika pişirip nane ekleyin."], minutes: 40),
  GeneralRecipe(id: "p39a14_017", title: "Kıymalı fırın karnabahar", category: "Et yemekleri", ingredients: ["1 küçük karnabahar", "250 g kıyma", "1 soğan", "2 domates", "2 yemek kaşığı zeytinyağı"], steps: ["Karnabaharı çiçeklerine ayırıp 8 dakika buharda pişirin.", "Soğan ve kıymayı tavada kıyma tamamen pişene kadar kavurun.", "Domatesi ekleyip 5 dakika kaynatın.", "Karnabahar ve kıymalı sosu fırın kabında birleştirip 190°C fırında 20 dakika pişirin."], minutes: 50),
  GeneralRecipe(id: "p39a14_018", title: "Biberli nohutlu makarna salatası", category: "Salatalar", ingredients: ["1 su bardağı kısa makarna", "1 su bardağı haşlanmış nohut", "1 kapya biber", "Yarım demet maydanoz", "2 yemek kaşığı limon suyu", "1 yemek kaşığı zeytinyağı"], steps: ["Makarnayı paket talimatına göre haşlayıp soğutun.", "Kapya biberi ve maydanozu ince doğrayın.", "Makarna ve nohudu sebzelerle birleştirin.", "Limon ve yağla harmanlayın."], minutes: 25),
  GeneralRecipe(id: "p39a14_019", title: "Fırında tarçınlı muzlu ekmek", category: "Kek ve kurabiyeler", ingredients: ["2 olgun muz", "2 yumurta", "1,5 su bardağı un", "Yarım su bardağı süt", "1 paket kabartma tozu", "1 çay kaşığı tarçın"], steps: ["Fırını 175°C ısıtın.", "Muzları ezip yumurta ve sütle çırpın.", "Un, kabartma tozu ve tarçını ekleyip karıştırın.", "Yağlanmış kalıba döküp ortası tamamen pişene kadar 35-40 dakika fırınlayın."], minutes: 55),
  GeneralRecipe(id: "p39a14_020", title: "Tavuklu sebzeli karabuğday", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı karabuğday", "250 g tavuk göğsü", "1 havuç", "1 küçük kabak", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Tavuğu küçük doğrayıp yağda tamamen pişene kadar soteleyin.", "Küp doğranmış havuç ve kabağı ekleyip 5 dakika pişirin.", "Yıkanmış karabuğdayı ve sıcak suyu ilave edin.", "Kapağı kapalı şekilde suyunu çekene kadar 15-20 dakika pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a15_001", title: "Fırında sebzeli hindi rosto", category: "Tavuk yemekleri", ingredients: ["500 g hindi göğüs", "2 havuç", "1 kabak", "1 soğan", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik"], steps: ["Fırını 190°C ısıtın; hindi etini iri parçalara bölün.", "Sebzeleri doğrayıp hindiyle birlikte yağ ve kekikle harmanlayın.", "Fırın kabına yayıp üzerini yağlı kâğıtla örtün.", "35 dakika pişirin; kâğıdı açıp et tamamen pişene kadar 10-15 dakika daha fırınlayın."], minutes: 60),
  GeneralRecipe(id: "p39a15_002", title: "Kremasız pırasa patates çorbası", category: "Çorbalar", ingredients: ["2 pırasa", "2 patates", "1 soğan", "1 yemek kaşığı zeytinyağı", "5 su bardağı sebze suyu"], steps: ["Pırasayı iyice yıkayıp ince doğrayın.", "Soğan ve pırasayı yağda 5 dakika yumuşatın.", "Küp patates ve sebze suyunu ekleyip 20 dakika kaynatın.", "Blenderdan geçirip sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a15_003", title: "Fırında domates soslu kabak kayıkları", category: "Sebze yemekleri", ingredients: ["3 kabak", "2 domates", "1 soğan", "1 su bardağı haşlanmış yeşil mercimek", "2 yemek kaşığı zeytinyağı", "3 yemek kaşığı rendelenmiş kaşar"], steps: ["Kabakları boyuna ikiye bölüp içlerini kaşıkla oyun.", "Soğanı yağda soteleyip doğranmış domates ve mercimeği ekleyin.", "İç harcı kabaklara paylaştırıp üzerlerine kaşar serpin.", "190°C fırında kabaklar yumuşayana kadar 25-30 dakika pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a15_004", title: "Nohutlu köz biberli kinoa pilavı", category: "Diyet ve sağlıklı tarifler", ingredients: ["1 su bardağı kinoa", "1 su bardağı haşlanmış nohut", "2 közlenmiş kapya biber", "2 su bardağı su", "1 yemek kaşığı zeytinyağı", "Yarım limonun suyu"], steps: ["Kinoayı bol suyla yıkayıp süzün.", "Kinoayı suyla 15 dakika pişirip 5 dakika dinlendirin.", "Köz biberleri doğrayıp nohutla birlikte kinoaya ekleyin.", "Zeytinyağı ve limon suyuyla karıştırarak servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a15_005", title: "Dereotlu fırın mezgit", category: "Balık ve deniz ürünleri", ingredients: ["500 g mezgit fileto", "1 limon", "2 yemek kaşığı zeytinyağı", "Yarım demet dereotu", "1 diş sarımsak"], steps: ["Fırını 190°C ısıtın ve balıkları fırın kabına dizin.", "Limon suyu, yağ ve ezilmiş sarımsağı karıştırın.", "Sosu balıkların üzerine döküp dereotunu serpin.", "Balık eti opaklaşıp kolay ayrılana kadar 18-22 dakika pişirin."], minutes: 30),
  GeneralRecipe(id: "p39a15_006", title: "Fırında mantarlı ıspanaklı yumurta", category: "Kahvaltılıklar", ingredients: ["3 yumurta", "150 g mantar", "2 avuç ıspanak", "2 yemek kaşığı süt", "1 tatlı kaşığı zeytinyağı"], steps: ["Mantarları dilimleyip tavada suyunu çekene kadar soteleyin.", "Ispanağı ekleyip yumuşatın ve küçük fırın kabına alın.", "Yumurta ve sütü çırpıp sebzelerin üzerine dökün.", "180°C fırında yumurta tamamen pişene kadar 15-20 dakika pişirin."], minutes: 30),
  GeneralRecipe(id: "p39a15_007", title: "Köz havuçlu mercimek salatası", category: "Salatalar", ingredients: ["1 su bardağı haşlanmış yeşil mercimek", "3 havuç", "1 avuç roka", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu", "1 tatlı kaşığı kimyon"], steps: ["Havuçları çubuk doğrayıp yağ ve kimyonla harmanlayın.", "200°C fırında 20 dakika yumuşayana kadar pişirin.", "Mercimek ve yıkanmış rokayı servis kabına alın.", "Ilık havuçları ekleyip limon suyuyla karıştırın."], minutes: 35),
  GeneralRecipe(id: "p39a15_008", title: "Yoğurtlu dereotlu patates salatası", category: "Salatalar", ingredients: ["3 orta boy patates", "4 yemek kaşığı yoğurt", "Yarım demet dereotu", "1 tatlı kaşığı hardal", "1 yemek kaşığı limon suyu"], steps: ["Patatesleri kabuklarıyla haşlayıp soğutun.", "Kabuklarını soyup iri küpler halinde doğrayın.", "Yoğurt, hardal, limon ve ince kıyılmış dereotunu karıştırın.", "Patatesleri sosla harmanlayıp serin servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a15_009", title: "Fırında kıymalı mantar dolması", category: "Et yemekleri", ingredients: ["10 büyük kültür mantarı", "200 g kıyma", "1 küçük soğan", "1 domates", "1 yemek kaşığı zeytinyağı", "2 yemek kaşığı kaşar"], steps: ["Mantarların saplarını çıkarıp temizleyin.", "Soğanı ve kıymayı tavada tamamen pişene kadar kavurun.", "Doğranmış domatesi ekleyip 5 dakika pişirin ve mantarları doldurun.", "Kaşar serpip 190°C fırında mantarlar yumuşayana kadar 20 dakika pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a15_010", title: "Portakallı zeytinyağlı pancar", category: "Sebze yemekleri", ingredients: ["3 küçük pancar", "1 portakalın suyu", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım su bardağı su"], steps: ["Pancarları soyup ince yarım ay dilimleyin.", "Soğanı yağda 3 dakika yumuşatın.", "Pancar, portakal suyu ve suyu ekleyin.", "Kapağı kapalı şekilde pancarlar yumuşayana kadar 30-35 dakika pişirin."], minutes: 45),
  GeneralRecipe(id: "p39a15_011", title: "Tavuklu limonlu arpa şehriye", category: "Makarnalar", ingredients: ["1 su bardağı arpa şehriye", "250 g tavuk göğsü", "1 havuç", "2 su bardağı sıcak su", "1 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Tavuğu küçük küpler halinde doğrayıp yağda tamamen pişirin.", "Rendelenmiş havuç ve arpa şehriyeyi ekleyip 3 dakika kavurun.", "Sıcak suyu ekleyip kapağı kapalı şekilde suyunu çekene kadar pişirin.", "Limon suyunu ekleyip 5 dakika dinlendirin."], minutes: 35),
  GeneralRecipe(id: "p39a15_012", title: "Fırında peynirli karnabahar dilimleri", category: "Sebze yemekleri", ingredients: ["1 büyük karnabahar", "3 yemek kaşığı yoğurt", "1 yumurta", "4 yemek kaşığı rendelenmiş kaşar", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 200°C ısıtın ve karnabaharı kalın dilimler halinde kesin.", "Yoğurt, yumurta ve yağı çırpın.", "Karnabahar dilimlerine sosu sürüp kaşar serpin.", "Sebze yumuşayıp üzeri kızarana kadar 25-30 dakika pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a15_013", title: "Bulgurlu mantarlı sebze çorbası", category: "Çorbalar", ingredients: ["Yarım su bardağı ince bulgur", "150 g mantar", "1 havuç", "1 küçük soğan", "5 su bardağı su", "1 yemek kaşığı zeytinyağı"], steps: ["Soğanı, havucu ve mantarları küçük doğrayın.", "Soğan ve mantarı yağda 5 dakika soteleyin.", "Havuç, bulgur ve suyu ekleyip karıştırın.", "Bulgur ve sebzeler yumuşayana kadar 20 dakika kaynatın."], minutes: 35),
  GeneralRecipe(id: "p39a15_014", title: "Elmalı cevizli yoğurt tatlısı", category: "Tatlılar", ingredients: ["2 elma", "1 su bardağı yoğurt", "2 yemek kaşığı ceviz", "1 tatlı kaşığı bal", "Yarım çay kaşığı tarçın"], steps: ["Elmaları soyup küp doğrayın.", "Az suyla tavada 5-6 dakika yumuşatıp tarçın ekleyin.", "Yoğurdu kaselere paylaştırıp ılık elmaları üzerine koyun.", "Ceviz ve balı ekleyip servis edin."], minutes: 15),
  GeneralRecipe(id: "p39a15_015", title: "Tahinli kakolu yulaf topları", category: "Tatlılar", ingredients: ["1 su bardağı yulaf ezmesi", "2 yemek kaşığı tahin", "2 yemek kaşığı kakao", "1 olgun muz", "2 yemek kaşığı Hindistan cevizi"], steps: ["Muzu çatalla iyice ezin.", "Yulaf, tahin ve kakaoyu ekleyip yoğurun.", "Karışımdan küçük toplar yuvarlayın.", "Hindistan cevizine bulayıp buzdolabında 20 dakika dinlendirin."], minutes: 30),
  GeneralRecipe(id: "p39a15_016", title: "Fırında ıspanaklı nohut köftesi", category: "Sebze yemekleri", ingredients: ["1,5 su bardağı haşlanmış nohut", "2 avuç ıspanak", "1 yumurta", "3 yemek kaşığı yulaf unu", "1 yemek kaşığı zeytinyağı"], steps: ["Nohudu çatalla ezin ve ıspanağı ince kıyın.", "Yumurta ve yulaf unuyla yoğurup küçük köfteler şekillendirin.", "Yağlı kâğıt serili tepsiye dizip üzerlerine yağ sürün.", "190°C fırında iki tarafı kızarana kadar 20-25 dakika pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a15_017", title: "Domatesli fasulyeli kuskus salatası", category: "Dünya mutfağı", ingredients: ["1 su bardağı haşlanmış kuskus", "1 su bardağı haşlanmış kuru fasulye", "2 domates", "1 salatalık", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu"], steps: ["Kuskusu haşlayıp süzün ve soğutun.", "Domates ve salatalığı küçük küpler halinde doğrayın.", "Kuskus ve fasulyeyi sebzelerle karıştırın.", "Zeytinyağı ve limonla harmanlayarak servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a15_018", title: "Fırında patatesli pırasa böreği", category: "Hamur işleri", ingredients: ["3 yufka", "2 pırasa", "2 patates", "1 yumurta", "Yarım su bardağı süt", "3 yemek kaşığı zeytinyağı"], steps: ["Pırasayı doğrayıp yağda yumuşatın; haşlanmış patatesi ezin.", "Pırasa ve patatesi karıştırarak iç harcı hazırlayın.", "Yufkaları süt ve yumurta karışımıyla ıslatıp iç harcı sarın.", "180°C fırında üzeri kızarana kadar 30-35 dakika pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a15_019", title: "Kabaklı dereotlu mercimek mücveri", category: "Sebze yemekleri", ingredients: ["2 kabak", "1 su bardağı haşlanmış kırmızı mercimek", "1 yumurta", "3 yemek kaşığı un", "Yarım demet dereotu", "1 yemek kaşığı zeytinyağı"], steps: ["Kabakları rendeleyip suyunu iyice sıkın.", "Mercimeği ezip kabak, yumurta, un ve dereotuyla karıştırın.", "Karışımdan kaşıkla porsiyonlar alıp yağlı tepsiye dizin.", "190°C fırında iki tarafı kızarana kadar 25 dakika pişirin."], minutes: 40),
  GeneralRecipe(id: "p39a15_020", title: "Fırında armutlu yulaf kup", category: "Tatlılar", ingredients: ["2 armut", "Yarım su bardağı yulaf ezmesi", "Yarım su bardağı süt", "1 yemek kaşığı ceviz", "1 tatlı kaşığı bal", "Yarım çay kaşığı tarçın"], steps: ["Armutları küçük doğrayıp fırın kaplarına paylaştırın.", "Yulaf, süt, tarçın ve cevizi karıştırın.", "Karışımı armutların üzerine ekleyin.", "180°C fırında 20-25 dakika pişirip ılıkken bal gezdirin."], minutes: 35),
  GeneralRecipe(id: "p39a16_001", title: "Kabak ve beyaz fasulye çorbası", category: "Çorbalar", ingredients: ["2 kabak", "1 su bardağı haşlanmış beyaz fasulye", "1 küçük kuru soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su", "İsteğe göre az tuz"], steps: ["Sebzeleri yıkayıp küçük parçalara doğrayın; kuru bakliyat kullanıyorsanız önceden haşlayın.", "Soğanı zeytinyağında 3 dakika yumuşatın; ana malzemeleri ekleyip karıştırın.", "Suyu ekleyip malzemeler tamamen yumuşayana kadar 20-30 dakika pişirin.", "İsteğe göre pürüzsüz kıvam için blenderdan geçirin; kıvamı sıcak suyla ayarlayıp servis edin."], minutes: 40, detailed: false),
