  GeneralRecipe(id: "p39a16_034", title: "Kuskus ve mısır salatası", category: "Dünya mutfağı", ingredients: ["1 su bardağı pişmiş kuskus", "yarım su bardağı haşlanmış mısır", "Yarım demet maydanoz", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu", "İsteğe göre az tuz"], steps: ["Çiğ tüketilecek sebze ve meyveleri iyice yıkayıp kurulayın.", "Pişmesi gereken tahıl veya bakliyatı önceden tamamen pişirip soğutun.", "Ana malzemeleri servislik boyutta doğrayın; maydanozla birleştirin.", "Zeytinyağı ve limon suyunu ayrı kapta çırpıp salataya ekleyin; hemen servis edin."], minutes: 25, detailed: false),
  GeneralRecipe(id: "p39a16_035", title: "Mor lahana ve elma salatası", category: "Salatalar", ingredients: ["yarım mor lahana", "1 yeşil elma", "Yarım demet maydanoz", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu", "İsteğe göre az tuz"], steps: ["Çiğ tüketilecek sebze ve meyveleri iyice yıkayıp kurulayın.", "Pişmesi gereken tahıl veya bakliyatı önceden tamamen pişirip soğutun.", "Ana malzemeleri servislik boyutta doğrayın; maydanozla birleştirin.", "Zeytinyağı ve limon suyunu ayrı kapta çırpıp salataya ekleyin; hemen servis edin."], minutes: 25, detailed: false),
  GeneralRecipe(id: "p39a16_036", title: "Brokoli ve ceviz salatası", category: "Salatalar", ingredients: ["300 g brokoli", "3 yemek kaşığı ceviz", "Yarım demet maydanoz", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu", "İsteğe göre az tuz"], steps: ["Çiğ tüketilecek sebze ve meyveleri iyice yıkayıp kurulayın.", "Pişmesi gereken tahıl veya bakliyatı önceden tamamen pişirip soğutun.", "Ana malzemeleri servislik boyutta doğrayın; maydanozla birleştirin.", "Zeytinyağı ve limon suyunu ayrı kapta çırpıp salataya ekleyin; hemen servis edin."], minutes: 25, detailed: false),
  GeneralRecipe(id: "p39a16_037", title: "Kabak ve lor omleti", category: "Kahvaltılıklar", ingredients: ["150 g kabak", "60 g lor", "3 yumurta", "2 yemek kaşığı süt", "1 tatlı kaşığı zeytinyağı"], steps: ["Kabağı rendeleyip fazla suyunu sıkın; zeytinyağında 3 dakika soteleyin.", "Yumurtaları sütle çırpın; hazırlanan sebzeyi ve diğer malzemeyi ekleyin.", "Karışımı hafif yağlanmış yapışmaz tavaya dökün; kapağı kapalı kısık ateşte pişirin.", "Altı tutunca dikkatlice çevirin; yumurtanın içi tamamen katılaşana kadar pişirip servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a16_038", title: "Mantar ve kaşar omleti", category: "Kahvaltılıklar", ingredients: ["150 g mantar", "60 g kaşar", "3 yumurta", "2 yemek kaşığı süt", "1 tatlı kaşığı zeytinyağı"], steps: ["Mantarları ince dilimleyip yağda suyunu çekene kadar soteleyin.", "Yumurtaları sütle çırpın; hazırlanan sebzeyi ve diğer malzemeyi ekleyin.", "Karışımı hafif yağlanmış yapışmaz tavaya dökün; kapağı kapalı kısık ateşte pişirin.", "Altı tutunca dikkatlice çevirin; yumurtanın içi tamamen katılaşana kadar pişirip servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a16_039", title: "Ispanak ve domates omleti", category: "Kahvaltılıklar", ingredients: ["150 g ıspanak", "60 g domates", "3 yumurta", "2 yemek kaşığı süt", "1 tatlı kaşığı zeytinyağı"], steps: ["Ispanağı yıkayıp doğrayın; domatesin çekirdeklerini ayırıp küp doğrayın.", "Yumurtaları sütle çırpın; hazırlanan sebzeyi ve diğer malzemeyi ekleyin.", "Karışımı hafif yağlanmış yapışmaz tavaya dökün; kapağı kapalı kısık ateşte pişirin.", "Altı tutunca dikkatlice çevirin; yumurtanın içi tamamen katılaşana kadar pişirip servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a16_040", title: "Pırasa ve beyaz peynir omleti", category: "Kahvaltılıklar", ingredients: ["150 g pırasa", "60 g beyaz peynir", "3 yumurta", "2 yemek kaşığı süt", "1 tatlı kaşığı zeytinyağı"], steps: ["Pırasayı ince kıyıp yağda yumuşayana kadar 6 dakika pişirin.", "Yumurtaları sütle çırpın; hazırlanan sebzeyi ve diğer malzemeyi ekleyin.", "Karışımı hafif yağlanmış yapışmaz tavaya dökün; kapağı kapalı kısık ateşte pişirin.", "Altı tutunca dikkatlice çevirin; yumurtanın içi tamamen katılaşana kadar pişirip servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a16_041", title: "Brokoli ve dereotu omleti", category: "Kahvaltılıklar", ingredients: ["150 g brokoli", "60 g dereotu", "3 yumurta", "2 yemek kaşığı süt", "1 tatlı kaşığı zeytinyağı"], steps: ["Brokoliyi küçük çiçeklere ayırıp 5 dakika buharda yumuşatın; dereotunu kıyın.", "Yumurtaları sütle çırpın; hazırlanan sebzeyi ve diğer malzemeyi ekleyin.", "Karışımı hafif yağlanmış yapışmaz tavaya dökün; kapağı kapalı kısık ateşte pişirin.", "Altı tutunca dikkatlice çevirin; yumurtanın içi tamamen katılaşana kadar pişirip servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a16_042", title: "Köz biber ve lor omleti", category: "Kahvaltılıklar", ingredients: ["150 g közlenmiş kırmızı biber", "60 g lor", "3 yumurta", "2 yemek kaşığı süt", "1 tatlı kaşığı zeytinyağı"], steps: ["Közlenmiş biberi süzüp ince şeritlere kesin.", "Yumurtaları sütle çırpın; hazırlanan sebzeyi ve diğer malzemeyi ekleyin.", "Karışımı hafif yağlanmış yapışmaz tavaya dökün; kapağı kapalı kısık ateşte pişirin.", "Altı tutunca dikkatlice çevirin; yumurtanın içi tamamen katılaşana kadar pişirip servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a16_043", title: "Patates ve maydanoz omleti", category: "Kahvaltılıklar", ingredients: ["150 g patates", "60 g maydanoz", "3 yumurta", "2 yemek kaşığı süt", "1 tatlı kaşığı zeytinyağı"], steps: ["Patatesi küçük küpler halinde doğrayıp az suda 8 dakika ön haşlayın; maydanozu kıyın.", "Yumurtaları sütle çırpın; hazırlanan sebzeyi ve diğer malzemeyi ekleyin.", "Karışımı hafif yağlanmış yapışmaz tavaya dökün; kapağı kapalı kısık ateşte pişirin.", "Altı tutunca dikkatlice çevirin; yumurtanın içi tamamen katılaşana kadar pişirip servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a16_044", title: "Bezelye ve nane omleti", category: "Kahvaltılıklar", ingredients: ["150 g haşlanmış bezelye", "60 g taze nane", "3 yumurta", "2 yemek kaşığı süt", "1 tatlı kaşığı zeytinyağı"], steps: ["Bezelyeyi önceden haşlayıp süzün; naneyi ince kıyın.", "Yumurtaları sütle çırpın; hazırlanan sebzeyi ve diğer malzemeyi ekleyin.", "Karışımı hafif yağlanmış yapışmaz tavaya dökün; kapağı kapalı kısık ateşte pişirin.", "Altı tutunca dikkatlice çevirin; yumurtanın içi tamamen katılaşana kadar pişirip servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a16_045", title: "Karnabahar ve kaşar omleti", category: "Kahvaltılıklar", ingredients: ["150 g karnabahar", "60 g kaşar", "3 yumurta", "2 yemek kaşığı süt", "1 tatlı kaşığı zeytinyağı"], steps: ["Karnabaharı küçük çiçeklere ayırıp 6 dakika buharda ön pişirin.", "Yumurtaları sütle çırpın; hazırlanan sebzeyi ve diğer malzemeyi ekleyin.", "Karışımı hafif yağlanmış yapışmaz tavaya dökün; kapağı kapalı kısık ateşte pişirin.", "Altı tutunca dikkatlice çevirin; yumurtanın içi tamamen katılaşana kadar pişirip servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a16_046", title: "Domates ve fesleğen omleti", category: "Kahvaltılıklar", ingredients: ["150 g domates", "60 g fesleğen", "3 yumurta", "2 yemek kaşığı süt", "1 tatlı kaşığı zeytinyağı"], steps: ["Domatesin çekirdekli suyunu ayırıp küp doğrayın; fesleğeni ince kıyın.", "Yumurtaları sütle çırpın; hazırlanan sebzeyi ve diğer malzemeyi ekleyin.", "Karışımı hafif yağlanmış yapışmaz tavaya dökün; kapağı kapalı kısık ateşte pişirin.", "Altı tutunca dikkatlice çevirin; yumurtanın içi tamamen katılaşana kadar pişirip servis edin."], minutes: 25),
  GeneralRecipe(id: "p39a16_047", title: "Kabak ve dereotu omleti", category: "Kahvaltılıklar", ingredients: ["1 küçük kabak", "yarım demet dereotu", "3 yumurta", "2 yemek kaşığı süt", "1 tatlı kaşığı zeytinyağı"], steps: ["Sebzeleri yıkayıp küçük doğrayın; sert olanları tavada önceden yumuşatın.", "Yumurtaları sütle çırpıp hazırlanan malzemeleri ekleyin.", "Yağlanmış yapışmaz tavaya döküp kısık ateşte kapağı kapalı pişirin.", "Omleti çevirerek her iki yüzünü ve içini tamamen pişirin; sıcak servis edin."], minutes: 20),
  GeneralRecipe(id: "p39a16_048", title: "Mantar ve ıspanak omleti", category: "Kahvaltılıklar", ingredients: ["100 g mantar", "1 avuç ıspanak", "3 yumurta", "2 yemek kaşığı süt", "1 tatlı kaşığı zeytinyağı"], steps: ["Sebzeleri yıkayıp küçük doğrayın; sert olanları tavada önceden yumuşatın.", "Yumurtaları sütle çırpıp hazırlanan malzemeleri ekleyin.", "Yağlanmış yapışmaz tavaya döküp kısık ateşte kapağı kapalı pişirin.", "Omleti çevirerek her iki yüzünü ve içini tamamen pişirin; sıcak servis edin."], minutes: 20),
  GeneralRecipe(id: "p39a16_049", title: "Mantarlı karabuğday pilavı", category: "Pilavlar", ingredients: ["1 su bardağı karabuğday", "200 g mantar", "1 küçük kuru soğan", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Tahılı yıkayıp süzün; sebzeleri temizleyip küçük doğrayın.", "Soğanı yağda yumuşatın, pişmesi gereken ek malzemeyi ekleyip kısa süre soteleyin.", "Tahılı ve sıcak suyu ekleyin; tahılın türüne göre su miktarını gerektiğinde artırın.", "Kısık ateşte taneler yumuşayana kadar pişirip 10 dakika dinlendirin; karıştırarak servis edin."], minutes: 40, detailed: false),
