  GeneralRecipe(id: "p39a16_081", title: "Havuçlu limonlu fırın balık", category: "Balık ve deniz ürünleri", ingredients: ["2 levrek fileto", "2 havuç", "2 yemek kaşığı zeytinyağı", "1 limon", "1 diş sarımsak", "1 çay kaşığı kekik"], steps: ["Fırını 190°C ısıtın; balığın kılçıklarını kontrol edip sebzeleri temizleyin.", "İkinci ana malzemeyi ince doğrayıp fırın kabına yayın; gerekiyorsa 10 dakika ön pişirin.", "Balığı sebzelerin üzerine koyup zeytinyağı, limon suyu, sarımsak ve kekik ekleyin.", "Balığın kalınlığına göre yaklaşık 15-25 dakika, içi opaklaşıp kolay ayrılana ve 63°C iç sıcaklığa ulaşana kadar pişirin."], minutes: 40, detailed: false),
  GeneralRecipe(id: "p39a16_082", title: "Mantar ve kekikli fırın balık", category: "Kek ve kurabiyeler", ingredients: ["2 somon fileto", "150 g mantar", "2 yemek kaşığı zeytinyağı", "1 limon", "1 diş sarımsak", "1 çay kaşığı kekik"], steps: ["Fırını 190°C ısıtın; balığın kılçıklarını kontrol edip sebzeleri temizleyin.", "İkinci ana malzemeyi ince doğrayıp fırın kabına yayın; gerekiyorsa 10 dakika ön pişirin.", "Balığı sebzelerin üzerine koyup zeytinyağı, limon suyu, sarımsak ve kekik ekleyin.", "Balığın kalınlığına göre yaklaşık 15-25 dakika, içi opaklaşıp kolay ayrılana ve 63°C iç sıcaklığa ulaşana kadar pişirin."], minutes: 40, detailed: false),
  GeneralRecipe(id: "p39a16_083", title: "Domatesli zeytinli fırın balık", category: "Balık ve deniz ürünleri", ingredients: ["2 mezgit fileto", "2 domates", "2 yemek kaşığı zeytinyağı", "1 limon", "1 diş sarımsak", "1 çay kaşığı kekik"], steps: ["Fırını 190°C ısıtın; balığın kılçıklarını kontrol edip sebzeleri temizleyin.", "İkinci ana malzemeyi ince doğrayıp fırın kabına yayın; gerekiyorsa 10 dakika ön pişirin.", "Balığı sebzelerin üzerine koyup zeytinyağı, limon suyu, sarımsak ve kekik ekleyin.", "Balığın kalınlığına göre yaklaşık 15-25 dakika, içi opaklaşıp kolay ayrılana ve 63°C iç sıcaklığa ulaşana kadar pişirin."], minutes: 40, detailed: false),
  GeneralRecipe(id: "p39a16_084", title: "Ispanaklı fırın balık", category: "Balık ve deniz ürünleri", ingredients: ["2 çipura fileto", "200 g ıspanak", "2 yemek kaşığı zeytinyağı", "1 limon", "1 diş sarımsak", "1 çay kaşığı kekik"], steps: ["Fırını 190°C ısıtın; balığın kılçıklarını kontrol edip sebzeleri temizleyin.", "İkinci ana malzemeyi ince doğrayıp fırın kabına yayın; gerekiyorsa 10 dakika ön pişirin.", "Balığı sebzelerin üzerine koyup zeytinyağı, limon suyu, sarımsak ve kekik ekleyin.", "Balığın kalınlığına göre yaklaşık 15-25 dakika, içi opaklaşıp kolay ayrılana ve 63°C iç sıcaklığa ulaşana kadar pişirin."], minutes: 40, detailed: false),
  GeneralRecipe(id: "p39a16_085", title: "Elmalı yulaflı fırın tatlısı", category: "Tatlılar", ingredients: ["2 elma", "yarım su bardağı yulaf", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın. Elmaları kabuklarıyla rendeleyip yulafla karıştırın.", "Süt, yulaf unu ve tarçını ayrı kapta çırpın; meyveli karışıma ekleyin.", "Karışımı küçük fırın kaplarına eşit dağıtın; üzerini kaşıkla düzeltin.", "Orta rafta yaklaşık 25-30 dakika, karışım kıvam alana kadar pişirin; ılıtarak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a16_086", title: "Armutlu cevizli fırın tatlısı", category: "Tatlılar", ingredients: ["2 armut", "3 yemek kaşığı iri kıyılmış ceviz", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın. Armutları soyup küp doğrayın; cevizleri iri kıyın.", "Süt, yulaf unu ve tarçını ayrı kapta çırpın; meyveli karışıma ekleyin.", "Karışımı küçük fırın kaplarına eşit dağıtın; üzerini kaşıkla düzeltin.", "Orta rafta yaklaşık 25-30 dakika, karışım kıvam alana kadar pişirin; ılıtarak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a16_087", title: "Muzlu kakaolu fırın tatlısı", category: "Tatlılar", ingredients: ["2 olgun muz", "1 yemek kaşığı kakao", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın. Muzları çatalla ezip kakaoyu pürüzsüzce karıştırın.", "Süt, yulaf unu ve tarçını ayrı kapta çırpın; meyveli karışıma ekleyin.", "Karışımı küçük fırın kaplarına eşit dağıtın; üzerini kaşıkla düzeltin.", "Orta rafta yaklaşık 25-30 dakika, karışım kıvam alana kadar pişirin; ılıtarak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a16_088", title: "Şeftalili bademli fırın tatlısı", category: "Tatlılar", ingredients: ["2 şeftali", "3 yemek kaşığı file badem", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın. Şeftalileri dilimleyin; bademleri üzerine serpmek için ayırın.", "Süt, yulaf unu ve tarçını ayrı kapta çırpın; meyveli karışıma ekleyin.", "Karışımı küçük fırın kaplarına eşit dağıtın; üzerini kaşıkla düzeltin.", "Orta rafta yaklaşık 25-30 dakika, karışım kıvam alana kadar pişirin; ılıtarak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a16_089", title: "Ayvalı tarçınlı fırın tatlısı", category: "Tatlılar", ingredients: ["2 ayva", "Yarım çay kaşığı tarçın", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın. Ayvaları soyup ince dilimleyin; 10 dakika az suda ön pişirin.", "Süt, yulaf unu ve tarçını ayrı kapta çırpın; meyveli karışıma ekleyin.", "Karışımı küçük fırın kaplarına eşit dağıtın; üzerini kaşıkla düzeltin.", "Orta rafta yaklaşık 25-30 dakika, karışım kıvam alana kadar pişirin; ılıtarak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a16_090", title: "Balkabaklı cevizli fırın tatlısı", category: "Tatlılar", ingredients: ["300 g balkabağı", "3 yemek kaşığı iri kıyılmış ceviz", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın. Balkabağını küçük küplere doğrayıp 12 dakika buharda yumuşatın.", "Süt, yulaf unu ve tarçını ayrı kapta çırpın; meyveli karışıma ekleyin.", "Karışımı küçük fırın kaplarına eşit dağıtın; üzerini kaşıkla düzeltin.", "Orta rafta yaklaşık 25-30 dakika, karışım kıvam alana kadar pişirin; ılıtarak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a16_091", title: "Erikli yulaflı fırın tatlısı", category: "Tatlılar", ingredients: ["8 erik", "yarım su bardağı yulaf", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın. Erikleri çekirdeklerinden ayırıp dörde bölün; yulafla harmanlayın.", "Süt, yulaf unu ve tarçını ayrı kapta çırpın; meyveli karışıma ekleyin.", "Karışımı küçük fırın kaplarına eşit dağıtın; üzerini kaşıkla düzeltin.", "Orta rafta yaklaşık 25-30 dakika, karışım kıvam alana kadar pişirin; ılıtarak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a16_092", title: "Kayısılı bademli fırın tatlısı", category: "Tatlılar", ingredients: ["8 kayısı", "3 yemek kaşığı file badem", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın. Kayısıları ikiye bölüp çekirdeklerini çıkarın; bademleri ayırın.", "Süt, yulaf unu ve tarçını ayrı kapta çırpın; meyveli karışıma ekleyin.", "Karışımı küçük fırın kaplarına eşit dağıtın; üzerini kaşıkla düzeltin.", "Orta rafta yaklaşık 25-30 dakika, karışım kıvam alana kadar pişirin; ılıtarak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a16_093", title: "Portakallı elmalı fırın tatlısı", category: "Tatlılar", ingredients: ["1 portakal ve 1 elma", "1 çay kaşığı rendelenmiş portakal kabuğu", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın. Elmayı küçük küp doğrayın; portakalın kabuğunu ince rendeleyip suyunu sıkın.", "Süt, yulaf unu ve tarçını ayrı kapta çırpın; meyveli karışıma ekleyin.", "Karışımı küçük fırın kaplarına eşit dağıtın; üzerini kaşıkla düzeltin.", "Orta rafta yaklaşık 25-30 dakika, karışım kıvam alana kadar pişirin; ılıtarak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a16_094", title: "Vişneli yulaflı fırın tatlısı", category: "Tatlılar", ingredients: ["1 su bardağı çekirdeksiz vişne", "yarım su bardağı yulaf", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C’ye ısıtın. Vişnelerin çekirdeklerini çıkarıp yulafla karıştırın.", "Süt, yulaf unu ve tarçını ayrı kapta çırpın; meyveli karışıma ekleyin.", "Karışımı küçük fırın kaplarına eşit dağıtın; üzerini kaşıkla düzeltin.", "Orta rafta yaklaşık 25-30 dakika, karışım kıvam alana kadar pişirin; ılıtarak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a16_095", title: "İncirli cevizli fırın tatlısı", category: "Tatlılar", ingredients: ["5 taze incir", "3 yemek kaşığı ceviz", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C ısıtın; meyveleri yıkayıp çekirdeklerini çıkarın ve doğrayın.", "Ana malzemeleri süt, yulaf unu ve tarçınla karıştırın.", "Karışımı küçük fırın kaplarına paylaştırın; üzerini düzeltin.", "Yaklaşık 20-30 dakika, üstü hafif kızarıp içi sıcak olana kadar pişirin; ılıtarak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a16_096", title: "Hurmalı kakaolu fırın tatlısı", category: "Tatlılar", ingredients: ["6 çekirdeksiz hurma", "1 yemek kaşığı kakao", "Yarım su bardağı süt", "2 yemek kaşığı yulaf unu", "Yarım çay kaşığı tarçın"], steps: ["Fırını 180°C ısıtın; meyveleri yıkayıp çekirdeklerini çıkarın ve doğrayın.", "Ana malzemeleri süt, yulaf unu ve tarçınla karıştırın.", "Karışımı küçük fırın kaplarına paylaştırın; üzerini düzeltin.", "Yaklaşık 20-30 dakika, üstü hafif kızarıp içi sıcak olana kadar pişirin; ılıtarak servis edin."], minutes: 40),
  GeneralRecipe(id: "p39a16_097", title: "Ispanaklı lorlu makarna", category: "Makarnalar", ingredients: ["250 g tam buğday makarna", "200 g ıspanak", "100 g lor", "1 yemek kaşığı zeytinyağı", "1 diş sarımsak", "Yarım çay bardağı makarna haşlama suyu"], steps: ["Makarnayı paket süresine göre bol kaynar suda diri kıvamda haşlayın; suyundan bir miktar ayırın.", "Ana malzemeleri temizleyip doğrayın; pişmesi gerekenleri zeytinyağı ve sarımsakla tavada yumuşatın.", "Makarnayı tavaya alıp ayırdığınız haşlama suyunu azar azar ekleyin.", "Sos makarnayı kaplayana kadar 2 dakika karıştırın; sıcak servis edin."], minutes: 30, detailed: false),
