  GeneralRecipe(id: "p39a16_105", title: "Pırasalı mantarlı makarna", category: "Makarnalar", ingredients: ["250 g tam buğday makarna", "1 pırasa", "150 g mantar", "1 yemek kaşığı zeytinyağı", "1 diş sarımsak", "Yarım çay bardağı makarna haşlama suyu"], steps: ["Makarnayı paket süresine göre bol kaynar suda diri kıvamda haşlayın; suyundan bir miktar ayırın.", "Ana malzemeleri temizleyip doğrayın; pişmesi gerekenleri zeytinyağı ve sarımsakla tavada yumuşatın.", "Makarnayı tavaya alıp ayırdığınız haşlama suyunu azar azar ekleyin.", "Sos makarnayı kaplayana kadar 2 dakika karıştırın; sıcak servis edin."], minutes: 30, detailed: false),
