  GeneralRecipe(id: "p39a16_108", title: "Nohutlu ıspanaklı makarna", category: "Makarnalar", ingredients: ["250 g tam buğday makarna", "yarım su bardağı haşlanmış nohut", "150 g ıspanak", "1 yemek kaşığı zeytinyağı", "1 diş sarımsak", "Yarım çay bardağı makarna haşlama suyu"], steps: ["Makarnayı paket süresine göre bol kaynar suda diri kıvamda haşlayın; suyundan bir miktar ayırın.", "Ana malzemeleri temizleyip doğrayın; pişmesi gerekenleri zeytinyağı ve sarımsakla tavada yumuşatın.", "Makarnayı tavaya alıp ayırdığınız haşlama suyunu azar azar ekleyin.", "Sos makarnayı kaplayana kadar 2 dakika karıştırın; sıcak servis edin."], minutes: 30, detailed: false),
  GeneralRecipe(id: "p39a16_109", title: "Yoğurtlu pancar mezesi", category: "Mezeler", ingredients: ["2 haşlanmış pancar", "1 su bardağı yoğurt", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı limon suyu", "1 diş sarımsak"], steps: ["Ana malzemeleri temizleyin; pişirilmesi gereken sebze ve bakliyatları tamamen pişirip soğutun.", "Tarifin ana malzemelerini ince doğrayın veya çatalla ezin.", "Zeytinyağı, limon suyu ve ezilmiş sarımsağı ekleyip homojen olana kadar karıştırın.", "Buzdolabında 15 dakika dinlendirip temiz servis kabında sunun."], minutes: 30, detailed: false),
