  GeneralRecipe(id: "p39a16_118", title: "Pazı ve yoğurt mezesi", category: "Mezeler", ingredients: ["1 demet pazı", "1 su bardağı yoğurt", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı limon suyu", "1 diş sarımsak"], steps: ["Ana malzemeleri temizleyin; pişirilmesi gereken sebze ve bakliyatları tamamen pişirip soğutun.", "Tarifin ana malzemelerini ince doğrayın veya çatalla ezin.", "Zeytinyağı, limon suyu ve ezilmiş sarımsağı ekleyip homojen olana kadar karıştırın.", "Buzdolabında 15 dakika dinlendirip temiz servis kabında sunun."], minutes: 30, detailed: false),
  GeneralRecipe(id: "p39a16_119", title: "Patlıcan ve domates mezesi", category: "Mezeler", ingredients: ["2 közlenmiş patlıcan", "2 domates", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı limon suyu", "1 diş sarımsak"], steps: ["Ana malzemeleri temizleyin; pişirilmesi gereken sebze ve bakliyatları tamamen pişirip soğutun.", "Tarifin ana malzemelerini ince doğrayın veya çatalla ezin.", "Zeytinyağı, limon suyu ve ezilmiş sarımsağı ekleyip homojen olana kadar karıştırın.", "Buzdolabında 15 dakika dinlendirip temiz servis kabında sunun."], minutes: 30, detailed: false),
  GeneralRecipe(id: "p39a16_120", title: "Kereviz ve elma mezesi", category: "Mezeler", ingredients: ["1 küçük kereviz", "1 yeşil elma", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı limon suyu", "1 diş sarımsak"], steps: ["Ana malzemeleri temizleyin; pişirilmesi gereken sebze ve bakliyatları tamamen pişirip soğutun.", "Tarifin ana malzemelerini ince doğrayın veya çatalla ezin.", "Zeytinyağı, limon suyu ve ezilmiş sarımsağı ekleyip homojen olana kadar karıştırın.", "Buzdolabında 15 dakika dinlendirip temiz servis kabında sunun."], minutes: 30, detailed: false),
  GeneralRecipe(id: "p39a17_001", title: "Kabak ve dereotu çorbası", category: "Çorbalar", ingredients: ["2 orta boy kabak", "Yarım demet dereotu", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Sebzeleri yıkayıp ayıklayın; ana malzemeyi küçük ve eşit parçalara kesin.", "Soğanı zeytinyağında 3 dakika kavurun; kabak ve dereotu malzemesini (taze ot, limon veya yoğurtsa servis aşamasında) ekleyin.", "Suyu ekleyip malzemeler tamamen yumuşayana kadar 20–25 dakika hafif ateşte pişirin.", "Gerekirse blenderdan geçirin; taze otları ve limon suyunu ocaktan aldıktan sonra, yoğurdu ise ılıştırarak ekleyin."], minutes: 40),
  GeneralRecipe(id: "p39a17_004", title: "Karnabahar ve zerdeçal çorbası", category: "Çorbalar", ingredients: ["350 g karnabahar", "Yarım çay kaşığı zerdeçal", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Sebzeleri yıkayıp ayıklayın; ana malzemeyi küçük ve eşit parçalara kesin.", "Soğanı zeytinyağında 3 dakika kavurun; karnabahar ve zerdeçal malzemesini (taze ot, limon veya yoğurtsa servis aşamasında) ekleyin.", "Suyu ekleyip malzemeler tamamen yumuşayana kadar 20–25 dakika hafif ateşte pişirin.", "Gerekirse blenderdan geçirin; taze otları ve limon suyunu ocaktan aldıktan sonra, yoğurdu ise ılıştırarak ekleyin."], minutes: 40),
  GeneralRecipe(id: "p39a17_005", title: "Pırasa ve patates çorbası", category: "Çorbalar", ingredients: ["2 pırasa", "1 küçük patates", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Sebzeleri yıkayıp ayıklayın; ana malzemeyi küçük ve eşit parçalara kesin.", "Soğanı zeytinyağında 3 dakika kavurun; pırasa ve patates malzemesini (taze ot, limon veya yoğurtsa servis aşamasında) ekleyin.", "Suyu ekleyip malzemeler tamamen yumuşayana kadar 20–25 dakika hafif ateşte pişirin.", "Gerekirse blenderdan geçirin; taze otları ve limon suyunu ocaktan aldıktan sonra, yoğurdu ise ılıştırarak ekleyin."], minutes: 40),
  GeneralRecipe(id: "p39a17_006", title: "Kereviz ve elma çorbası", category: "Çorbalar", ingredients: ["1 orta boy kereviz", "1 küçük elma", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Sebzeleri yıkayıp ayıklayın; ana malzemeyi küçük ve eşit parçalara kesin.", "Soğanı zeytinyağında 3 dakika kavurun; kereviz ve elma malzemesini (taze ot, limon veya yoğurtsa servis aşamasında) ekleyin.", "Suyu ekleyip malzemeler tamamen yumuşayana kadar 20–25 dakika hafif ateşte pişirin.", "Gerekirse blenderdan geçirin; taze otları ve limon suyunu ocaktan aldıktan sonra, yoğurdu ise ılıştırarak ekleyin."], minutes: 40),
  GeneralRecipe(id: "p39a17_007", title: "Domates ve fesleğen çorbası", category: "Çorbalar", ingredients: ["4 olgun domates", "5 yaprak taze fesleğen", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Sebzeleri yıkayıp ayıklayın; ana malzemeyi küçük ve eşit parçalara kesin.", "Soğanı zeytinyağında 3 dakika kavurun; domates ve fesleğen malzemesini (taze ot, limon veya yoğurtsa servis aşamasında) ekleyin.", "Suyu ekleyip malzemeler tamamen yumuşayana kadar 20–25 dakika hafif ateşte pişirin.", "Gerekirse blenderdan geçirin; taze otları ve limon suyunu ocaktan aldıktan sonra, yoğurdu ise ılıştırarak ekleyin."], minutes: 40),
  GeneralRecipe(id: "p39a17_008", title: "Mercimek ve kimyon çorbası", category: "Çorbalar", ingredients: ["1 su bardağı kırmızı mercimek", "1 çay kaşığı kimyon", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Sebzeleri yıkayıp ayıklayın; ana malzemeyi küçük ve eşit parçalara kesin.", "Soğanı zeytinyağında 3 dakika kavurun; mercimek ve kimyon malzemesini (taze ot, limon veya yoğurtsa servis aşamasında) ekleyin.", "Suyu ekleyip malzemeler tamamen yumuşayana kadar 20–25 dakika hafif ateşte pişirin.", "Gerekirse blenderdan geçirin; taze otları ve limon suyunu ocaktan aldıktan sonra, yoğurdu ise ılıştırarak ekleyin."], minutes: 40),
  GeneralRecipe(id: "p39a17_009", title: "Mantar ve kekik çorbası", category: "Çorbalar", ingredients: ["300 g kültür mantarı", "1 çay kaşığı kekik", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Sebzeleri yıkayıp ayıklayın; ana malzemeyi küçük ve eşit parçalara kesin.", "Soğanı zeytinyağında 3 dakika kavurun; mantar ve kekik malzemesini (taze ot, limon veya yoğurtsa servis aşamasında) ekleyin.", "Suyu ekleyip malzemeler tamamen yumuşayana kadar 20–25 dakika hafif ateşte pişirin.", "Gerekirse blenderdan geçirin; taze otları ve limon suyunu ocaktan aldıktan sonra, yoğurdu ise ılıştırarak ekleyin."], minutes: 40),
  GeneralRecipe(id: "p39a17_010", title: "Balkabağı ve hindistan cevizi sütü çorbası", category: "Çorbalar", ingredients: ["350 g balkabağı", "Yarım su bardağı hindistan cevizi sütü", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Sebzeleri yıkayıp ayıklayın; ana malzemeyi küçük ve eşit parçalara kesin.", "Soğanı zeytinyağında 3 dakika kavurun; balkabağı ve hindistan cevizi sütü malzemesini (taze ot, limon veya yoğurtsa servis aşamasında) ekleyin.", "Suyu ekleyip malzemeler tamamen yumuşayana kadar 20–25 dakika hafif ateşte pişirin.", "Gerekirse blenderdan geçirin; taze otları ve limon suyunu ocaktan aldıktan sonra, yoğurdu ise ılıştırarak ekleyin."], minutes: 40),
  GeneralRecipe(id: "p39a17_013", title: "Köz biber ve domates çorbası", category: "Çorbalar", ingredients: ["3 közlenmiş kapya biber", "2 olgun domates", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Sebzeleri yıkayıp ayıklayın; ana malzemeyi küçük ve eşit parçalara kesin.", "Soğanı zeytinyağında 3 dakika kavurun; köz biber ve domates malzemesini (taze ot, limon veya yoğurtsa servis aşamasında) ekleyin.", "Suyu ekleyip malzemeler tamamen yumuşayana kadar 20–25 dakika hafif ateşte pişirin.", "Gerekirse blenderdan geçirin; taze otları ve limon suyunu ocaktan aldıktan sonra, yoğurdu ise ılıştırarak ekleyin."], minutes: 40),
  GeneralRecipe(id: "p39a17_014", title: "Nohut ve limon çorbası", category: "Çorbalar", ingredients: ["2 su bardağı haşlanmış nohut", "1 yemek kaşığı limon suyu", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Sebzeleri yıkayıp ayıklayın; ana malzemeyi küçük ve eşit parçalara kesin.", "Soğanı zeytinyağında 3 dakika kavurun; nohut ve limon malzemesini (taze ot, limon veya yoğurtsa servis aşamasında) ekleyin.", "Suyu ekleyip malzemeler tamamen yumuşayana kadar 20–25 dakika hafif ateşte pişirin.", "Gerekirse blenderdan geçirin; taze otları ve limon suyunu ocaktan aldıktan sonra, yoğurdu ise ılıştırarak ekleyin."], minutes: 40),
  GeneralRecipe(id: "p39a17_015", title: "Pancar ve yoğurt çorbası", category: "Çorbalar", ingredients: ["2 küçük haşlanmış pancar", "3 yemek kaşığı yoğurt", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su"], steps: ["Sebzeleri yıkayıp ayıklayın; ana malzemeyi küçük ve eşit parçalara kesin.", "Soğanı zeytinyağında 3 dakika kavurun; pancar ve yoğurt malzemesini (taze ot, limon veya yoğurtsa servis aşamasında) ekleyin.", "Suyu ekleyip malzemeler tamamen yumuşayana kadar 20–25 dakika hafif ateşte pişirin.", "Gerekirse blenderdan geçirin; taze otları ve limon suyunu ocaktan aldıktan sonra, yoğurdu ise ılıştırarak ekleyin."], minutes: 40),
  GeneralRecipe(id: "p39a17_016", title: "Kabak ve nohut ile tencere yemeği", category: "Sebze yemekleri", ingredients: ["1 porsiyonluk kabak (yaklaşık 200 g)", "1 küçük porsiyon nohut (yaklaşık 50 g)", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "1 su bardağı su"], steps: ["Kabak ve nohut malzemelerini temizleyip eşit büyüklükte doğrayın.", "Soğanı zeytinyağında şeffaflaşana kadar kavurun.", "Sebzeleri ekleyip 5 dakika çevirin, suyu ilave edin.", "Kapağı kapalı tencerede sebzeler yumuşayana kadar 20-30 dakika pişirin; suyunu kontrol edin."], minutes: 40),
