  GeneralRecipe(id: "p39a17_120", title: "Havuç ve zencefil ile makarnası", category: "Makarnalar", ingredients: ["1 porsiyonluk havuç (yaklaşık 200 g)", "1 küçük porsiyon zencefil (yaklaşık 50 g)", "250 g makarna", "1 yemek kaşığı zeytinyağı", "1 diş sarımsak"], steps: ["Makarnayı paket üzerindeki süreye göre kaynar suda haşlayın; yarım çay bardağı haşlama suyu ayırın.", "Havuç ve zencefil malzemelerini temizleyip doğrayın.", "Sarımsak ve ana malzemeleri yağda, sebzeler yumuşayana kadar soteleyin.", "Makarnayı ve ayırdığınız suyu ekleyip 2 dakika karıştırarak sosla birleştirin."], minutes: 25),
  GeneralRecipe(id: "p39a17_121", title: "Elma ve ceviz ile yoğurtlu kup", category: "Tatlılar", ingredients: ["1 porsiyonluk elma (yaklaşık 200 g)", "1 küçük porsiyon ceviz (yaklaşık 50 g)", "1 su bardağı yoğurt", "3 yemek kaşığı yulaf ezmesi", "1 tatlı kaşığı bal (isteğe bağlı)"], steps: ["Elma ve ceviz malzemelerini yenmeye hazır şekilde temizleyip küçük parçalar halinde hazırlayın.", "Yulafı tavada yağsız olarak 2 dakika çevirip soğumaya bırakın.", "Yoğurdu servis kaselerine bölüştürün; meyve ve diğer malzemeleri katmanlayın.", "İsteğe bağlı balı ekleyip hemen servis edin; buzdolabında saklayacaksanız üzerini kapatın."], minutes: 20),
  GeneralRecipe(id: "p39a17_122", title: "Armut ve tarçın ile yoğurtlu kup", category: "Tatlılar", ingredients: ["1 porsiyonluk armut (yaklaşık 200 g)", "1 küçük porsiyon tarçın (yaklaşık 50 g)", "1 su bardağı yoğurt", "3 yemek kaşığı yulaf ezmesi", "1 tatlı kaşığı bal (isteğe bağlı)"], steps: ["Armut ve tarçın malzemelerini yenmeye hazır şekilde temizleyip küçük parçalar halinde hazırlayın.", "Yulafı tavada yağsız olarak 2 dakika çevirip soğumaya bırakın.", "Yoğurdu servis kaselerine bölüştürün; meyve ve diğer malzemeleri katmanlayın.", "İsteğe bağlı balı ekleyip hemen servis edin; buzdolabında saklayacaksanız üzerini kapatın."], minutes: 20),
  GeneralRecipe(id: "p39a17_123", title: "Muz ve kakao ile yoğurtlu kup", category: "Tatlılar", ingredients: ["1 porsiyonluk muz (yaklaşık 200 g)", "1 küçük porsiyon kakao (yaklaşık 50 g)", "1 su bardağı yoğurt", "3 yemek kaşığı yulaf ezmesi", "1 tatlı kaşığı bal (isteğe bağlı)"], steps: ["Muz ve kakao malzemelerini yenmeye hazır şekilde temizleyip küçük parçalar halinde hazırlayın.", "Yulafı tavada yağsız olarak 2 dakika çevirip soğumaya bırakın.", "Yoğurdu servis kaselerine bölüştürün; meyve ve diğer malzemeleri katmanlayın.", "İsteğe bağlı balı ekleyip hemen servis edin; buzdolabında saklayacaksanız üzerini kapatın."], minutes: 20),
