  GeneralRecipe(id: "p39a18_001", title: "Fırında sarımsaklı kabak", category: "Sebze yemekleri", ingredients: ["2 orta boy kabak", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Kabakları yıkayıp 1 cm kalınlığında yarım ay dilimleyin; fazla suyunu kâğıt havluyla alın.", "Sarımsağı ezip zeytinyağı, kekik ve az tuzla karıştırın; sebzeleri bu sosla kaplayın.", "Sebzeleri fırın kâğıtlı tepsiye tek kat yayın; 200°C önceden ısıtılmış fırına verin.", "Sebzeler yumuşayıp kenarları kızarana kadar 20–30 dakika pişirin; pişirme ortasında çevirin."], minutes: 35),
  GeneralRecipe(id: "p39a18_002", title: "Fırında sarımsaklı patlıcan", category: "Sebze yemekleri", ingredients: ["2 orta boy patlıcan", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Patlıcanları alacalı soyup küp doğrayın; 15 dakika tuzlu suda bekletip iyice kurulayın.", "Sarımsağı ezip zeytinyağı, kekik ve az tuzla karıştırın; sebzeleri bu sosla kaplayın.", "Sebzeleri fırın kâğıtlı tepsiye tek kat yayın; 200°C önceden ısıtılmış fırına verin.", "Sebzeler yumuşayıp kenarları kızarana kadar 20–30 dakika pişirin; pişirme ortasında çevirin."], minutes: 35),
  GeneralRecipe(id: "p39a18_003", title: "Fırında sarımsaklı karnabahar", category: "Sebze yemekleri", ingredients: ["1 küçük karnabahar", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Karnabaharı küçük çiçeklere ayırıp yıkayın; çok iri parçaları ikiye bölün.", "Sarımsağı ezip zeytinyağı, kekik ve az tuzla karıştırın; sebzeleri bu sosla kaplayın.", "Sebzeleri fırın kâğıtlı tepsiye tek kat yayın; 200°C önceden ısıtılmış fırına verin.", "Sebzeler yumuşayıp kenarları kızarana kadar 20–30 dakika pişirin; pişirme ortasında çevirin."], minutes: 35),
  GeneralRecipe(id: "p39a18_004", title: "Fırında sarımsaklı brokoli", category: "Sebze yemekleri", ingredients: ["1 orta boy brokoli", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Brokoliyi çiçeklere ayırın, kalın saplarını ince dilimleyin ve iyice kurulayın.", "Sarımsağı ezip zeytinyağı, kekik ve az tuzla karıştırın; sebzeleri bu sosla kaplayın.", "Sebzeleri fırın kâğıtlı tepsiye tek kat yayın; 200°C önceden ısıtılmış fırına verin.", "Sebzeler yumuşayıp kenarları kızarana kadar 20–30 dakika pişirin; pişirme ortasında çevirin."], minutes: 35),
  GeneralRecipe(id: "p39a18_005", title: "Fırında sarımsaklı pırasa", category: "Sebze yemekleri", ingredients: ["3 sap pırasa", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Pırasaları boyuna kesip katlarını iyice yıkayın; 3 cm parçalar hâlinde doğrayın.", "Sarımsağı ezip zeytinyağı, kekik ve az tuzla karıştırın; sebzeleri bu sosla kaplayın.", "Sebzeleri fırın kâğıtlı tepsiye tek kat yayın; 200°C önceden ısıtılmış fırına verin.", "Sebzeler tamamen yumuşayıp kenarları kızarana kadar 30–35 dakika pişirin; gerekirse üzerini kısa süre örtün."], minutes: 45),
  GeneralRecipe(id: "p39a18_006", title: "Fırında sarımsaklı ıspanak", category: "Sebze yemekleri", ingredients: ["350 g ıspanak", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Ispanağı bol suyla yıkayıp süzün, kalın saplarını ayırın ve iri doğrayın.", "Sarımsağı zeytinyağıyla karıştırın; yaprak ve sapları geniş fırın kabına alın.", "Sert sapları önce 190°C fırında 8 dakika pişirin; yaprakları ekleyip karıştırın.", "Yapraklar sönüp yumuşayana kadar 8–12 dakika daha pişirin; limonla servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a18_007", title: "Fırında sarımsaklı pazı", category: "Sebze yemekleri", ingredients: ["1 demet pazı", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Pazı yapraklarını yıkayıp kurulayın; sert sapları ince, yaprakları iri doğrayın.", "Sarımsağı zeytinyağıyla karıştırın; yaprak ve sapları geniş fırın kabına alın.", "Sert sapları önce 190°C fırında 8 dakika pişirin; yaprakları ekleyip karıştırın.", "Yapraklar sönüp yumuşayana kadar 8–12 dakika daha pişirin; limonla servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a18_008", title: "Fırında sarımsaklı kereviz", category: "Sebze yemekleri", ingredients: ["1 orta boy kereviz", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Kerevizi soyup 2 cm küpler hâlinde kesin; kararmaması için limonlu suda tutun.", "Sarımsağı ezip zeytinyağı, kekik ve az tuzla karıştırın; sebzeleri bu sosla kaplayın.", "Sebzeleri fırın kâğıtlı tepsiye tek kat yayın; 200°C önceden ısıtılmış fırına verin.", "Sebzeler tamamen yumuşayıp kenarları kızarana kadar 30–35 dakika pişirin; gerekirse üzerini kısa süre örtün."], minutes: 45),
  GeneralRecipe(id: "p39a18_009", title: "Fırında sarımsaklı havuç", category: "Sebze yemekleri", ingredients: ["4 orta boy havuç", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Havuçları soyup eşit kalınlıkta, yaklaşık 1 cm çubuklar hâlinde kesin.", "Sarımsağı ezip zeytinyağı, kekik ve az tuzla karıştırın; sebzeleri bu sosla kaplayın.", "Sebzeleri fırın kâğıtlı tepsiye tek kat yayın; 200°C önceden ısıtılmış fırına verin.", "Sebzeler yumuşayıp kenarları kızarana kadar 20–30 dakika pişirin; pişirme ortasında çevirin."], minutes: 35),
  GeneralRecipe(id: "p39a18_010", title: "Fırında sarımsaklı mantar", category: "Sebze yemekleri", ingredients: ["400 g kültür mantarı", "2 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 çay kaşığı kuru kekik", "1 yemek kaşığı limon suyu", "Az tuz"], steps: ["Mantarları nemli bezle temizleyip ikiye bölün; suya yatırmayın.", "Sarımsak, zeytinyağı ve kekiği mantarlarla harmanlayın.", "Mantarları geniş tepsiye tek kat yayın; 200°C fırında 15 dakika pişirin.", "Suyunu bırakıp kenarları kızarınca karıştırın; 5–8 dakika daha pişirip servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a18_011", title: "Yoğurtlu kabak salatası", category: "Salatalar", ingredients: ["300 g kabak", "5 yemek kaşığı süzme yoğurt", "1 diş sarımsak", "1 yemek kaşığı zeytinyağı", "1 tatlı kaşığı limon suyu"], steps: ["Sebzeyi yıkayıp küçük doğrayın; kaynar suda veya buharda tamamen yumuşayana kadar pişirin.", "Süzüp soğumaya bırakın; fazla suyunu alın.", "Yoğurdu sarımsak ve limonla çırpın.", "Sebzeyi yoğurtla karıştırıp zeytinyağı gezdirerek soğuk servis edin."], minutes: 35, detailed: false),
