  GeneralRecipe(id: "p39a18_031", title: "Kabak ve peynirli omlet", category: "Kahvaltılıklar", ingredients: ["100 g kabak", "2 yumurta", "40 g beyaz peynir", "1 tatlı kaşığı zeytinyağı", "2 yemek kaşığı süt"], steps: ["Sebzeyi yıkayıp küçük doğrayın; sert sebzeleri az suda yumuşayana kadar ön pişirin.", "Sebzeyi yağlanmış tavada 3–4 dakika soteleyin.", "Yumurtaları süt ve ufalanmış peynirle çırpıp tavaya dökün.", "Kapağı kapalı olarak yumurta tamamen katılaşana kadar pişirin."], minutes: 25, detailed: false),
