  GeneralRecipe(id: "p39a18_071", title: "Kabak ve fırın somon", category: "Balık ve deniz ürünleri", ingredients: ["2 adet 150 g somon fileto", "2 orta boy kabak", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 limonun suyu", "Karabiber ve az tuz"], steps: ["Kabak sebzesini temizleyip eşit boyda doğrayın.", "Sebzeyi zeytinyağıyla harmanlayıp fırın kabına yayın.", "Somon filetolarını sebzelerin üzerine yerleştirip limon suyu, sarımsak ve karabiber ekleyin.", "190°C fırında somonun en kalın kısmı 63°C olana ve sebzeler yumuşayana kadar pişirin; sebzelerin durumunu ayrıca kontrol edin."], minutes: 30),
  GeneralRecipe(id: "p39a18_072", title: "Patlıcan ve fırın somon", category: "Balık ve deniz ürünleri", ingredients: ["2 adet 150 g somon fileto", "2 orta boy patlıcan", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 limonun suyu", "Karabiber ve az tuz"], steps: ["Patlıcan sebzesini temizleyip eşit boyda doğrayın.", "Sebzeyi zeytinyağıyla harmanlayıp fırın kabına yayın.", "Somon filetolarını sebzelerin üzerine yerleştirip limon suyu, sarımsak ve karabiber ekleyin.", "190°C fırında somonun en kalın kısmı 63°C olana ve sebzeler yumuşayana kadar pişirin; sebzelerin durumunu ayrıca kontrol edin."], minutes: 30),
  GeneralRecipe(id: "p39a18_073", title: "Karnabahar ve fırın somon", category: "Balık ve deniz ürünleri", ingredients: ["2 adet 150 g somon fileto", "1 küçük karnabahar", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 limonun suyu", "Karabiber ve az tuz"], steps: ["Karnabahar sebzesini temizleyip eşit boyda doğrayın.", "Sebzeyi 200°C fırında 12–15 dakika ön pişirin; sertse küçük doğrayın.", "Somon filetolarını sebzelerin üzerine yerleştirip limon suyu, sarımsak ve karabiber ekleyin.", "190°C fırında somonun en kalın kısmı 63°C olana ve sebzeler yumuşayana kadar pişirin; sebzelerin durumunu ayrıca kontrol edin."], minutes: 40),
  GeneralRecipe(id: "p39a18_074", title: "Brokoli ve fırın somon", category: "Balık ve deniz ürünleri", ingredients: ["2 adet 150 g somon fileto", "1 orta boy brokoli", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 limonun suyu", "Karabiber ve az tuz"], steps: ["Brokoli sebzesini temizleyip eşit boyda doğrayın.", "Sebzeyi 200°C fırında 12–15 dakika ön pişirin; sertse küçük doğrayın.", "Somon filetolarını sebzelerin üzerine yerleştirip limon suyu, sarımsak ve karabiber ekleyin.", "190°C fırında somonun en kalın kısmı 63°C olana ve sebzeler yumuşayana kadar pişirin; sebzelerin durumunu ayrıca kontrol edin."], minutes: 40),
  GeneralRecipe(id: "p39a18_075", title: "Pırasa ve fırın somon", category: "Balık ve deniz ürünleri", ingredients: ["2 adet 150 g somon fileto", "3 sap pırasa", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 limonun suyu", "Karabiber ve az tuz"], steps: ["Pırasa sebzesini temizleyip eşit boyda doğrayın.", "Sebzeyi 200°C fırında 12–15 dakika ön pişirin; sertse küçük doğrayın.", "Somon filetolarını sebzelerin üzerine yerleştirip limon suyu, sarımsak ve karabiber ekleyin.", "190°C fırında somonun en kalın kısmı 63°C olana ve sebzeler yumuşayana kadar pişirin; sebzelerin durumunu ayrıca kontrol edin."], minutes: 40),
  GeneralRecipe(id: "p39a18_076", title: "Ispanak ve fırın somon", category: "Balık ve deniz ürünleri", ingredients: ["2 adet 150 g somon fileto", "350 g ıspanak", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 limonun suyu", "Karabiber ve az tuz"], steps: ["Ispanak yapraklarını iyice yıkayıp saplarını ayırın; sarımsağı ince doğrayın.", "Yaprakları zeytinyağında 3–4 dakika soteleyip suyunu hafifçe çektirin.", "Somonları ayrı fırın kabına alıp limon, karabiber ve az zeytinyağıyla tatlandırın.", "190°C fırında somonun en kalın kısmı 63°C olana kadar yaklaşık 15–20 dakika pişirin; yeşillikle servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a18_077", title: "Pazı ve fırın somon", category: "Balık ve deniz ürünleri", ingredients: ["2 adet 150 g somon fileto", "1 demet pazı", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 limonun suyu", "Karabiber ve az tuz"], steps: ["Pazı yapraklarını iyice yıkayıp saplarını ayırın; sarımsağı ince doğrayın.", "Yaprakları zeytinyağında 3–4 dakika soteleyip suyunu hafifçe çektirin.", "Somonları ayrı fırın kabına alıp limon, karabiber ve az zeytinyağıyla tatlandırın.", "190°C fırında somonun en kalın kısmı 63°C olana kadar yaklaşık 15–20 dakika pişirin; yeşillikle servis edin."], minutes: 30),
  GeneralRecipe(id: "p39a18_078", title: "Kereviz ve fırın somon", category: "Balık ve deniz ürünleri", ingredients: ["2 adet 150 g somon fileto", "1 orta boy kereviz", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 limonun suyu", "Karabiber ve az tuz"], steps: ["Kereviz sebzesini temizleyip eşit boyda doğrayın.", "Sebzeyi 200°C fırında 12–15 dakika ön pişirin; sertse küçük doğrayın.", "Somon filetolarını sebzelerin üzerine yerleştirip limon suyu, sarımsak ve karabiber ekleyin.", "190°C fırında somonun en kalın kısmı 63°C olana ve sebzeler yumuşayana kadar pişirin; sebzelerin durumunu ayrıca kontrol edin."], minutes: 40),
  GeneralRecipe(id: "p39a18_079", title: "Havuç ve fırın somon", category: "Balık ve deniz ürünleri", ingredients: ["2 adet 150 g somon fileto", "4 orta boy havuç", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 limonun suyu", "Karabiber ve az tuz"], steps: ["Havuç sebzesini temizleyip eşit boyda doğrayın.", "Sebzeyi 200°C fırında 12–15 dakika ön pişirin; sertse küçük doğrayın.", "Somon filetolarını sebzelerin üzerine yerleştirip limon suyu, sarımsak ve karabiber ekleyin.", "190°C fırında somonun en kalın kısmı 63°C olana ve sebzeler yumuşayana kadar pişirin; sebzelerin durumunu ayrıca kontrol edin."], minutes: 40),
  GeneralRecipe(id: "p39a18_080", title: "Mantar ve fırın somon", category: "Balık ve deniz ürünleri", ingredients: ["2 adet 150 g somon fileto", "400 g kültür mantarı", "1 diş sarımsak", "2 yemek kaşığı zeytinyağı", "1 limonun suyu", "Karabiber ve az tuz"], steps: ["Mantarları temizleyip dilimleyin; sarımsağı ezin.", "Mantarları az yağda suyunu çekene kadar 5–6 dakika soteleyin.", "Somonları fırın kabına alıp mantar, limon ve sarımsakla çevreleyin.", "190°C fırında somonun içi 63°C olana kadar yaklaşık 15–20 dakika pişirin."], minutes: 30),
  GeneralRecipe(id: "p39a18_081", title: "Kabak ve tahinli meze", category: "Mezeler", ingredients: ["250 g kabak", "1 yemek kaşığı tahin", "2 yemek kaşığı yoğurt", "1 tatlı kaşığı limon suyu", "1 küçük diş sarımsak"], steps: ["Sebzeyi temizleyip tamamen yumuşayana kadar buharda veya fırında pişirin.", "Soğuyan sebzeyi çatalla ezin veya ince doğrayın.", "Tahin, yoğurt, limon ve ezilmiş sarımsakla karıştırın.", "Buzdolabında 15 dakika dinlendirerek servis edin."], minutes: 35, detailed: false),
  GeneralRecipe(id: "p39a18_082", title: "Patlıcan ve tahinli meze", category: "Mezeler", ingredients: ["250 g patlıcan", "1 yemek kaşığı tahin", "2 yemek kaşığı yoğurt", "1 tatlı kaşığı limon suyu", "1 küçük diş sarımsak"], steps: ["Sebzeyi temizleyip tamamen yumuşayana kadar buharda veya fırında pişirin.", "Soğuyan sebzeyi çatalla ezin veya ince doğrayın.", "Tahin, yoğurt, limon ve ezilmiş sarımsakla karıştırın.", "Buzdolabında 15 dakika dinlendirerek servis edin."], minutes: 35, detailed: false),
