  GeneralRecipe(id: "p39a18_129", title: "Havuç ve pirinçli sebze yemeği", category: "Sebze yemekleri", ingredients: ["4 orta boy havuç", "Yarım su bardağı pirinç", "1 küçük kuru soğan", "2 yemek kaşığı zeytinyağı", "1,5 su bardağı sıcak su", "Az tuz"], steps: ["Havuç sebzesini yıkayıp küçük, eşit büyüklükte doğrayın; soğanı kıyın.", "Soğanı zeytinyağında 3 dakika soteleyip sebzeyi ekleyin; 4–5 dakika çevirin.", "Yıkanmış pirinci ve sıcak suyu ekleyin; kapağını kapatın.", "Sebze ve pirinç tamamen yumuşayana kadar kısık ateşte 18–25 dakika pişirin; su azalırsa azar azar sıcak su ekleyin."], minutes: 40),
  GeneralRecipe(id: "p39a18_130", title: "Mantar ve pirinçli sebze yemeği", category: "Sebze yemekleri", ingredients: ["400 g kültür mantarı", "Yarım su bardağı pirinç", "1 küçük kuru soğan", "2 yemek kaşığı zeytinyağı", "1,5 su bardağı sıcak su", "Az tuz"], steps: ["Mantarları temizleyip dilimleyin; soğanı küçük doğrayın.", "Mantarları geniş tencerede suyunu çekene kadar soteleyin; soğan ve zeytinyağını ekleyin.", "Yıkanmış pirinci katıp 1 dakika çevirin; sıcak suyu ekleyin.", "Kısık ateşte pirinç yumuşayana kadar 15–18 dakika pişirip 5 dakika dinlendirin."], minutes: 40),
  GeneralRecipe(id: "p39a18_131", title: "Kabak ve lorlu fırın mücver", category: "Sebze yemekleri", ingredients: ["250 g kabak", "2 yumurta", "4 yemek kaşığı tam buğday unu", "80 g lor peyniri", "1 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C ısıtın; sebzeyi rendeleyin veya çok ince doğrayın.", "Sulu sebzelerin suyunu sıkın; sert sebzeleri kısa süre ön pişirin.", "Yumurta, un, lor ve yağla karıştırıp yağlı kağıtlı tepsiye küçük porsiyonlar koyun.", "İçi tamamen pişip yüzeyi kızarana kadar 20–25 dakika fırınlayın."], minutes: 40, detailed: false),
