  GeneralRecipe(id: "p39a19_001", title: "Balkabaklı zencefilli çorbası", category: "Çorbalar", ingredients: ["1 su bardağı doğranmış ana sebze veya bakliyat", "1 küçük soğan", "1 yemek kaşığı zeytinyağı", "4 su bardağı su", "Tuz ve karabiber"], steps: ["Soğanı ince kıyıp zeytinyağında 3 dakika yumuşatın.", "Tarifin adındaki sebzeleri yıkayıp küçük doğrayın; bakliyat kullanıyorsanız önceden haşlayın.", "Malzemeleri ve suyu ekleyerek sebzeler yumuşayıncaya kadar 20–25 dakika pişirin.", "Kıvamını ayarlayın; taneli bırakın veya isteğe göre blenderdan geçirin."], minutes: 35, detailed: false),
  GeneralRecipe(id: "p39a19_011", title: "Enginar ve bezelye zeytinyağlısı", category: "Sebze yemekleri", ingredients: ["400 g tarifte adı geçen sebzeler", "1 küçük soğan", "1 domates", "3 yemek kaşığı zeytinyağı", "Yarım su bardağı sıcak su", "1 tatlı kaşığı limon suyu"], steps: ["Sebzeleri ayıklayıp eşit boyda doğrayın; bakliyat varsa önceden haşlayın.", "Soğanı yağda 3 dakika çevirin; domatesi ve sebzeleri ekleyin.", "Sıcak suyu ekleyip kapağı kapalı şekilde sebzeler yumuşayıncaya kadar pişirin.", "Limon suyunu ekleyip dinlendirdikten sonra servis edin."], minutes: 45, detailed: false),
  GeneralRecipe(id: "p39a19_021", title: "Mantarlı kekikli tavuk sote", category: "Kek ve kurabiyeler", ingredients: ["350 g kuşbaşı tavuk göğsü", "200 g mantar", "1 çay kaşığı kekik", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu ve sebzeleri ayrı kesme tahtalarında hazırlayın; mantar malzemesini uygun büyüklükte doğrayın.", "Soğanı yağda 2 dakika çevirin; tavuğu ekleyip her tarafını renk alana kadar 5–6 dakika soteleyin.", "Mantar malzemesini ve sıcak suyu ekleyip kapağı kapalı 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Kekik malzemesini son aşamada ekleyip 1–2 dakika harmanlayın; sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a19_022", title: "Kabaklı limonlu tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "1 orta boy kabak", "Yarım limonun suyu", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu ve sebzeleri ayrı kesme tahtalarında hazırlayın; kabak malzemesini uygun büyüklükte doğrayın.", "Soğanı yağda 2 dakika çevirin; tavuğu ekleyip her tarafını renk alana kadar 5–6 dakika soteleyin.", "Kabak malzemesini ve sıcak suyu ekleyip kapağı kapalı 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Limon malzemesini son aşamada ekleyip 1–2 dakika harmanlayın; sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a19_023", title: "Kapya biberli fesleğenli tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "1 büyük kapya biber", "5 yaprak fesleğen", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu ve sebzeleri ayrı kesme tahtalarında hazırlayın; kapya biber malzemesini uygun büyüklükte doğrayın.", "Soğanı yağda 2 dakika çevirin; tavuğu ekleyip her tarafını renk alana kadar 5–6 dakika soteleyin.", "Kapya biber malzemesini ve sıcak suyu ekleyip kapağı kapalı 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Fesleğen malzemesini son aşamada ekleyip 1–2 dakika harmanlayın; sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a19_024", title: "Ispanaklı sarımsaklı tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "200 g ıspanak", "2 diş sarımsak", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu ve sebzeleri ayrı kesme tahtalarında hazırlayın; ıspanak malzemesini uygun büyüklükte doğrayın.", "Soğanı yağda 2 dakika çevirin; tavuğu ekleyip her tarafını renk alana kadar 5–6 dakika soteleyin.", "Ispanak malzemesini ve sıcak suyu ekleyip kapağı kapalı 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Sarımsak malzemesini son aşamada ekleyip 1–2 dakika harmanlayın; sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a19_025", title: "Brokolili zencefilli tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "200 g brokoli", "1 çay kaşığı taze zencefil", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu ve sebzeleri ayrı kesme tahtalarında hazırlayın; brokoli malzemesini uygun büyüklükte doğrayın.", "Soğanı yağda 2 dakika çevirin; tavuğu ekleyip her tarafını renk alana kadar 5–6 dakika soteleyin.", "Brokoli malzemesini ve sıcak suyu ekleyip kapağı kapalı 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Zencefil malzemesini son aşamada ekleyip 1–2 dakika harmanlayın; sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a19_026", title: "Havuçlu susamlı tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "2 havuç", "1 yemek kaşığı susam", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu ve sebzeleri ayrı kesme tahtalarında hazırlayın; havuç malzemesini uygun büyüklükte doğrayın.", "Soğanı yağda 2 dakika çevirin; tavuğu ekleyip her tarafını renk alana kadar 5–6 dakika soteleyin.", "Havuç malzemesini ve sıcak suyu ekleyip kapağı kapalı 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Susam malzemesini son aşamada ekleyip 1–2 dakika harmanlayın; sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a19_027", title: "Pırasalı hardallı tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "1 büyük pırasa", "1 tatlı kaşığı hardal", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu ve sebzeleri ayrı kesme tahtalarında hazırlayın; pırasa malzemesini uygun büyüklükte doğrayın.", "Soğanı yağda 2 dakika çevirin; tavuğu ekleyip her tarafını renk alana kadar 5–6 dakika soteleyin.", "Pırasa malzemesini ve sıcak suyu ekleyip kapağı kapalı 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Hardal malzemesini son aşamada ekleyip 1–2 dakika harmanlayın; sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a19_028", title: "Domatesli zeytinli tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "2 domates", "8 çekirdeksiz zeytin", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu ve sebzeleri ayrı kesme tahtalarında hazırlayın; domates malzemesini uygun büyüklükte doğrayın.", "Soğanı yağda 2 dakika çevirin; tavuğu ekleyip her tarafını renk alana kadar 5–6 dakika soteleyin.", "Domates malzemesini ve sıcak suyu ekleyip kapağı kapalı 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Zeytin malzemesini son aşamada ekleyip 1–2 dakika harmanlayın; sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a19_029", title: "Patlıcanlı kimyonlu tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "1 küçük patlıcan", "Yarım çay kaşığı kimyon", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu ve sebzeleri ayrı kesme tahtalarında hazırlayın; patlıcan malzemesini uygun büyüklükte doğrayın.", "Soğanı yağda 2 dakika çevirin; tavuğu ekleyip her tarafını renk alana kadar 5–6 dakika soteleyin.", "Patlıcan malzemesini ve sıcak suyu ekleyip kapağı kapalı 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Kimyon malzemesini son aşamada ekleyip 1–2 dakika harmanlayın; sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a19_030", title: "Bezelyeli dereotlu tavuk sote", category: "Tavuk yemekleri", ingredients: ["350 g kuşbaşı tavuk göğsü", "1 su bardağı bezelye", "4 dal dereotu", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "Yarım çay bardağı sıcak su"], steps: ["Tavuğu ve sebzeleri ayrı kesme tahtalarında hazırlayın; bezelye malzemesini uygun büyüklükte doğrayın.", "Soğanı yağda 2 dakika çevirin; tavuğu ekleyip her tarafını renk alana kadar 5–6 dakika soteleyin.", "Bezelye malzemesini ve sıcak suyu ekleyip kapağı kapalı 10–15 dakika, tavuk tamamen pişene kadar pişirin.", "Dereotu malzemesini son aşamada ekleyip 1–2 dakika harmanlayın; sıcak servis edin."], minutes: 35),
  GeneralRecipe(id: "p39a19_031", title: "Nohutlu domatesli bulgur pilavı", category: "Pilavlar", ingredients: ["1 su bardağı pilavlık bulgur", "1 su bardağı tarifte belirtilen doğranmış veya haşlanmış ek malzeme", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su", "Tuz"], steps: ["Bulguru yıkayıp süzün; tarifte geçen sebzeleri doğrayın ve bakliyatı önceden haşlayın.", "Soğanı yağda yumuşatıp diğer malzemeleri 4 dakika kavurun.", "Bulguru ve sıcak suyu ekleyin; kapağı kapalı şekilde kısık ateşte suyunu çektirin.", "Ocaktan alıp 10 dakika dinlendirin ve çatalla havalandırın."], minutes: 35, detailed: false),
  GeneralRecipe(id: "p39a19_041", title: "Roka armut ceviz salatası", category: "Salatalar", ingredients: ["2 su bardağı tarifte adı geçen taze malzemeler", "1 su bardağı tarifte adı geçen haşlanmış tahıl veya bakliyat (varsa)", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu", "Tuz"], steps: ["Taze ürünleri akan suda iyice yıkayın ve süzün.", "Tarifte tahıl veya bakliyat varsa ayrı kapta pişirip tamamen soğutun.", "Tüm malzemeleri uygun boyda doğrayıp servis kasesinde birleştirin.", "Zeytinyağı ve limon suyunu ekleyip nazikçe harmanlayın."], minutes: 20, detailed: false),
  GeneralRecipe(id: "p39a19_051", title: "Köz biberli ricottalı makarna", category: "Makarnalar", ingredients: ["200 g kuru makarna", "200 g tarifte belirtilen ek malzeme", "2 yemek kaşığı zeytinyağı", "1 diş sarımsak", "Yarım çay bardağı makarna haşlama suyu"], steps: ["Makarnayı paketindeki süreye göre bol suda haşlayın; biraz haşlama suyu ayırın.", "Tarifte belirtilen sebzeleri temizleyip doğrayın; gerekiyorsa ön pişirme yapın.", "Sarımsağı yağda kısa süre çevirip ek malzemeleri yumuşayana kadar soteleyin.", "Makarnayı ve ayırdığınız suyu ekleyip sosla karıştırarak sıcak servis edin."], minutes: 30, detailed: false),
  GeneralRecipe(id: "p39a19_061", title: "Ispanaklı lorlu omlet", category: "Kahvaltılıklar", ingredients: ["3 yumurta", "1 su bardağı tarifte adı geçen sebze", "50 g tarifte adı geçen peynir (varsa)", "1 yemek kaşığı zeytinyağı", "Tuz"], steps: ["Sebzeleri yıkayıp ince doğrayın; patates veya brokoli gibi sert sebzeleri önceden yumuşatın.", "Yumurtaları bir kasede çırpıp varsa peyniri ekleyin.", "Sebzeleri yağlanmış tavada soteleyip yumurtayı üzerine dökün.", "Kısık ateşte her iki yüzü de tamamen pişene kadar pişirin."], minutes: 20, detailed: false),
  GeneralRecipe(id: "p39a19_071", title: "Limonlu dereotlu levrek fırın balık", category: "Balık ve deniz ürünleri", ingredients: ["2 adet temizlenmiş balık filetosu (toplam yaklaşık 350–400 g)", "1 su bardağı tarifte belirtilen sebze veya garnitür", "2 yemek kaşığı zeytinyağı", "1 yemek kaşığı limon suyu", "Tuz ve karabiber"], steps: ["Fırını 190°C’ye ısıtın; sebzeleri ince doğrayın.", "Balığı yağlı kağıtlı tepsiye yerleştirip sebzeleri yanına yayın.", "Yağ, limon ve baharatları ekleyin; kalın parçalar için süreyi ayarlayın.", "Balık opaklaşıp kolayca ayrılana ve güvenli iç sıcaklığına (63°C) ulaşana kadar pişirin."], minutes: 35, detailed: false),
  GeneralRecipe(id: "p39a19_081", title: "Mantarlı arpacık soğanlı dana güveç", category: "Et yemekleri", ingredients: ["400 g kuşbaşı dana eti", "250 g tarifte belirtilen sebzeler", "1 soğan", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "2 su bardağı sıcak su"], steps: ["Eti kızgın tencerede yağla mühürleyin; soğanı ekleyip kavurun.", "Tarifteki sebzeleri temizleyip iri küpler halinde doğrayın; bakliyatı önceden haşlayın.", "Salçayı ve sıcak suyu ekleyip et yumuşayana kadar kapağı kapalı kısık ateşte pişirin.", "Sebzeleri pişme sürelerine göre ekleyip tamamı yumuşayana kadar pişirmeyi sürdürün."], minutes: 95, detailed: false),
  GeneralRecipe(id: "p39a19_091", title: "Köz patlıcanlı sarımsaklı yoğurtlu meze", category: "Mezeler", ingredients: ["1 su bardağı koyu yoğurt", "200 g tarifte adı geçen sebze", "1 yemek kaşığı zeytinyağı", "1 küçük diş sarımsak (isteğe bağlı)", "Tuz"], steps: ["Sebzeyi yıkayın; çiğ yenmeyenleri uygun yöntemle pişirip tamamen soğutun.", "Sebzeyi ince doğrayın veya rendeleyin ve fazla suyunu süzün.", "Yoğurdu yağ ve istenen aromalarla çırpıp sebzeyi ekleyin.", "Soğuk olarak servis edin; artan mezeyi buzdolabında saklayın."], minutes: 25, detailed: false),
  GeneralRecipe(id: "p39a19_101", title: "Elmalı tarçınlı yulaflı fırın tatlısı", category: "Tatlılar", ingredients: ["2 su bardağı tarifte belirtilen meyve", "Yarım su bardağı yulaf ezmesi", "2 yemek kaşığı ince çekilmiş ceviz veya badem", "1 yemek kaşığı tereyağı", "1 çay kaşığı tarçın (isteğe bağlı)"], steps: ["Fırını 180°C’ye ısıtın; meyveleri yıkayıp çekirdeklerini çıkarın.", "Meyveleri küçük doğrayıp hafif yağlanmış fırın kabına yayın.", "Yulaf, kuruyemiş ve tereyağını ufalayarak karıştırıp üzerine serpin.", "Meyveler yumuşayıp üstü kızarana kadar yaklaşık 25–30 dakika pişirin."], minutes: 40, detailed: false),
  GeneralRecipe(id: "p39a19_111", title: "Ispanaklı lorlu börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g ıspanak", "120 g lor peyniri", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Ispanağı yıkayıp doğrayın; tavada suyunu çektirip soğutun.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a19_112", title: "Pırasalı beyaz peynirli börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g pırasa", "120 g beyaz peynir", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Pırasayı ince doğrayıp yağda 6-8 dakika yumuşatın ve soğutun.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a19_113", title: "Patatesli dereotlu börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g patates", "120 g beyaz peynir ve 2 yemek kaşığı dereotu", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Patatesleri haşlayıp ezin; ince kıyılmış dereotuyla karıştırın.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a19_114", title: "Mantarlı kaşarlı börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g mantar", "120 g rendelenmiş kaşar", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Mantarları ince doğrayıp tavada suyunu tamamen çektirin; soğutun.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a19_115", title: "Kabaklı naneli börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g kabak", "120 g lor ve 1 tatlı kaşığı kuru nane", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Kabağı rendeleyip suyunu sıkın; naneyle kısa süre soteleyip soğutun.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a19_116", title: "Patlıcanlı lorlu börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g patlıcan", "120 g lor peyniri", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Patlıcanı küçük küp doğrayıp yağda yumuşayana kadar soteleyin; soğutun.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a19_117", title: "Brokolili peynirli börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g brokoli", "120 g beyaz peynir", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Brokoliyi küçük doğrayıp 5 dakika buharda pişirin; süzerek soğutun.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a19_118", title: "Havuçlu çökelekli börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g havuç", "120 g çökelek", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Havucu rendeleyip tavada 4 dakika soteleyin; soğutun.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a19_119", title: "Köz biberli lorlu börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g közlenmiş kırmızı biber", "120 g lor peyniri", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Közlenmiş biberi süzüp ince doğrayın; fazla suyunu alın.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a19_120", title: "Pazılı beyaz peynirli börek", category: "Hamur işleri", ingredients: ["3 adet yufka", "250 g pazı", "120 g beyaz peynir", "1 yumurta", "Yarım su bardağı süt", "2 yemek kaşığı zeytinyağı"], steps: ["Fırını 190°C’ye ısıtın. Pazıyı yıkayıp doğrayın; tavada suyunu çektirip soğutun.", "Hazırladığınız sebzeyi peynirle harmanlayın; yumurta, süt ve zeytinyağını ayrı kapta çırpın.", "Yufkaları sostan hafifçe sürerek katlayın; iç harcı eşit paylaştırıp rulo yapın ve tepsiye dizin.", "Kalan sosu üzerine sürün; 30-35 dakika üzeri altın rengi olana kadar pişirin."], minutes: 55),
  GeneralRecipe(id: "p39a19_121", title: "Nohutlu ıspanaklı bakliyat yemeği", category: "Bakliyat yemekleri", ingredients: ["2 su bardağı önceden haşlanmış tarifteki bakliyat", "250 g tarifte belirtilen sebze", "1 soğan", "1 yemek kaşığı domates salçası", "2 yemek kaşığı zeytinyağı", "1 su bardağı sıcak su"], steps: ["Bakliyatı önceden ıslatıp tamamen yumuşayana kadar haşlayın.", "Soğanı yağda kavurun, salçayı ekleyip kokusu çıkana kadar çevirin.", "Doğranmış sebzeyi, bakliyatı ve suyu ekleyin.", "Sebzeler tamamen yumuşayana ve lezzetler birleşene kadar kısık ateşte pişirin."], minutes: 50, detailed: false),
  GeneralRecipe(id: "p39a19_131", title: "Kabaklı patatesli fırın tepsi", category: "Sebze yemekleri", ingredients: ["400 g tarifte belirtilen sebzeler", "1 küçük soğan", "2 yemek kaşığı zeytinyağı", "1 tatlı kaşığı kekik", "Yarım çay bardağı su", "Tuz"], steps: ["Fırını 200°C’ye ısıtın; sebzeleri eşit büyüklükte doğrayın.", "Sebzeleri yağ, kekik ve tuzla karıştırıp tepsiye tek kat halinde yayın.", "Sert sebzeleri küçük doğrayın veya kısa süre ön haşlayın; tepsiye suyu ekleyin.", "Sebzeler yumuşayıp kenarları kızarana kadar 30–40 dakika pişirin."], minutes: 50, detailed: false),
  GeneralRecipe(id: "p39a19_141", title: "Muzlu çilekli smoothie", category: "İçecekler", ingredients: ["1 küçük muz", "5 çilek", "1 su bardağı süt", "3–4 buz küpü (isteğe bağlı)"], steps: ["Çilekleri yıkayıp saplarını ayıklayın; muzu soyup dilimleyin.", "Muz, çilek ve sütü blendera alın.", "Pürüzsüz olana kadar 30–45 saniye karıştırın.", "İsterseniz buz ekleyip yeniden kısa süre karıştırın ve hemen servis edin."], minutes: 10),
  GeneralRecipe(id: "p39a19_142", title: "Yaban mersinli yoğurtlu smoothie", category: "İçecekler", ingredients: ["Yarım su bardağı yaban mersini", "1 su bardağı yoğurt", "3–4 buz küpü (isteğe bağlı)"], steps: ["Yaban mersinlerini yıkayıp süzün.", "Yaban mersinlerini yoğurtla birlikte blendera alın.", "Kıvam pürüzsüz olana kadar karıştırın; çok koyuysa az miktarda içme suyu ekleyin.", "İsteğe bağlı buzla soğuk servis edin."], minutes: 10),
  GeneralRecipe(id: "p39a19_143", title: "Şeftalili yulaflı smoothie", category: "İçecekler", ingredients: ["1 olgun şeftali", "2 yemek kaşığı yulaf", "1 su bardağı süt", "3–4 buz küpü (isteğe bağlı)"], steps: ["Şeftaliyi yıkayıp çekirdeğini çıkarın ve dilimleyin.", "Yulafı sütle birlikte blendera koyup 20 saniye karıştırın.", "Şeftaliyi ekleyip pürüzsüz olana kadar çekin.", "İsteğe bağlı buz ekleyerek hemen servis edin."], minutes: 10),
  GeneralRecipe(id: "p39a19_144", title: "Mangolu kefirli smoothie", category: "İçecekler", ingredients: ["Yarım olgun mango", "1 su bardağı kefir", "3–4 buz küpü (isteğe bağlı)"], steps: ["Mangonun kabuğunu ve çekirdeğini ayırıp meyveyi doğrayın.", "Mango parçaları ile kefiri blendera alın.", "Pürüzsüz bir kıvam elde edene kadar 30–45 saniye karıştırın.", "İsterseniz buz ekleyip soğuk servis edin."], minutes: 10),
  GeneralRecipe(id: "p39a19_145", title: "Armutlu tarçınlı smoothie", category: "İçecekler", ingredients: ["1 armut", "Yarım çay kaşığı tarçın", "1 su bardağı süt", "3–4 buz küpü (isteğe bağlı)"], steps: ["Armudu yıkayın, çekirdeğini çıkarın ve küçük parçalara ayırın.", "Armut, süt ve tarçını blendera ekleyin.", "Armut tamamen parçalanana kadar karıştırın.", "İsteğe bağlı buz ekleyip bekletmeden servis edin."], minutes: 10),
  GeneralRecipe(id: "p39a19_146", title: "Elmalı yulaflı smoothie", category: "İçecekler", ingredients: ["1 elma", "2 yemek kaşığı yulaf", "1 su bardağı süt", "3–4 buz küpü (isteğe bağlı)"], steps: ["Elmayı yıkayın, çekirdeğini çıkarın ve doğrayın.", "Yulafı sütle blenderda kısa süre karıştırın.", "Elma parçalarını ekleyip pürüzsüz olana kadar çekin.", "İsteğe bağlı buz ekleyin ve hemen servis edin."], minutes: 10),
  GeneralRecipe(id: "p39a19_147", title: "Ananaslı naneli smoothie", category: "İçecekler", ingredients: ["1 su bardağı doğranmış ananas", "4 yaprak nane", "1 su bardağı su", "3–4 buz küpü (isteğe bağlı)"], steps: ["Ananas parçalarını hazırlayın; taze naneyi yıkayın.", "Ananası ve suyu blenderda karıştırın.", "Nane yapraklarını ekleyip 10–15 saniye daha çekin.", "İsteğe bağlı buzla soğuk servis edin."], minutes: 10),
  GeneralRecipe(id: "p39a19_148", title: "Böğürtlenli muzlu smoothie", category: "İçecekler", ingredients: ["Yarım su bardağı böğürtlen", "1 küçük muz", "1 su bardağı süt", "3–4 buz küpü (isteğe bağlı)"], steps: ["Böğürtlenleri yıkayıp süzün, muzu soyun.", "Böğürtlen, muz ve sütü blendera alın.", "Pürüzsüz olana kadar 30–45 saniye karıştırın.", "İsterseniz buz ekleyip hemen servis edin."], minutes: 10),
  GeneralRecipe(id: "p39a19_149", title: "Kayısılı yoğurtlu smoothie", category: "İçecekler", ingredients: ["3 olgun kayısı", "1 su bardağı yoğurt", "3–4 buz küpü (isteğe bağlı)"], steps: ["Kayısıları yıkayın, çekirdeklerini çıkarıp doğrayın.", "Kayısı ve yoğurdu blendera alın.", "Homojen ve akışkan bir kıvam elde edene kadar karıştırın.", "İsteğe bağlı buz ekleyip soğuk servis edin."], minutes: 10),
  GeneralRecipe(id: "p39a19_150", title: "Kivili muzlu smoothie", category: "İçecekler", ingredients: ["2 kivi", "1 küçük muz", "1 su bardağı süt", "3–4 buz küpü (isteğe bağlı)"], steps: ["Kivileri soyup dilimleyin, muzu soyun.", "Kivi, muz ve sütü blendera ekleyin.", "Pürüzsüz olana kadar 30–45 saniye karıştırın.", "İsteğe bağlı buzla bekletmeden servis edin."], minutes: 10),
];
